window.__D("text/maamarei-admur-hazaken/c015",{"p":[[2101920083,"בהם לשון רינה. וזה אינו מובן שח\"ת הוא תמיד בחוץ להחיות בי\"ע מאין ליש שהוא חכ' שבדיבור כנ\"ל. והענין הוא שחכמות לא קאי על חכ' שבדיבור כו' רק על בחי' חכ' שבתורה שירדה למטה לברר בירורים שזהו נק' ח\"ת, וזהו חכמות בחוץ תרונה ב' חכמות ח\"ת שהוא בחי' חכ' שבתורה לברר בירורי' וח\"ע שהוא בחי' הכח לבירורי' שנמשך מלמעלה מבחי' פנימי' אין ומקור החכ' כמ\"ש הנה ה' יוצא ממקומו כו' לברר בירורים כו', אורייתא מחכ' נפקת כנ\"ל, וב' חכמות הנ\"ל שהן בחוץ לברר בי\"ע אז תרונה. וענין רינה הוא כמ\"ש שמחה<sup data-n=\"208\">38</sup> בצפרא רננה ברמשא כי הנה בחי' שיר ושמחה בצפרא הוא בחי' העלא' כמ\"ש כל<sup data-n=\"209\">39</sup> בעלי השיר יוצאי' בשיר כו' והלוים שהם מבחי' גבורות אמרו<sup data-n=\"210\">40</sup> שיר על כל מעלה ומעלה של ט\"ו מעלות שהוא בחי' העלא', וכן מלאכים אומרים שירה בכל בוקר מהשגת אלקו' שבהם ובטלים לגבי אוא\"ס המהווה אותם כו', אבל בחי' רינה הוא בחי' אחרת והוא הבא לאחר יאוש שמייאש מאיזה דבר ואח\"כ נמצא הדבר ההוא אז שייך רינה, והוא כמ\"ש בא<sup data-n=\"211\">41</sup> יבא ברינה נושא אלומותיו, והוא בחי' רננה ברמשא שכל היום היו בבחי' בירורים והי' אפשר שישארו למטה כו' והוא עד\"מ כמו שאדם זורע שדהו בתבואו' שאינו יודע אם יצמחו התבואות או אפשר ירקבו הזרעים ולא יצמח כלום, או כמו שאדם מפזר מעות בשביל מו\"מ שאינו יודע אם ירויח או יפסיד, ממילא אח\"כ כשיצמח התבואה מגרעין אחד כמה שיבלות וכן כשמרויח במו\"מ אז שייך רינה, וכמו\"כ יובן בבחי' החכ' שבתורה שירדה בע\"ש לברר בירורי' שהוא בחי' ירידה למטה בנוגה כו' שהוא בחי' שאפשר שישאר למטה ולא יכול לברר, ממילא אח\"כ לאחר תשלום כל הבירורים אז שייך בחי' רנה, וזהו בא יבא ברנה נושא אלומותיו, כי אלומותיו הוא בחי' בירורים כמ\"ש והנה<sup data-n=\"212\">42</sup> אנחנו מאלמים אלומים כו' שהוא בחי' הבירורי' וביוסף כתי' קמה אלומתי שנתעלה למעלה וכל האלומות של השבטים משתחווים לאלומתי כו', וכשהוא נושא אלומותיו והוא בחי' לאחר כל הבירורי' אז בא יבא ברנה, וזהו שמחה בצפרא רננה ברמשא שהוא בחי' הבירורי' שירדה החכ' ונתלבשה בבחי' חושך דנוג\"ה כנ\"ל. וזהו שיר<sup data-n=\"213\">43</sup> השירים אשר לשלמה, כי יש כמה בחי' שירים שיר<sup data-n=\"214\">44</sup> פשוט שיר כפול שיר משולש שיר מרובע כו'. שיר פשוט הוא בכתר שיר כפול הוא בחו\"ב כו' שהוא בחי' שלא ירדה ונתלבשה למטה בבי\"ע, ובחי' שיר השירי' הוא בחי' שירדה למטה לברר בירורי' והוא נתעלה למעלה לאחר כל הבירורים וד\"ל. וזהו חכמות בחוץ תרונה, כשהם בחוץ דהיינו לברר בירורים לאהפכא כו' ואז לאחר תשלום כל הבירורים כשיתעלו למעלה אז הוא בחי' רנה כנ\"ל וד\"ל.",[["208","38","<b>שמחה בצפרא רננה ברמשא</b>: זח\"א רכט, ב."],["209","39","<b>כל בעלי השיר יוצאי' בשיר</b>: שבת נא, ב. וראה עוד ע\"ז במ\"מ למאמר שלפני\"ז."],["210","40","<b>אמרו שיר על כל מעלה ומעלה של ט\"ו מעלות</b>: ראה סוכה נא, ב."],["211","41","<b>בא יבא ברינה</b>: תהלים קכו, ו."],["212","42","<b>והנה אנחנו מאלמים אלומים . . קמה אלומתי</b>: וישב לז, ז. וראה תו\"א וישב כח, א."],["213","43","<b>שיר השירים</b>: שה\"ש א, א."],["214","44","<b>שיר פשוט שיר כפול</b>: ראה זח\"א רכז, ב. תקו\"ז בהקדמה ג, א. אשל אברהם (פיורדא תס\"א) בתחילתו. ובכ\"מ."]]],[2101920084,"<b>וזהו</b> מה שמבואר במדרש לעתיד הקב\"ה עושה כנפיים לצדיקים ושטין ע\"פ המים. כי הנה בחי' כנפיים הוא בחי' נפרד מהגוף ואין זו בתולדה רק הוא נעשה מהמזון כמ\"ש בגרים<sup data-n=\"215\">45</sup> שהקריב' תחת כנפי השכינה, לפי שהגרים הוא בחי' העלאה מע' שרים ואינם יכולים להעלות אלא תחת כנפי השכינה שהוא ג\"כ מבחי' הבירורים דתוהו כו' וד\"ל. וכמו\"כ בנשמו' הצדיקי' שהיו למטה בעוה\"ז לברר בירורי', ע\"י בחי' הבירורים נעשה להם בחי' כנפיים ושטין על פני המים דוקא, כי הנה בחי' מים הוא בחי' חכמה ונשמת משה הוא מבחי' חכ' כמ\"ש כי מן המים משיתיהו כו' שהי' מבחי' פנימי' חכ' שהחכ' הי' מקיפו והוא הי' מוקף בתוך החכ' כולה, וכן נשמת רב<sup data-n=\"216\">46</sup> המנונא סבא נונא בימא רבא כו' דשאט ימא רבא בשיטא אחת כו' וד\"ל, שהי' מוקף בתוך ים החכ' כולא והיא היתה מכסה עליו כו', אבל בחי' נשמות הצדיקים לעתיד הוא ששטין ע\"פ המים למעלה ממקור החכ', שהם מקיפי' את כל החכ' של תורה מחמת שהם למעלה ממקור החכ' ממילא מקיפים את כל החכמה כו', וכ\"ז נעשה ע\"י הבירורי' שהיו מבררים בעוה\"ז בחי' ע\"ש וק\"נ כו' וד\"ל.\n<b>אך</b> יש להבין מפני מה כתי' כנפיים כנשרים כו', והראי' שמביא הפסוק יעלו אבר כנשרים כו'. אך הענין הוא דכתי' דרך<sup data-n=\"217\">47</sup> הנשר בשמים פי' משום דהנשר יש לו כח בכנפיו להגביה גופו למעלה מעלה משאר עופות שאינו מרגיש כבדו' ומשאו' גופו בכן יכול להגביה עצמו מאד ויכול ג\"כ להשפיל א\"ע למטה מטה. והנה מצינו שהנשר רחמן על בניו ושומרן בב' אופנים, הא' כשמתיירא שלא יזרקו עליהם חיצים אזי נושאם ע\"ג כנפיו ומגביה אותם למעלה מעלה כמ\"ש ישאהו<sup data-n=\"218\">48</sup> על אברתו, והאופן הב' כשמתיירא שלא יקדור החמה עליהם יותר מדאי אזי הוא מוריד כנפיו למטה ונושאן תחת כנפיו כמ\"ש על גוזליו ירחף כו'. וכמו\"כ יובן למעלה בבחי' פני נשר שבמרכבה שהוא בחי' רחמנות כמ\"ש פני ארי' ופני שור ופני<sup data-n=\"219\">49</sup> נשר לארבעתן כו' שהוא בחי' קו אמצעי שיורד למטה מטה ויכול להעלות למעלה מעלה כמ\"ש והבריח<sup data-n=\"220\">50</sup> התיכון מבריח מן הקצה אל הקצה בחי' יעקב כו'. והענין יובן עד\"מ מבשרי אחזה בענין רחמנות למטה שאינו נופל לשון רחמנות רק על עני ואביון שהוא בשפל המדריגה ירחם עליו, וגם על המרחם לא שייך לשון רחמים אלא דוקא כשהוא מרומם בתכלית רוממות המדריגה כמו ד\"מ מלך גדול שהוא מרומם בתכלית אינו יכול לסבול היפוכו יותר מאדם אחר, מפני",[["215","45","<b>בגרים שהקריב' תחת כנפי השכינה</b>: ראה סנהדרין צו, ב. זח\"א יג, א. ובכ\"מ."],["216","46","<b>רב המנונא סבא נונא בימא רבא כו' דשאט ימא רבא בשיטא אחת</b>: ראה זח\"א ו, א. ס' מאמרי אדה\"ז עה\"ת ח\"א ע' רנו. על מארז\"ל ע' קמו. ובכ\"מ."],["217","47","<b>דרך הנשר בשמים</b>: משלי ל, יט."],["218","48","<b>ישאהו על אברתו . . על גוזליו ירחף</b>: האזינו לב, יא."],["219","49","<b>ופני נשר לארבעתן</b>: יחזקאל א, י."],["220","50","<b>והבריח התיכון מבריח מן הקצה אל הקצה בחי' יעקב</b>: תרומה כו, כח. ראה זח\"ב קעה, ב. קעו, א. זח\"א א, ב. אוה\"ת ויחי כרך ב' שפה, ב."]]],[2101920085,"שהמלך בתכלית הרוממות אינו יכול לסבול על העני ונכאה לבב שהוא בתכלית השפלות שהוא רחוק מהמלך מאד, אבל איש עשיר הגם שהוא שפל לגבי המלך אין שייך לומר לשון רחמנות גדולים עליו שהוא אינו רחוק כ\"כ מהמלך וכן איש עשיר על עני אין שייך לשון רחמנות גדולים בו שהעשיר אינו רחוק כ\"כ מן העני כמו המלך.\n<b>ובזה</b> יובן הענין מ\"ש למעלה<sup data-n=\"221\">51</sup> עד אין קץ למטה עד אין תכלית, כי מבחי' קו האמצעי שהוא בחי' רחמים רבים נמשך בחי' רחמנות מחמת שהוא מבריח מן הקצה אל הקצה דוקא על מי שהוא בשפל המדריגה, מחי' מתים ברחמים רבים מחמת שהם מתים בתכלית השפלות אז שייך עליהם רח\"ר כנ\"ל. וכן יובן הענין מה שבשעת מ\"ת כתי' ואשא<sup data-n=\"222\">52</sup> אתכם על כנפי נשרים ואביא אתכם אלי, אלי דוקא אנכי מי שאנכי כו'. ובמקום אחר נת' שהוא מכסה וחופף עליהם כמו שאנו אומרי' ופרוס<sup data-n=\"223\">53</sup> עלינו סוכת שלומיך בחי' מקיפי' דאימא מחמת ב' רחמנו' הנ\"ל בב' מדריגו' כנ\"ל אזי שומרם בכל מה דאפשר, וביצ\"מ שהיו משוקעים בקליפו' בתכלית הטומאה לא הניחם מלהגן עליהם, וכמו\"כ בכל שאר זמנים שצריך לשמור להם מפני יניקת החיצוני' נמשך עליהם בחי' מקיפי' דאימא להגן עליהם כו'. וכ\"ז צריכים לב' שמירות בב' מדריגות הנ\"ל בזמן הבירורי' שעדיין לא נתברר הרע דקליפו' צריך לנשאו' ולהגן עליהם אבל לאחר תשלום כל הבירורי' אז יהי' להם כנפים מצד עצמם מבחי' הבירורי' כנ\"ל והוא ד\"מ כשהבנים קטנים שקודם שיכולים לילך בעצמם אזי צריך אביהם לעזור אותם מן הצד ולתומכם ואם לא יכולי' לילך בעצמם נוטלם על זרועותיו, אבל כשיגדלו אזי בן בדומה לאב ויש להם לעצמן רגליים וכח להלך, וכן בנשר ג\"כ כשיגדלו הבנים שלו אזי יש להם כנפי' לעצמן מבחי' מזון כנ\"ל. וכמו\"כ יובן למעלה בבחי' אדם העליון מקור נש\"י שכל זמן הבירורי' אזי הם צריכים לבחי' עזר וסעד מבחי' כנפיים העליונים שבבחי' אדם עילאה כנ\"ל אבל לאחר תשלום כל הבירורי' שאז הבן דומה לאב שיש להן כנפיים מצד עצמן דהיינו מבחי' הבירורי' שלמטה ואינם צריכים לכנפיים של האב כו' כנ\"ל וד\"ל. וזהו עושה להם כנפיים כנ\"ל ושטין ע\"פ המים דוקא כנ\"ל וד\"ל.\n<b>יכול</b> יש להם צער ת\"ל וקוי ה' יחליפו כח, להבין פי' יכול יש להם צער, כי הנה בחי' מנוחה פי' כשהוא נח במקום א', אבל כשהוא נע ונד ממקום למקום אין שייך לשון מנוחה שאין זה מנוחה אלא פיזור הנפש, וכמו\"כ הוא בשכל שכ\"ז שהשכל על אופן א' דהיינו כולו לזכות, או שהוא מתחלה ועד סוף כולו לחוב ולא להיפך, שייך לשון מנוחה שהוא על צד ואופן א'. אבל כשמוכרח פעמים להלביש",[["221","51","<b>למעלה עד אין קץ למטה עד אין תכלית</b>: תקו\"ז סתנ\"ז. זוהר חדש לד, ב. ובכ\"מ."],["222","52","<b>ואשא אתכם על כנפי נשרים</b>: יתרו יט, ד."],["223","53","<b>ופרוס עלינו סוכת שלומיך</b>: נוסח ברכת השכיבנו."]]],[2101920086,"את השכל לזכות ולפעמים לחוב אזי הוא בחי' פיזור הנפש בחי' דבר והיפוכו ונק' בחי' צער. וכמו\"כ יובן הענין למעלה דהנה רוח<sup data-n=\"224\">54</sup> אייתי רוח ואמשיך רוח שע\"י העלאה גורם המשכה, וכמו בשבת שהיא בחי' נקודה אמצעית, שבששת ימי החול הי' בחי' בירורי' ובשעת קבלת שבת הוא בחי' העלאו' ואח\"כ נמשך המשכות לצורך ימי החול של שבוע אחרת, ובכללות יובן הענין בבחי' אלף הז', שית<sup data-n=\"225\">55</sup> אלפי שנין וחד חרוב כו' שהוא בחי' יום שכולו שבת שהוא בחי' עלי' אחר תשלום כל הבירורי' שעי\"ז יהי' גורם אח\"כ המשכה שיהי' שמים<sup data-n=\"226\">56</sup> חדשים וארץ חדשה כמ\"ש שמים חדשים וארץ חדשה, ותורה<sup data-n=\"227\">57</sup> חדשה מאתי תצא כו', כמ\"ש בספר<sup data-n=\"228\">58</sup> התמונה שיש שבעה שמיטות כו' ושמיטה הזאת היא שמיטת הפחד והראי' שבו נחרבו הבתי מקדשים, אבל לאחר תשלום כל הבירורים יהי' נמשך אח\"כ באופן משובח יותר מכמו של עכשיו דהיינו שיהי' שמיטת הת\"ת כו', וממילא יובן שיהי' בחי' העלאו' והמשכו' כמ\"ש צדיקים<sup data-n=\"229\">59</sup> אין להם מנוחה לא בעוה\"ב כו' שנאמר ילכו מחיל אל חיל בחי' עלי' ובחי' המשכות, יכול יש להם צער ת\"ל וקוי ה' יחליפו כח פי' יחליפו שיהי' להם כח חדש שלא הי' בבחי' העלאה שמתחלה ולא נתייגע כלל, וע\"כ בכח זה החדש לא ייעפו ולא ייגעו כלל, ומהו התחלפות הכח שיהי' להם בחי' וקוי ה', בחי' ביטול עצמי' שאינו מרגיש עצמו שבדעתו שהוא אינו עושה כלום רק שמה שהוא עושה הוא ע\"י שנותנים לו מלמעלה מאחר שיהי' לאחר תשלום כל הבירורים שיתעלה הכל למעלה ויהי' בבחי' עצמיות ושם אין חילוק כלל בין בחי' העלאה ובין בחי' המשכה, כמ\"ש שגיא<sup data-n=\"230\">60</sup> כח רב כח כו', ועי\"ז ויעלו אבר כנשרים כמו שהנשר אינו מרגיש הגבהת גופו מעלה מעלה והשפלת גופו למטה מטה כנ\"ל כו' וד\"ל.",[["224","54","<b>רוח אייתי רוח ואמשיך רוח</b>: ראה זח\"ב קסב, ב."],["225","55","<b>שית אלפי שנין וחד חרוב</b>: ר\"ה לא, א."],["226","56","<b>שמים חדשים וארץ חדשה</b>: ישעי' סה, יז. סו, כב."],["227","57","<b>ותורה חדשה מאתי תצא</b>: ויק\"ר פי\"ג, ג — ע\"פ ישעי' נא, ד."],["228","58","<b>בספר התמונה שיש שבעה שמיטות</b>: בהקדמה לתמונה ג'. וראה תו\"א שמות נא, ד. תו\"ח שמות (הוצאה החדשה) ח\"א מג, א. ח\"ב רעט, א. וש\"נ."],["229","59","<b>צדיקים אין להם מנוחה . . ילכו מחיל אל חיל</b>: ברכות סד, א. [בגמ' שם: ת\"ח. אבל הגי' ”צדיקים\" מובא בכ\"מ — ראה בהמ\"מ בלקו\"ש חט\"ו ע' 137. ובס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' מו]. תהלים פד, ח."],["230","60","<b>שגיא כח רב כח</b>: ע\"פ איוב לז, כג."]]],[2101920087,"<h3>ביום השמיני עצרת</h3>\n<b>ביום</b><sup data-n=\"231\">1</sup> השמיני<sup data-n=\"232\">2</sup> עצרת תהי' לכם, להבין שייכות השמחה מהתורה בשמ\"ע דוקא הלא מ\"ת הי' בשבועות והי' צ\"ל אז שמחה זו. אך הענין כי לוחות ראשונות הם שניתנו בשבועות ולוחו' אחרונות ניתנו ביוכ\"פ ועל לוחות אלו הוא שנקבעה השמחה בשמ\"ע. והענין כי יש ב' בחי' צדיקים ובע\"ת, והנה לוחות ראשונות הם כנגד בחי' צדיקים ולוחות אחרונות הם כנגד בחי' בע\"ת ולכן ניתנו ביוכ\"פ שהוא בחי' תשובה<sup data-n=\"233\">3</sup> בחילא יתיר ממעמקי'<sup data-n=\"234\">4</sup> קראתיך הוי', שמעה בקולי, ועי\"ז לפני<sup data-n=\"235\">5</sup> הוי' תטהרו ואז נעשי'<sup data-n=\"236\">6</sup> לו זדונות כזכיות וה\"ז בחי' זכיות משוני' משל הצדיקים, וע\"ז הוא שנקבע להיו' שמח\"ת כי השמחה היא דוקא מקירוב הבא אחר ריחוק כמשל בן מלך שהי' בשבי' ונתרחק מאביו המלך ובצאתו חפשי ובא לאור פני המלך אזי ישמחו שניהם כו' משא\"כ תענוג<sup data-n=\"237\">7</sup> תמידי אינו תענוג, וכך סוכות הוא זמן שמחתינו ב' שמחות ישמח<sup data-n=\"238\">8</sup> ה' במעשיו וישמח ישראל בעושיו מן הקירוב שנתקרבו אליו ית' ע\"י בחי' תשוב' ביוכ\"פ אחר הריחוק שהי' בכל השנה כו'.\n<b>והנה</b> בחי' התורה נק' שלום כמ\"ש או<sup data-n=\"239\">9</sup> יחזיק במעוזי יעשה שלום לי שלום יעשה לי וארז\"ל כל העוסק בתורה משים שלום בפשמ\"ע ובפשמ\"ט. וענין השלום",[["231","1","<b>ביום השמע\"צ</b>: המאמר כאן הוא הנחת כ\"ק אדמו\"ר הצ\"צ (ונדפס כאן מגוכי\"ק). וראה לקמן נוסח שני (באריכות יותר, וע\"ש בהמ\"מ). ונמצא תוכן של איזה ענינים מהמאמר (בשינויים ובאריכות) בס' מאמרי אדהאמ\"צ דברים ח\"ד ע' א'רפג. ובשינויים והגהות מהצ\"צ באוה\"ת שמע\"צ ע' א'תשעט ואילך (ושם בלי הביאור שנדפס לקמן).\nוראה מעניני המאמר בסה\"מ תרל\"ג ח\"ב ע' תקלו ואילך. סה\"מ תר\"מ ח\"ב ע' תקפ ואילך. וד\"ה ביום השמע\"צ בסה\"מ תרמ\"ח ע' קעט ואילך. עזר\"ת ע' לה ואילך. וראה גם אוה\"ת שמע\"צ (כרך ה) ע' ב'קמט ואילך. סה\"מ עטר\"ת (הוצאת תשמ\"ח) ע' תרסג ואילך. סה\"מ תרפ\"ז ע' לו ואילך. תרצ\"ט ע' 62 ואילך. וראה ד\"ה בראשית ברא: בסה\"מ תרצ\"א (נמצא בדפוס). וסה\"מ תש\"ה ע' 67 ואילך. וראה עוד לקמן במ\"מ להביאור.\nמאמר זה נזכר גם בכ\"מ באוה\"ת: וירא כרך ד' תשמא, א. וישב רסח, ב. ויחי שעב, א. יתרו ע' תתא. משפטים ע' א'קיב. א'קנח. תשא ע' א'תתכד. במדבר כרך ה' ע' א'תקצו. א'תרנה. בלק ע' תתקנז. ואתחנן כרך ו' ע' ב'יח. נצבים ע' א'רסג. נ\"ך כרך ב' ע' תשפח. אוה\"ת ענינים ע' רס. ביאוה\"ז ע' קיד וע' שס. דרמ\"צ סד, ב. קיצורים והערות לתניא ע' קטו. תר\"ל ע' ב. סה\"מ תרל\"ו ח\"ב ע' תקצז [שם: ע' בד\"ה בהשע\"צ שלא נדפס וביאורו בענין קריאת התורה והיקיפה סביב הבימה בס' הצעטל' דתקע\"ב בערך. וקאי על הכת\"י שממנו נדפס המאמר כאן]. המשך וככה תרל\"ז ע' טז. תרנ\"ט ע' ז."],["232","2","<b>ביום השמע\"צ תהי' לכם</b>: פינחס כט, לה."],["233","3","<b>תשובה בחילא יתיר</b>: זח\"א קכט, ב."],["234","4","<b>ממעמקי' קראתיך</b>: תהלים קל, א."],["235","5","<b>לפני הוי' תטהרו</b>: אחרי טז, ל."],["236","6","<b>נעשי' לו זדונות כזכיות</b>: יומא פו, א."],["237","7","<b>תענוג תמידי אינו תענוג</b>: ראה כתר שם טוב סקכ\"א (ובמ\"מ שם, בכש\"ט הוצאת קה\"ת תשס\"ד). ס' מאמרי אדהאמ\"צ קונטרסים ע' תקסח (ובמ\"מ שם)."],["238","8","<b>ישמח ה' במעשיו וישמח ישראל בעושיו</b>: תהלים קד, לא. קמט, ב. וראה לקו\"ת שמע\"צ פד, ג ואילך."],["239","9","<b>או יחזיק במעוזי . . כל העוסק בתורה</b>: ישעי' כז, ב. סנהדרין צט, ב. וראה גם תו\"א יתרו קט, ב. לקו\"ת מטות פו, ב. ובכ\"מ."]]],[2101920088,"הוא. כי הנה כתוב א' אומר בראשי'<sup data-n=\"240\">10</sup> ברא את השמים ואת הארץ הקדים שמים לארץ וכתוב א' אומר ביום עשות ארץ ושמים ארץ קדמה כו', שלכן גם כל המצות הם מעשיות דוקא שנשפלו בבחי' מעשה להיות זורע וחורש וקוצר כו' ואז עשר<sup data-n=\"241\">11</sup> תעשר ב' מעשרות היוצא שנה שנה כו', וכן הצדקה סתם היא מיגיע כפו, וכן עד\"ז שאר כל המצות ציצי' מצמר תפילין מקלף, שע\"י המעשה דוקא הוא שממשיכי' גלוי אא\"ס ב\"ה להיות רמ\"ח<sup data-n=\"242\">12</sup> איברין כו' וכמ\"ש ויניחהו<sup data-n=\"243\">13</sup> בג\"ע לעבדה זו רמ\"ח מ\"ע כו' וכמאמ' שכר<sup data-n=\"244\">14</sup> מצוה מצוה דפי' שהשכר מצוה והג\"ע נמשך ונולד מהמצוה עצמה. ולהבין זה איך כח המעשה גדול כ\"כ להיות עי\"ז המשכת אורות עליוני' עין<sup data-n=\"245\">15</sup> לא ראתה אלקי' זולתך.\nב) <b>אך</b> הענין כי הנה יש ב' בחי' ממכ\"ע וסכ\"ע, פי' בחי' ממכ\"ע הוא כמ\"ש לכבודי<sup data-n=\"246\">16</sup> בראתיו יצרתיו אף עשיתיו שהוא בחי' השתלשלות העולמות, והיינו בחי' ד' חיות שבמרכבה שישנם בכל עולם ועולם, מבחי' פני שור נמשכי' כל נפשות הבהמות ומבחי' פני ארי' נשמה לכל החיות ומפני נשר לכל העופו' ומבחי' פני אדם שבמרכבה לחסידי או\"ה, ויש עוד בחי' אדם והוא שעל<sup data-n=\"247\">17</sup> הכסא דמות כמראה אדם ממנו נמשכי' נשמות ישראל, ויש בחי' מרכבה זו בכל עולמו' בי\"ע מהעולם ועד העולם, נשמה מבריאה ורוח מיצי' כו', והכל לכבודי בראתיו שההשתלשלו' הוא מבחי' חכמה<sup data-n=\"248\">18</sup> הנק' כבוד ל\"ב נתיבות כידוע. אך כ\"ז הוא בחי' ההשתלשלו' בהתהו' בחי' ומדרגות רוחניי' כמו בחי' הנפשו' שאף נפש הבהמה רוחני' היא, וכן נפש הבהמי' שבאדם שנמשכ' מבחי' פני שור שבמרכבה, וכן הנפש האלקי' הרוחני' מבחי' פני אדם העליון שע\"ז נאמר לכבודי בראתיו שראשית<sup data-n=\"249\">19</sup> ההשתלשלו' הוא מבחי' חכמה כמ\"ש ראשי' חכמה וממנה נמשכי' בחי' ומדרגו' שלמטה ממנה והכל ברוחנית. אבל להיות התהוות בחי' עשיה הגשמיות א\"א להיות מבחי' השתלשלו', שעפ\"י השתלשלו' א\"א להיות התהוות הגשמיו' מן הרוחני' בשום אופן בעולם שאפי' יהי' כמה ריבוא רבבו' השתלשלות לא יועילו להיות התהוות בחי' גשמיות מהרוחניות. ולזאת א\"א להיות התהוות הגשמיו' כ\"א מבחי' שלמעלה מהשתלשלו' דהיינו עצמותו ית' שהוא כל יכול והיינו מבחי'",[["240","10","<b>בראשי' ברא . . ביום עשות . . ארץ קדמה</b>: בראשית א, א. ב, ד. חגיגה יב, א."],["241","11","<b>עשר תעשר</b>: פ' ראה יד, כב. ר\"ה ח, א."],["242","12","<b>רמ\"ח אברין</b>: ראה תקו\"ז תי' ל' (עד, א)."],["243","13","<b>ויניחהו בג\"ע לעבדה זו רמ\"ח מ\"ע</b>: בראשית ב, טו. זח\"א כז, א. זח\"ב קסה, ב. ובכ\"מ."],["244","14","<b>שכר מצוה מצוה דפי' שהשכר מצוה כו' מהמצוה עצמה</b>: אבות פ\"ד מ\"ב. תניא ר\"פ ל\"ז. פל\"ט (נב, ב). ובכ\"מ."],["245","15","<b>עין לא ראתה אלקי' זולתך</b>: ישעי' סד, ג."],["246","16","<b>לכבודי בראתיו יצרתיו</b>: ישעי' מג, ז."],["247","17","<b>שעל הכסא דמות כמראה אדם</b>: ע\"פ יחזקאל א, כו."],["248","18","<b>חכמה הנק' כבוד ל\"ב נתיבות כידוע</b>: ראה זח\"ג לג, א. פרדס שכ\"ג מע' כבוד. מאמרי אדהאמ\"צ בראשית ע' ג. וש\"נ."],["249","19","<b>שראשית ההשתלשלו' הוא מבחי' חכמה כמ\"ש ראשי' חכמה</b>: תהלים קיא, י. ראה זח\"א לא, ב. תקו\"ז ריש תי' ל'. פרדס ש\"ג פ\"ג. ע\"ח שער דרושי אבי\"ע (שמ\"ב) פ\"א."]]],[2101920089,"רצון העליון כל<sup data-n=\"250\">20</sup> אשר חפץ הוי' עשה, שמבחי' הרצון דוקא שהוא מבחי' סוכ\"ע נעשה התהוות העשי' גשמיו' משא\"כ בבחי' השתלשלו' לכבודי בראתיו כו' מבחי' חכמ' לא הי' באפשרי להיות התהוות הגשמיו', וז\"ס נעוץ<sup data-n=\"251\">21</sup> סופן בתחלתן סוף<sup data-n=\"252\">22</sup> מעשה במחשבה תחלה, ומה שארז\"ל אין<sup data-n=\"253\">23</sup> לך עשב שאין לו מזל כו' היינו שהמזל רק מגדלו ונותן בו טעם כמשל התהוות מתיקות התפוח מהכח הצומח שיש בארץ אבל גופו הוא באמת מלמעלה מבחי' סוכ\"ע. והגם שיש כמה ברואי' שוני' לאין קץ ותכלי' ואיך נמשך זה מאא\"ס ב\"ה שהוא אחדות פשוט להיו' בחי' רבוי כו', אך הענין לפי שההמשכה הוא ע\"י מדות חסד<sup data-n=\"254\">24</sup> דרועא ימינא כו' ומ\"מ אא\"ס ב\"ה ממש הוא העושה וכל הע\"ס הם כגרזן ביד החוצב בו שמ\"מ האדם חוצב כו', והיינו שהם בחי' כלים, ועי\"ז נעשה בחי' רבוי יהי אור מחסד וכן מים, ורקיע מבחי' גבורה כו'. וזהו ענין ארץ קדמה שבחי' ארץ שהיא בחי' התהוות גשמיו' קדמה לשמי' שהם רוחני' כי היא נמשכ' דוקא מבחי' סוכ\"ע כנ\"ל.\nג) <b>והנה</b> האדם יש בו ב' הבחי', שנפשותיו האלקי' והבהמי' הם מבחי' ממכ\"ע מפני אדם ושור וגופו שהוא גשמי שרשו מבחי' סוכ\"ע, ושיהיו יכולים להתחבר יחד הוא ע\"י התורה שהיא משים שלום בפשמ\"ט. והענין שיש בחי' רצון ובחי' חפץ והוא בחי' פנימי' הרצון שע\"ז נאמר וראית<sup data-n=\"255\">25</sup> את אחורי ופני לא יראו. והפי' כי הרצון הוא רק בחי' חיצוני', כמו כשרוצה לעדור ולחרוש שהתכלי' בזה הוא כדי להוציא פירות, וכן העוסק במו\"מ שהתכלי' הוא קיבוץ הממון להרויח אשר לזה יש לו חשקות והוא נק' חפץ בלה\"ק אבל גוף המעשה שחורש וקוצר וכן מה שעוסק במו\"מ הרצון שבזה הוא בחי' חיצוני' וזהו הנק' רצון כו'. וכך יובן ג\"כ למעלה שבחי' רצון העליון הוא בחי' סוכ\"ע שבחי' חכמ' נחשבת לגבי' כמו בחי' עשי' כמ\"ש כולם<sup data-n=\"256\">26</sup> בחכמ' עשית וע\"י רצון זה הוא שנתהוה בחי' הגשמיות. אבל בחי' חפץ הוא למעלה מזה והוא בחי' המצות שיש לו ית' חפץ בהן. והנה בתורה יש ב' הבחי', אורייתא<sup data-n=\"257\">27</sup> מחכמה נפקת בחי' ממכ\"ע, והרצון שבמצות בחי' סוכ\"ע, והתחברותם הוא ע\"י החפץ שבהם שהוא בחי' פנימי' החכמה [ופנימי' הרצון] כו' וכמ\"ש ה'<sup data-n=\"258\">28</sup> חפץ למען צדקו יגדיל תורה ויאדיר, שבחי' החפץ הוא בבחי' התורה אשר קדשנו במצותיו, אשר מל' אשרי שהוא דבר המאושר וטוב מבחי' חפץ כו', לכן העוסק בתורה משים שלום ומחבר סוכ\"ע וממכ\"ע בין בפשמ\"ע ובין בפשמ\"ט כנ\"ל.",[["250","20","<b>כל אשר חפץ ה' עשה</b>: תהלים קלה, ו."],["251","21","<b>נעוץ סופן בתחלתן</b>: ס' יצירה פ\"א מ\"ז."],["252","22","<b>סוף מעשה במחשבה תחילה</b>: פיוט לכה דודי."],["253","23","<b>אין לך עשב</b>: ראה ב\"ר פ\"י, ו. וראה מזה עוד לקמן אחר מאמר זה ד\"ה ביאור ענין שהמזל."],["254","24","<b>חסד דרועא ימינא</b>: תקו\"ז בהקדמה ד\"ה פתח אליהו (יז, א)."],["255","25","<b>וראית את אחורי</b>: תשא לג, כג."],["256","26","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["257","27","<b>אורייתא מחכמה נפקת</b>: זח\"ב סב, א. פה, א. קכא, א. ובכ\"מ."],["258","28","<b>ה' חפץ למען צדקו</b>: ישעי' מב, כא."]]],[2101920090,"ד) <b>והנה</b> ביום<sup data-n=\"259\">29</sup> חתונתו זה מ\"ת הגם שהוא משל גשמי אבל כן הוא באמת שכנ\"י נק' בשם כלה ואורייתא מחכמ' נפקת הוא כמשל הטפה שנמשכת מהמוח וכמו שבגשמיו' א\"א להיו' הטפה נמשכת אלא ע\"י הכלי והאדם ידע כו' והוא בחי' דעת התקשרו' שעי\"ז נמשך בחי' התורה דמחכמ' נפקת, דהיינו שלא יהי' ההתבוננו' בבחי' מחשבה בלבד אלא בתקיעת הדעת והתקשרו' ממש בחי' ביטול ואז אח\"כ כשעוסק בתורה ממשיך בחי' הטפה ומשים שלום כו'. והמשכת בחי' דעת זה לכל השנה שבכל יום ויום צ\"ל כן דע<sup data-n=\"260\">30</sup> את אלקי אביך ועי\"ז ועבדהו בלב מבחי' אחד יחו\"ע ויחו\"ת להיו' עי\"ז ואהבת<sup data-n=\"261\">31</sup> כו', ואח\"כ והיו הדברים כו' בחי' הטפה שמחכמה, הוא ע\"י הלולב ומיניו שבסוכו' שאז נמשך בחי' דעת זה בלב כללו' נשמו' ישראל, כי ד' מינים הם מבחי' ד' אותיות הוי\"ה שהוא מבחי' חכמ' ביטול שעי\"ז ממשיכי' בחי' הדעת. וגם לפי שהם בחי' גשמיו' דהיינו שנשפלה ההארה בבחי' צומח גשמי וארץ קדמה ששרש הגשמיו' מאד נעלה לכן עי\"ז דוקא ממשיכי' האור כנ\"ל בשבעת ימים שלפני שמ\"ע שהם שבעת ימי המשתה שלפני היחוד שבהם ממשיכי' בחי' הדעת שהוא הכלי להמשכת הטפה כו', וגם מצות סוכה והיא נעלי' בערך גם מבחי' הלולב ומיניו כי היא בחי' מקיף שאינה יוכל להתגלות בבחי' פנימי', בחי' פנימי' בינה והיינו מבחי' תעלומות לב שלמעלה מבחי' גלוי, והוא ענין א' עם יוכ\"פ בחי' תשוב' עילא' בינה ועיקר תשובה בלב כי בינה<sup data-n=\"262\">32</sup> ליבא פי' פנימי' הלב ועי\"ז לפני<sup data-n=\"263\">33</sup> הוי' תטהרו למלאו' כל הפגמי' והחסרונו' שנעשו בתורה כי זוהי למעלה מבחי' התורה כו', ומזה נעשה אח\"כ סוכות בסכך שמקיף מלמעלה אם הבנים שמחה כי בפנימי' א\"א להתגלות, וז\"ש לשמש<sup data-n=\"264\">34</sup> שם אהל בהם כחתן יוצא מחופתו שכן גם בחתן וכלה מתחלה מכניסי' אותם תחת חופה שהיא בחי' מקיף מלמעלה ואח\"כ ישיש כגבור לרוץ אורח כו', והוא למעלה מבחי' מ\"ת שבשבועות כנ\"ל. ואח\"כ הוא בחי' שמ\"ע היינו שבחי' מקיף זה נכנס אז בבחי' גילוי בפנימית.\n<b>והנה</b> בשמ\"ע עושי' הקפות שמקיפי' עם הס\"ת את המקום שקוראי' עליו בספר. והוא לרמוז בזה על ענין הכונה הנ\"ל דארץ קדמה כו' כי הנה הס\"ת עצמה הנכתב' בדיו ע\"ג קלף הוא בחי' עשי' גשמיו' אבל הקריאה בפה שע\"י האותיות הדבור אף כי אחה\"ע<sup data-n=\"265\">35</sup> מהגרון ובומ\"ף מהשפתים שהם גשמיי' היינו שהפה הוא בחי' כלי להאותיו', קבען<sup data-n=\"266\">36</sup> בפה בבחי' קביעות ממש, אבל מקורן בנפש הרוחני' ונמשכי' מן השכל כמ\"ש בחכמ'<sup data-n=\"267\">37</sup> יסד ארץ, אבא<sup data-n=\"268\">38</sup> יסד ברתא,",[["259","29","<b>ביום חתונתו זה מ\"ת</b>: שה\"ש ג, יא. תענית כו, ב."],["260","30","<b>דע את אלקי אביך</b>: דה\"א כח, ט."],["261","31","<b>ואהבת . . והיו הדברים</b>: ואתחנן ו, ה-ו."],["262","32","<b>בינה ליבא</b>: תקו\"ז בהקדמה ד\"ה פתח אליהו (יז, א)."],["263","33","<b>לפני הוי' תטהרו</b>: אחרי טז, ל."],["264","34","<b>לשמש שם אהל</b>: תהלים יט, ה."],["265","35","<b>אחה\"ע מהגרון</b>: ראה ס' יצירה פ\"ב מ\"א. וראה במ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"א ע' קה."],["266","36","<b>קבען בפה</b>: ס' יצירה שם מ\"ג."],["267","37","<b>בחכמ' יסד ארץ</b>: משלי ג, יט."],["268","38","<b>אבא יסד ברתא</b>: זח\"ג רמח, ב. רנו, ב. ועוד."]]],[2101920091,"כנרא' בעליל שהתינוק לפי שאין לו חכמ' אינו יכול לדבר כו', וזהו שמקיפי' אותם עם הס\"ת הגשמיו' משום דארץ קדמה ששרש הגשמיו' נעלה יותר כו', וכן בשעת נישואי חתן וכלה נקבה<sup data-n=\"269\">39</sup> תסובב גבר.\n<b>והנה</b> אחר שנמשך ההמשכה בפנימי' נאמ' עצרת תהי' לכם, עצרת ל' קליטה ועיכוב דהיינו שלא תהא פולטת ח\"ו אלא שיהי' נקלט ונתפס ממש בלב איש ישראל להיו' מזה כן על כל השנה בחי' דעת ואוריית' מחכמ' נפקת כו' וכמ\"כ הוא בחי' עצרת למעלה, וז\"ש אז מוריד הגשם שהיא בחי' תורה ובל' הזהר נק' שערות וכמ\"ש קוצותיו<sup data-n=\"270\">40</sup> תלתלים דכמו השערות יש לכל שערה יניקה מיוחדת מהמוח כן כל פרטי ההלכות הם המשכות פרטיים מבחי' חכמה עילאה כו' וכמו\"כ הוא <sup data-n=\"271\">41</sup>. . . ואח\"כ הלידה בזש\"פ התגלות הנשמות כו'. והנה בשבועות הי' ע\"י דבור ויאמר ה' וידבר ה' וביוכ\"פ תשובה בלב אבל בשמ\"ע הוא בבחי' מעשה וארץ קדמה כו' לכן נקלט ונתפס היטב להיו' עצרת לכם וד\"ל.",[["269","39","<b>נקבה תסובב גבר</b>: ירמי' לא, כא."],["270","40","<b>קוצותיו תלתלים</b>: שה\"ש ה, יא."],["271","41","חסר כאן כמה תיבות שנקרע בשולי הגליון בגוכתי\"ק."]]],[2101920092,"<h3>ביאור ענין שהמזל</h3>\n<b>ביאור</b><sup data-n=\"272\">1</sup> ענין שהמזל מכה ואומר לו גדל להעשב<sup data-n=\"273\">2</sup> ואעפ\"כ העיקר מבחי' א\"ס הסובב דוקא. הוא עד\"מ אדם העושה דבר ביד שאע\"פ שהידים עושי' ומציירים הרי מי העושה לא האדם שכחו ועוצמו עושה כל זאת רק שע\"י הידים הוא עושה כו', כמ\"כ א\"ס ב\"ה הכל יכול הוא העושה התהוות הגשמי' אלא שההמשכה היא ע\"י המדות חסד<sup data-n=\"274\">3</sup> דרועא ימינא יהי<sup data-n=\"275\">4</sup> אור כו' ולא שהחסד עצמו מהוה (כי הוא מבחי' ממלא שיכול להיו' מזה התהוות הרוחני' בלבד) אלא שא\"ס ב\"ה ממש מהוה, רק שמהוה ע\"י החסד וד\"ל.",[["272","1","<b>ביאור ענין שהמזל</b>: מאמר זה נרשם בגוכי\"ק הצ\"צ אחר המאמר דלעיל (ושייך להמבואר לעיל ד\"ה ביום השמע\"צ ס\"ב). ונדפס ג\"כ בליקוט פירושים ומ\"מ לתניא (חיטריק) אגה\"ק ס\"כ (ע' תפה). וראה בארוכה יותר להלן בנוסח השני של ד\"ה ביום השמע\"צ (בהפיסקאות שלאחרי הביאור). וראה עוד על מארז\"ל אין לך עשב כו' בס' מאמרי אדה\"ז על מארז\"ל ע' קלה. ומקבילו ד\"ה להבין שרש ענין השתלשלות בס' מאמרי אדהאמ\"צ דברים ח\"ג ע' תתעו."],["273","2","<b>שהמזל מכה ואומר לו גדל להעשב</b>: ראה ב\"ר פ\"י, ו. זח\"א רנא, א. זח\"ב קעא, ב. זח\"ג פו, א. מו\"נ ח\"ב פ\"י. תניא אגה\"ק ס\"כ."],["274","3","<b>חסד דרועא ימינא</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."],["275","4","<b>יהי אור</b>: בראשית א, ג."]]],[2101920093,"<h3>שרשי הדברים ע\"פ ביום השמע\"צ</h3>\n<b>שרשי</b><sup data-n=\"276\">1</sup> הדברים הנ\"ל. תחלה יש להבין מה<sup data-n=\"277\">2</sup> שהמשכת הדעת הוא ע\"י ד' מיני' אלו דוקא. הענין (ב'<sup data-n=\"278\">3</sup> הה\"מ ז\"ל ששמע ממנו סוכות האחרון תקל\"ג) דכתי' נפשות<sup data-n=\"279\">4</sup> עשו וביעקב ע'<sup data-n=\"280\">5</sup> נפש כי זהו הכלל שבכ\"מ שהוא בחי' רבוי ובחי' יש א\"א להיות מזה בחי' אחדות אבל ע\"י בחי' ביטול בחי' אין נעשה אחדות. כמו שנאמר עושה<sup data-n=\"281\">6</sup> שלום במרומיו שר של מים ואש אין מכבין זא\"ז. אף שבאמת הם הפכי' רק שע\"י הביטול מגלוי הארה שלמעלה מערכם והוא מ\"ש המשל ופחד עמו וע\"י זה הם בבחי' אין ולכן יכולי' להתחבר יחד כי המים אינן מים והאש אינו אש עד\"מ עד שיהיו בלתי סובלי' זא\"ז אלא כולם כאחד ממש מחמ' שהם בבחי' אין. משא\"כ כשהוא בבחי' יש אזי הם כאו\"א בפני עצמו נפשות ל' רבים, אבל יעקב<sup data-n=\"282\">7</sup> להיותו בריח התיכון שמבריח מן הקצה אל הקצה ומחבר אברהם ויצחק חו\"ג ע\"י המשכת א\"ס ב\"ה שלמעלה מעלה, שע\"י בחי' אין אזי מתחברי' יחד כנ\"ל וזהו ע' נפש ל' יחיד. [צ\"ע<sup data-n=\"283\">8</sup> ממארז\"ל הושיט<sup data-n=\"284\">9</sup> הקב\"ה אצבעו הקטנה ושרפם, ומדוע אינם מתבטלים מיכאל וגבריאל כשמאיר בחי' המשל ופחד].\nב) <b>והנה</b> כמ\"כ כל הד' מיני' שבלולב הם נמשכי' מבחי' זו שהיא בחי' האין בחי' האחדו' שמשם הושפל ההארה להיו' כן בד' מיני' גשמיים הללו, כי",[["276","1","<b>שרשי הדברים הנ\"ל</b>: הנחת כ\"ק אדמו\"ר הצ\"צ (ונדפס כאן מגוכי\"ק). וראה לקמן נוסח שני באריכות יותר. ונוסח שלישי בסידור עם דא\"ח רסא, ג (שם הנחת כ\"ק אדמו\"ר האמצעי, ומתחיל: להבין שרש ענין הלולב ומיניו). וראה גם ס' מאמרי אדהאמ\"צ דברים ח\"ד ע' א'שיט. ד\"ה ביום השמע\"צ באוה\"ת שמע\"צ כרך ו' ע' ב'תקמג. ד\"ה ולקחתם לכם בסוף סה\"מ תרל\"ג ח\"ב ע' תקלד [ונמצא ג\"כ בסה\"מ תר\"מ ח\"ב ע' תקעח ואילך]. ובשינויים והוספות בסה\"מ תרל\"ו ח\"ב ע' שנח. המשך וככה תרל\"ז פרקים פז, צג-ד (ע' קמב-ג. קנ-נא). ד\"ה ולקחתם לכם בסה\"מ תרנ\"ב ע' א ואילך. וראה הגהות מכ\"ק אדמו\"ר מהר\"ש להלן בהוספות."],["277","2","<b>מה שהמשכת הדעת הוא ע\"י ד' מינים אלו דוקא</b>: ראה פע\"ח שער הלולב (שכ\"ט) פ\"א ואילך. שער הכוונות ענין סוכות דרוש ה'. משנת חסידים מס' ימי מצוה וסוכה פ\"ה מ\"ג. וראה גם מאמרי אדהאמ\"צ דברים ח\"ג ע' א'שט ואילך. המשך וככה תרל\"ז פפ\"ד ואילך (ע' קלז ואילך)."],["278","3","<b>(ב' הה\"מ ז\"ל ששמע ממנו סוכות האחרון תקל\"ג) דכתי' נפשות עשו</b>: ראה עוד ע\"ז בסידור שם רסב, ב. תו\"א קיז, ג. לקו\"ת ראה ל, א. מאמרי אדה\"ז עה\"ת ח\"ב ע' תערה. סה\"מ תקס\"ח ח\"א ע' צד. ח\"ב ע' תרצד. וראה מאמרי אדהאמ\"צ דברים ח\"ד ע' א'שיא. אוה\"ת לך לך פז, א. יתרו ע' תשלב. במדבר ע' יט. כא. מגילת אסתר (הוצאת תש\"נ) ע' רלח. רנט. סה\"מ תרל\"ח ע' פג (ובמ\"מ שם). ועוד."],["279","4","<b>נפשות עשו</b>: וישלח לו, ו."],["280","5","<b>ע' נפש</b>: ויגש מו, כז. ועוד. וראה ויק\"ר פ\"ד, ו. רש\"י ויגש מו, כו."],["281","6","<b>עושה שלום במרומיו שר של מים ואש .ֿ. המשל ופחד עמו</b>: איוב כה, ב. במדב\"ר פי\"ב, ח. ובכ\"מ. והובא ג\"כ (בשם הה\"מ): בס' מאמרי אדה\"ז אתהלך לאזניא ע' יב. תקס\"ב ח\"ב ע' תמ. תקס\"ג ח\"א ע' נב. ביאוה\"ז לאדהאמ\"צ ח, ג. סה\"מ תרל\"ב ח\"ב ע' תנד. פלח הרמון בראשית לד, ג. שמות ע' רסא. וראה בהנסמן עוד בסה\"מ תרל\"ג ח\"ב ע' תקלה. סה\"מ תר\"מ ח\"א ע' רלא."],["282","7","<b>יעקב להיותו בריח התיכון</b>: ראה זח\"ב נא, ב. קעה, ב. ובהמ\"מ בס' מאמרי אדהאמ\"צ שמות ח\"א ע' יא, ובסה\"מ תרכ\"ט ע' קיז."],["283","8","<b>צ\"ע ממארז\"ל הושיט</b>: הגהת כ\"ק אדמו\"ר הצ\"צ."],["284","9","<b>הושיט הקב\"ה אצבעו</b>: סנהדרין לח, ב."]]],[2101920094,"אתרוג<sup data-n=\"285\">10</sup> הדר באילנו משנה לשנה קיץ וחורף קור וחום, ואף גם בא\"י יש שינוי מימות החמה וימות הגשמים, וכן עפ\"י אמת הוא ב' מדרגות חלוקות ניסן ותשרי, והאתרוג דר באילנו משנה לשנה שסובל ב' הפכי' מצד בחי' אין שבו, וכן הלולב שכל ענפיו הם ביושר מדובקי' אלו לאלו לא ככל האילנות שענפיהן מתפרדי' זה פונה לכאן וזה לכאן, ואף אם אינן בקצוות רחוקי' מ\"מ אינן קרובי' אלו לאלו כבלולב שמדובקים ממש ונק'<sup data-n=\"286\">11</sup> כפות תמרים ל' כ‘פות, וכן ההדס עליו חופים את עצו, והערבה<sup data-n=\"287\">12</sup> ארז\"ל שנק' אחוינא ע\"ש שגדילי' באחוה דהיינו בדיבוק זל\"ז, והכל מפני בחי' אין שבהם ועי\"ז הוא שממשיכי' מבחי' דעת שהוא מבחי' אין בחי' חכמה.\nג) <b>אך</b> מה שהצורך דוקא במיני' גשמיים ולא בבחי' דעת רוחני, הוא כי הגשמיו' הוא בשרשו נעלה יותר שנמשך מבחי' סוכ\"ע, כי מבחי' ממכ\"ע א\"א להיות אלא ההמשכה ברוחני' כמו נפשו' הבהמות ונפש הבהמי' שבאדם מפני שור ונפש האלקי' מפני אדם כו' הכל ברוחני', אבל להיות התהוות מציאת גשמי זה א\"א בשום פנים כלל להתהוות מן הרוחני' כמ\"ש<sup data-n=\"288\">13</sup> הרמב\"ם שעילה ועלול הכל בערך א' מרוחני' לרוחני' אבל איך יתהוה מזה מציאת גשם זהו דבר שא\"א כלל. כ\"א מבחי' רצון עליון הכל יכול והוא למעלה מן החכמה שהיא בחי' ממכ\"ע שמשם ואילך הוא בחי' השתלשלו' יש מיש אבי\"ע אבל כשצ\"ל התהוו' גשמיו' א\"א להיו' ממנה כנ\"ל אלא מבחי' כתר רצון עליון אני<sup data-n=\"289\">14</sup> ראשון ואני אחרון כו', וז\"ש כולם<sup data-n=\"290\">15</sup> בחכמ' עשית ולא נאמ' חכמה עשה רק שעם החכמ' עשה הרצון כי מ\"מ ריבוי ההתחלקו' הוא מחמת החכמ' אבל גוף המעשה הוא ע\"י הרצון רק שהחכמ' מתלבשת ברצון ואז עשי\"ת<sup data-n=\"291\">16</sup> הוא הרצון כו'. ולכן ארץ<sup data-n=\"292\">17</sup> קדמה ששרש הגשמיו' נעלה יותר כי הוא בחי' החיצוני' דכתר משא\"כ בחי' שמי' רוחני' שנמשך מחכמ' ממכ\"ע בחי' פנימי' שלמטה במדרגה, כידוע<sup data-n=\"293\">18</sup> בענין הע\"ס דפעמי' הכתר נמנה כשמוני' י\"ס מבחי' חיצוני' ואז חיצוני' הכתר ראשון ואח\"כ חכמ' ואז אין הדעת נמנה ופעמי' אינו נמנה כשמוני' בחי' פנימי' כי פנימי' הכתר אינו בערך הספי' כלל ואז ראשית היא חכמ' דאצי' כו'.\n<b>והנה</b> להיות כי בשבעת ימי הסוכות צריך להמשיך דעת מחדש כנ\"ל וכל המשכת אור חדש הוא ע\"י הכתר דוקא כי אף שההמשכה היא מחכמ' אבל א\"א להיו'",[["285","10","<b>אתרוג הדר באילנו משנה לשנה</b>: סוכה לה, א. וראה גם סה\"מ מלוקט ח\"א ע' רנד."],["286","11","<b>ונק' כפות תמרים ל' כפות</b>: ראה סוכה לב, א. וראה גם סה\"מ מלוקט שם ע' רנג."],["287","12","<b>והערבה ארז\"ל שנק אחוינה ע\"ש שגדילי' באחוה</b>: ראה שבת כ, א וברש\"י שם. סידור שם רסב, ג. רסד, ד. סה\"מ תקס\"ח ח\"א ע' שיז."],["288","13","<b>כמ\"ש הרמב\"ם</b>: ראה מו\"נ ח\"ב פכ\"ב."],["289","14","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."],["290","15","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["291","16","<b>עשי\"ת</b>: הר\"ת כאן הוא לסימן הדגשה."],["292","17","<b>ארץ קדמה</b>: חגיגה יב, א."],["293","18","<b>כידוע בענין הע\"ס דלפעמים הכתר נמנה</b>: ראה ע\"ח שער מוחין דצלם (שכ\"ג) פ\"ה ופ\"ח. שער דרושי אבי\"ע (שמ\"ב). ס' שער ההקדמות דרוש בענין הכתר (רנב, א). וראה לקו\"ת שלח מט, ג. ס' מאמרי אדה\"ז עה\"ת ח\"ב ע' תרטו, ובמ\"מ שם. ובארוכה ביאוה\"ז לאדהצ\"צ ח\"א ע' ערה ואילך (ובהנסמן שם)."]]],[2101920095,"המשכה אם לא ע\"י שמתחלה יומשך הארה מן המקור בחכמ' כמשל הנהר כשרוצי' להמשיכו אנה ואנה שמתחלה צריך לחפור בעומק יותר להרחיבו בעצמותו וכו', ובחי' ההמשכה מכתר הוא ע\"י בחי' עשי' דוקא ששרשם נלקח מבחי' כתר דוקא כנ\"ל, וכן בחי' סוכות בחי' פנימי' בינה תשו\"ע שביוכ\"פ שמזה נעשה בסוכות מקיף מלמעלה, ולכן חמתה<sup data-n=\"294\">19</sup> מרובה מצלת' פסולה, כי הצל בחי' חשך נעלה יותר כמ\"ש בצל<sup data-n=\"295\">20</sup> החכמ', ישת<sup data-n=\"296\">21</sup> חשך סתרו, חשכת מי', כמראה<sup data-n=\"297\">22</sup> החמה עמוקה מהצל כו'.\nד) <b>והנה</b> האדם מורכב מב' הבחי', נפשו הרוחני' מממלא וגופו הגשמי שרשו מבחי' סכ\"ע, והתחברות' יחד ע\"י התורה שהיא כלולה מב' הבחי' אורייתא<sup data-n=\"298\">23</sup> מחכמ' נפקת, אבל לא כחכמ' שהיא חיות העולמו' שהיא בחי' נובלו'<sup data-n=\"299\">24</sup> חכמ' שע\"ז נאמ' כולם בחכמ' עשית, אבל התורה היא בחי' פנימי' חכמ', וכן המצות שהם רצון העליון יש בהם ג\"כ חפץ שהם חפץ ה' ית' ה'<sup data-n=\"300\">25</sup> חפץ למען צדקו כו', וע\"כ הם מחברי' בחי' החיצוני' שהוא הרצון שממנו נלקח כל הדברי' גשמיי' שכולם הם מבחי' רצון שהרי אין בהם חפץ, וכן כל הדברי' רוחניי' שהם מחיצוני' חכמ' כנ\"ל, והענין שבכדי שיהי' המשכת רצונו ית' בדברי'<sup data-n=\"301\">26</sup> ושיהי' התלבשות החכמ' בהם הוא מחמת החפץ שיש לו במצות שהוא המכריחם אף גם כי יש כמה דברי' בעולם שלא נעשו בהם מצוה מ\"מ כולם לא<sup data-n=\"302\">27</sup> נבראו אלא לצוות לזה לחם לאכול ובגד ללבוש ועי\"ז יהי' כח לומר אחד ואהבת, שבזה יש לו חפץ, וחפץ זה מכריח וגורם התלבשו' הרצון וחכמ' בכל הדברי' השייכי' לזה וזהו ענין שלום<sup data-n=\"303\">28</sup> בפשמ\"ט, וכמ\"כ יש בחי' שלום בפשמ\"ע להיות התחברות הרצון עליון הנק' סובב עם הי\"ס דאצי' הנק' ממלא הוא ע\"י פנימי' חכמ' ובחי' חפץ הנ\"ל, ולכן העוסק בתורה דוקא משים שלום התחברות המאציל עם הנאצלים שזהו ע\"י בחי' רצון הנ\"ל.\nה) <b>והנה</b> יש ב' בחי' תורה, א' לצדיקי' בשבועות ולכן הי' בפרהסיא בקולי קולות כי הצדיקים הרי כל מעשיהם באתגלי' כי אינן מתייראי' מכל דבר המזיק אחר ששלימים הם בעבודתם, משא\"כ בחי' מ\"ת הב' שביוכ\"פ שהוא כנגד בחי' בע\"ת הוא<sup data-n=\"304\">29</sup> בצנעא משום שבע\"ת הם הכל בסתר שהרי מתחלה מכסה פשעיו הוא וגם אחרי ששב לה' היינו ג\"כ בסתר. ואז ממעמקים<sup data-n=\"305\">30</sup> קראתיך הוי' ועי\"ז מתעלה",[["294","19","<b>חמתה מרובה מצלתה פסולה</b>: סוכה ב, א."],["295","20","<b>בצל החכמ'</b>: קהלת ז, יב."],["296","21","<b>ישת חשך סתרו, חשכת מים</b>: תהלים יח, יב."],["297","22","<b>כמראה החמה עמוקה מהצל</b>: ב\"ב פד, א. תו\"כ תזריע יג, ג. ובכ\"מ."],["298","23","<b>אורייתא מחכמ' נפקת</b>: זח\"ב סב, א. פה, א. קכא, א. ועוד."],["299","24","<b>נובלו' חכמ'</b>: ראה ב\"ר פי\"ז, ה."],["300","25","<b>ה' חפץ למען צדקו</b>: ישעי' מב, כא."],["301","26","<b>בדברי'</b>: בסה\"מ תרל\"ג שם (ח\"ב ע' תקלז): המשכת רצונו ית' בדברים גשמיים."],["302","27","<b>לא נבראו אלא לצוות לזה</b>: ברכות ו, ב."],["303","28","<b>שלום בפשמ\"ט . . שלום בפשמ\"ע</b>: סנהדרין צט, ב: כל העוסק בתורה משים שלום בפמליא של מעלה ובפמליא של מטה."],["304","29","<b>הוא בצנעא</b>: ראה תשא לד, ג וברש\"י שם. תנחומא תשא לא. ובכ\"מ."],["305","30","<b>ממעמקים קראתיך הוי'</b>: תהלים קל, א."]]],[2101920096,"בנעילה<sup data-n=\"306\">31</sup> עליי' המל' עד דיקנא ואז מתמלאי' כל הפגמי' והחסרונו' שנפגמו בשם הוי' ע\"י התורה<sup data-n=\"307\">32</sup> וא\"כ הוא למעלה מבחי' מ\"ת דשבועות כנ\"ל, ואח\"כ בסוכות באה הארה זו ומתגלי' מלמעלה למטה בבחי' מקיף עד שאח\"כ ע\"י שבעת ימים אלו וע\"י הלולב ומיניו נמשכ' ההארה זו בבחי' פנימי' בשמ\"ע, ואז מקיפי' עם התורה הגשמיות שכל הדקדוק באותיותיה ונגיעה<sup data-n=\"308\">33</sup> פסולה שאין זה בשביל הקריא' בדיבור שהרי יוכל לקרות האלף אף שיהי' בו נגיעה כו', אלא משום שצ\"ל שלימה באותיותיה הגשמיי' דוקא כי מקרא<sup data-n=\"309\">34</sup> בעשי' שנשפל בבחי' עשי' וארץ קדמה שהתהוות הגשמיו' הוא ממקום יותר עליון כנ\"ל ולכן מקיפי' בה על מקום שקוראי' בו כל השנה באותיו' הדיבור הרוחניי' כו', ואז עצרת תהי' לכם פי' עצרת מלשון עוצר, שההמשכה מתעכבת ונקלטת שלא תהא פולטת ח\"ו, וכך ממש הוא למעלה בנשמו' ישראל דפעמים נק' אחיי<sup data-n=\"310\">35</sup> וריעיי ופעמי' אם<sup data-n=\"311\">36</sup> כבנים ואם כעבדים, כי העבד היינו כשהוא בחי' נפרד לגמרי ובן אף שהוא חלק מהאב מ\"מ הוא בחי' שחוץ ממנו שהרי נאמ' בן<sup data-n=\"312\">37</sup> יכבד אב א\"כ שייך הכיבוד מן הבן לאב להיותו דבר נמוך ממנו, משא\"כ אחיי וריעיי היינו שהם בערך והשואה א', כמ\"כ יובן למעלה שהנשמו' מתחלה בבחי' אצי' הם אחי' וריעים להקדב\"ה ואח\"כ נמשכת הטפה בבטן הנוק' ונק' בנים וכשיורדי' בבי\"ע אז אם כבנים אם כעבדים שאפשר שמתגשמי' ביותר עד שנעשי' בבחי' פירוד לגמרי להיות כיש ונפרד ממש.\n<b>והנה</b><sup data-n=\"313\">38</sup> בז' של פסח היא הלידה אבל הקליט' הטפה הוא בשמ\"ע שמתעכבת ברחם הנוק'<sup data-n=\"314\">39</sup>.\n<b>בענין</b><sup data-n=\"315\">40</sup> המשכת טפה דתורה שהיא ממו\"ס שלו' המחבר ע\"י הדע' היינו תפלה חוה\"ש בד\"ה<sup data-n=\"316\">41</sup> לא הביט און כו' משא\"כ בלא תפלה דעת אפילו תורה אין לו, וע' מענין יעשה שלו' בד\"ה<sup data-n=\"317\">42</sup> החלצו ובד\"ה כה תברכו כו', ועד\"ז י\"ל צאינה<sup data-n=\"318\">43</sup> כו'",[["306","31","<b>בנעילה עליי' המל' עד דיקנא</b>: ראה פע\"ח שער יוהכ\"פ ספ\"א ופ\"ה. לקו\"ת מסעי צג, ד. אוה\"ת פ' ראה ע' תשכב."],["307","32","<b>התורה</b>: בסה\"מ תרל\"ג שם (ח\"ב ע' תקלח): התשובה."],["308","33","<b>ונגיעה פסולה</b>: ראה שו\"ע יו\"ד סי' עד\"ר ס\"ד. שו\"ע אדה\"ז או\"ח סל\"ב ס\"ה. ובכ\"מ."],["309","34","<b>מקרא בעשי'</b>: פע\"ח שער הנהגת הלימוד (שי\"ז). טעהמ\"צ ושער המצות פ' ואתחנן. תניא פ\"מ (בהגה\"ה אחרונה). לקו\"ת ויקרא ה, א ואילך [והוא מסוף שנת תקע\"א, ונרשם בגוכי\"ק הצ\"צ בכת\"י מס' 1116 סמוך לד\"ה ביוהשמע\"צ כאן]. ס' מאמרי אדהאמ\"צ נ\"ך ע' קל, ובמ\"מ שם."],["310","35","<b>אחיי וריעיי</b>: תהלים קכב, ח. וראה זח\"ב קכב, א. לקו\"ת צו טז, ב ואילך. ביאוה\"ז לאדהאמ\"צ פינחס קיד, ד ואילך. ובכ\"מ."],["311","36","<b>אם כבנים ואם כעבדים</b>: פיוט היום הרת עולם במוסף דר\"ה."],["312","37","<b>בן יכבד אב</b>: מלאכי א, ו."],["313","38","<b>והנה בז' של פסח הוא הלידה</b>: ראה פע\"ח שער הלולב (שכ\"ט) ספ\"ח. וראה להלן ריש ד\"ה שחורה אני (ש\"פ וירא). וש\"נ."],["314","39","<b>הנוק'</b>: ע\"כ נרשם המאמר בגוכי\"ק."],["315","40","<b>בענין המשכת טפה</b>: מכאן הוא הגהת כ\"ק אדמו\"ר הצ\"צ."],["316","41","<b>בד\"ה לא הביט און</b>: לקו\"ת בלק עד, ד."],["317","42","<b>בד\"ה החלצו ובד\"ה כה תברכו</b>: לקו\"ת מטות פו, ב. נשא כז, א."],["318","43","<b>צאינה כו' שלמה</b>: שה\"ש ג, יא."]]],[2101920097,"שלמה, וענין ההפרש בין תשו' לתורה הגם כי תורה שלו' י\"ל כי תורה דשבועו' מו\"ס וע\"י תשו' מו\"ס דעתיקא יריעו'<sup data-n=\"319\">44</sup> שלמה, ושייכו' דעת זה בנש\"י י\"ל שהם חתן כנז' בד\"ה<sup data-n=\"320\">45</sup> תורה צוה, א\"נ גם בכלה צ\"ל דעת.",[["319","44","<b>יריעו' שלמה</b>: שה\"ש א, ה. ראה סד\"ה שחורה אני הנדפס לקמן (פ' וירא)."],["320","45","<b>בד\"ה תורה צוה</b>: לקו\"ת ברכה צד, א."]]],[2101920098,"<h3><i>נוסח אחר:</i> ביום השמיני עצרת</h3>\n<b>ביום</b><sup data-n=\"321\">1</sup> השמיני<sup data-n=\"322\">2</sup> עצרת תהי' לכם כו'. להבין ענין שמחת תורה מהו שייכות לשמוח שמחת התורה ביום השמיני עצרת, והלא בשבועות הוא זמן מתן תורתינו וא\"כ אז הי' צריך להיות קביעות שמחה זו, דהאי יומא דקא גרים. אך הענין כי בשבועות ניתנו לוחות ראשונות אבל לוחות האחרונות ניתנו ביוהכ\"פ כידוע, ועל לוחות האחרונות דוקא הוא שנוהגים לעשות חדוה ושמחה, ולכן הוא בשמ\"ע שהוא יום האחרון של חג שאחר יוכ\"פ וכמשי\"ת.\n<b>והענין</b> כי ב' מיני לוחות אלו הם כנגד ב' בחי' שבישראל, לוחות ראשונות שבשבועות הם כנגד בחי' צדיקים, ולכן ניתנו בקולי קולות, כי הצדיקים עובדיהן באתגלייא, ולוחות אחרונות שביוכ\"פ הם כנגד בחי' בע\"ת שבישראל, ולכן ניתנו בצנעא כענין הבע\"ת שדרכם והילוכם בקודש הוא בבחי' הצנע לכת, וכמ\"ש אשרי<sup data-n=\"323\">3</sup> נשוי פשע כסוי חטאה וכו'. ולכך ג\"כ ניתנו לוחות האחרונות ביוכ\"פ מפני שאז הוא יום מחילה וסליחה כו'. והיינו ע\"י בחי' תשובה בכל עשרה ימים שלפני יוהכ\"פ בחילא יתיר<sup data-n=\"324\">4</sup>, וזהו שאומרים בכל עשרה ימים שמר\"ה עד יוהכ\"פ מזמור ממעמקים<sup data-n=\"325\">5</sup> קראתיך הוי', פי' מעומקא דליבא קראתיך והמשכתיך להיות שמעה בקולי, והיינו מ\"ש ביוהכ\"פ לפני הוי' תטהרו, שבו ביום נמשך ממדריגה שלפני ולמעלה מבחי' הוי' שמשם נמשך לכפר עליכם ולהיות תטהרו כו', ואז זדונות<sup data-n=\"326\">6</sup> נעשו לו כזכיות<sup data-n=\"327\">7</sup> ונעשה מלא מצות (פי' אור המצוה) ממה שהי' מלא עון. והנה בחי' זכיות אלו הם זכיות אחרים שלא מענין זכיות הצדיקים כלל, וזהו ענין מתן תורה שניתנה אז ביוכ\"פ לבחי' בע\"ת שגם הם נעשו כמלא זכיות ומצות ע\"י התשובה, שביוהכ\"פ",[["321","1","<b>ביום השמיני עצרת</b>: מאמר זה הוא נוסח אחר ובאריכות יותר מד\"ה ביום השמע\"צ שנדפס לעיל [לעיל נדפס מכתי\"ק אדמו\"ר הצ\"צ שנרשם בסמיכות לזמן אמירתו בשנת תקע\"ב, וכאן הוא באריכות יותר ועם הוספות, וכנראה נכתב ג\"כ ע\"י אדמו\"ר הצ\"צ בתקופה מאוחרת יותר]. וראה עוד בהמ\"מ לעיל בתחילת נוסח הא'."],["322","2","<b>ביום השמיני עצרת תהי' לכם</b>: פינחס כט, לה."],["323","3","<b>אשרי נשוי פשע</b>: תהלים לב, א."],["324","4","<b>בחילא יתיר</b>: זח\"א קכט, ב."],["325","5","<b>ממעמקים קראתיך הוי'</b>: תהלים קל, א."],["326","6","<b>לפני הוי' תטהרו</b>: אחרי טז, ל."],["327","7","<b>זדונות נעשו לו כזכיות</b>: יומא פו, ב."]]],[2101920099,"הזדונות נהפכים להיות הם ממש זכיות, והוא משונה מבחי' מ\"ת שבשבועות שהם לצדיקים המלאים זכיות מקיום המצות.\n<b>והנה</b> עיקר בחי' שמחה שייך דוקא בבחי' בע\"ת, עד\"מ בן מלך כשהוא תמיד אצל אביו המלך אין שייך לומר שיהי' אך שמח כל ימיו מזה, כי<sup data-n=\"328\">8</sup> תענוג תמידי אינו תענוג, אבל כשהי' בשביה ונתרחק מאד מאביו המלך אזי אח\"כ בצאתו חפשי בבואו אל אור פני אביו המלך אזי דוקא תגדל השמחה מאד וישמחו שניהם שמחה רבה ועצומה מקירובם זה אחר הריחוק שנתרחקו כו'. וכך הוא ההפרש בין בחי' צדיקים לבע\"ת, שמ\"ת שבשבועות שהוא כנגד בחי' צדיקים לא נקבע שמחה כ\"כ ע\"ז, כי הצדיקים הם כבנים למקום אשר מעודם הם עומדים לפני ה', ותענוג תמידי אינו תענוג, אבל מ\"ת שביוכ\"פ שהוא כנגד בחי' בע\"ת שנתרחקו מאור פני מלך חיים תחלה, ולכן כשנתקרבו אח\"כ ביוכ\"פ ע\"י התשובה מעומקא דליבא שבחילא יתיר ממטה למעלה ועי\"ז קראתיך הוי' ממעלה למטה, ומתייחדים פב\"פ, אזי תגדל השמחה והחדוה עד מאד בשניהם והוא בחי' סוכות שאח\"כ שהוא זמן שמחתינו לשון רבים, ב' שמחות ישמח ה' במעשיו כמשל האב ששמח מראיית בן הרחוק ומשתעשע בו, וישמח ישראל בעושיו כמשל הבן ששמח מן האב, והיינו ג\"כ ענין השמחה בשמע\"צ שהוא על מ\"ת שביוכ\"פ על רחוק<sup data-n=\"329\">9</sup> שנעשה קרוב כו' ששייך ע\"ז שמחה יותר מעל מ\"ת שבשבועות כנ\"ל.\n<b>אך</b> להבין מה שנקבע שמחה זו בשמיני עצרת דוקא ולא בימים שלפניו, הנה יש להקדים ענין בחי' התורה שנקראת שלום כמ\"ש<sup data-n=\"330\">10</sup> רז\"ל ע\"פ או יחזיק במעוזי יעשה שלום לי שלום יעשה לי, כל העוסק בתורה משים שלום בפשמ\"ע ובפשמ\"ט. וענין השלום כך הוא, כי הנה כתיב בראשית<sup data-n=\"331\">11</sup> ברא את השמים ואת הארץ הקדים שמים לארץ, וכתוב אחד אומר ביום עשות ארץ ושמים הקדים ארץ לשמים, ויש בזה ב' דיעות בדרז\"ל, א' אומר שמים קדמו וא' אומר ארץ קדמה, והנה באמת שניהם דברי אלקים חיים הם. אך לבאר דעת האומר ארץ קדמה, שלכאורה אינו מובן למה הארץ שהיא גשמי' תהי' קודמת לשמים שהם רוחניי', וגם כי מצינו כן ממה שכל המצות הם נשפלו בבחי' מעשה דוקא כמו מצות מעשר, עשר<sup data-n=\"332\">12</sup> תעשר היוצא שנה שנה, ב' מעשרות שהוא ע\"י שיהי' חורש הקרקע גשמי' וזורע וקוצר כו', וכן מצות הצדקה שהוא ממה שירויח מיגיע כפו בעשי' גשמיי' בפו\"מ, וכעד\"ז כל המצות ציצית מצמר תפילין מקלף כו', ובאמת נודע<sup data-n=\"333\">13</sup> דרמ\"ח מ\"ע הם רמ\"ח",[["328","8","<b>כי תענוג תמידי אינו תענוג</b>: ראה כתר שם טוב סקכ\"א. לקוטי אמרים להה\"מ כג, סע\"ג. אור תורה להה\"מ כז, ב."],["329","9","<b>רחוק שנעשה קרוב</b>: ע\"פ ברכות לד, ב."],["330","10","<b>כמ\"ש רז\"ל ע\"פ או יחזיק במעוזי</b>: ישעי' כז, ב. סנהדרין צט, ב."],["331","11","<b>בראשית ברא . . ביום עשות . . ב' דיעות בדרז\"ל</b>: בראשית א, א. ב, ד. חגיגה יב, א."],["332","12","<b>עשר תעשר היוצא שנה שנה</b>: פ' ראה יד, כב."],["333","13","<b>נודע דרמ\"ח מ\"ע הם רמ\"ח אברין דמלכא</b>: ראה תקו\"ז תי' ל' (עד, א)."]]],[2101920100,"אברין דמלכא שהוא רמ\"ח המשכות מא\"ס ב\"ה שנמשכים דוקא ע\"י קיום המצות מעשיות וכמ\"ש ויניחהו<sup data-n=\"334\">14</sup> בג\"ע לעבדה ולשמרה, וארז\"ל לעבדה זו רמ\"ח מ\"ע כו' שעי\"ז הי' מוסיף אורות בג\"ע וכידוע<sup data-n=\"335\">15</sup> ג\"כ בפי' המאמר שכר מצוה מצוה, דהיינו שהשכר מצוה שהוא ההמשכה מא\"ס ב\"ה שהוא בחי' אבר א' מרמ\"ח אברין דמלכא עד\"מ נולד מן המצוה עצמה, שהוא ענין המעשה בפו\"מ, וכ\"ז הוא משום דארץ קדמה כו', ובאמת כי כל זה פלאי איך ולמה כח המעשה גשמיות גדול כ\"כ להיות בה ועל ידה המשכת אורות עליונים מאד נעלים אשר עליהם נאמר עין<sup data-n=\"336\">16</sup> לא ראתה אלקים זולתך כידוע.\n<b>אך</b> הענין כי נודע שיש ב' בחי', ממכ\"ע וסוכ\"ע, פי' בחי' ממכ\"ע הוא בחי' השתלשלות העולמות דהיינו שההארה נמשכת בבחי' עילה ועלול ממדריגה למדריגה וכמ\"ש לכבודי<sup data-n=\"337\">17</sup> בראתיו יצרתיו אף עשיתיו, שג' עולמות בי\"ע הן בבחי' השתלשלות ירידות החיות מן העולם ועד העולם, והיינו מבחי' ד' חיות שבמרכבה שישנם בכל עולם ועולם ונמשכים מעולם שלמעלה הימנו והם המקורות לחיות כל הנמצאים אשר בעוה\"ז, מבחי' פני שור נמשכים נפשות הבהמות שבעולם ומבחי' פני ארי' נמשכים נפשות החיות שבעולם ומבחי' פני נשר נמשכים נפשות העופות שבעולם, ומבחי' פני אדם שבמרכבה נמשכו נשמות חסידי או\"ה ומבחי' אדם העליון שעל הכסא נמשכים נשמות ישראל כידוע.\n<b>והנה</b> בחי' ד' חיות אלו ישנם בכל עולם מג' עולמות בי\"ע כי מבריאה נמשך ויורד החיות ביצי' ומיצירה לעשי', וזה נק' בשם השתלשלות שהוא הילוך השפע ממדריגה למדריגה דהיינו מרוחניות לרוחניות, כי אף גם המשכות נפשות ורוח החיים לגופות הבהמות ובנ\"א שבעוה\"ז הוא רק בחי' השתלשלות והתהוות מציאות רוחני מרוחני שלמעלה ממנו, כי הרי נפש הבהמה רוחני הוא, ולכן נמשכת מפני שור שבמרכבה הרוחני, וכן גם המשכ' הנפש אלקי' שבאדם מבחי' אדה\"ע שעל הכסא, ודרך פרט המשכת נפש מעשי' ורוח מיצי' ונשמה מבריאה הכל הוא בבחי' השתלשלות, כי הרי נר\"נ שבאדם רוחניים המה כנ\"ל, ומקור התחלת ההשתלשלות הוא מבחי' חכמה וז\"ש לכבודי<sup data-n=\"338\">18</sup> בראתיו כבו\"ד בגימ' ל\"ב נ\"ח, ומשם ואילך בראתיו יצרתיו כו' בבחי' ההשתלשלות ואין התהוות מהות חדש כלל מראשית חכמה ואילך. אך כ\"ז הוא ההמשכות והתהוות מציאות רוחניות שהם נפשות הבע\"ח כנ\"ל, אבל להיות התהוות מציאות גשמי שהוא עד\"מ גוף הבע\"ח הנ\"ל או שאר כל",[["334","14","<b>ויניחהו בג\"ע לעבדה ולשמרה וארז\"ל לעבדה זו רמ\"ח מ\"ע</b>: בראשית ב, טו. זח\"א כז, א. זח\"ב קסה, ב. ובכ\"מ."],["335","15","<b>וכידוע ג\"כ בפי' המאמר שכר מצוה מצוה</b>: אבות פ\"ד מ\"ב. תניא ר\"פ ל\"ז. פל\"ט (נב, ב). ובכ\"מ."],["336","16","<b>עין לא ראתה אלקים זולתך</b>: ישעי' סד, ג."],["337","17","<b>לכבודי בראתיו יצרתיו אף עשיתיו</b>: שם מג, ז."],["338","18","<b>כבוד בגימ' ל\"ב נ\"ח</b>: ראה זח\"ג לג, א. פרדס שכ\"ג מע' כבוד. מאמרי אדהאמ\"צ בראשית ע' ג. וש\"נ."]]],[2101920101,"דומם וצומח, זה דבר שא\"א להיות כלל מבחי' השתלשלות, פי' שא\"א לבחי' פני שור הרוחני שהוא בחי' החיות הרוחני שנתצמצם להיות ממנו השפעות והתחלקות הנפשות לבהמות גשמיים עד\"מ שיהוה וישפיע גוף בהמה גשמי' עד\"מ, וכן אפי' בחי' פני אדם שעל הכסא הנותן נשמה לישראל א\"א שיתהווה ממנו הגוף כו', כי א\"א להיות כלל שיתהווה הגשמיות מן הרוחניות ואפי' אחר כמה ירידות לאין קץ ותכלית יהי' הכל בחי' רוחניות ולא יתהווה ממנו מציאות גשמי כו', וא\"א להיות התהוות הגופות הגשמיים דדצח\"ם שבעולם וכל אשר בו, כ\"א מלמעלה מהשתלשלות דהיינו מעצמותו ומהותו ית' ממש שהוא בלתי בעל גבול ותכלית ואין כחו מוגבל ומשם דוקא הוא שנמשך להיות התהוות הגשמי' כי הוא צוה ונבראו לפי שהוא כל יכול וכמ\"ש כל<sup data-n=\"339\">19</sup> אשר חפץ הוי' עשה, חפץ דוקא שהוא בחי' רצון העליון שלמעלה מהחכ' משם נמשך להיות בחי' עשי' גשמיות, משא\"כ מבחי' חכ' לא הי' באפשרי שיתהווה ממנה התהוות גשמיי' כלל, לפי שחכמה הוא בחי' ראשית ההשתלשלות כמ\"ש ראשית<sup data-n=\"340\">20</sup> חכמה דהיינו שכבר נתצמצם האור מבחי' א\"ס שלמעלה מהחכמה להיות בחי' חכמה בגבול ולכן משם ואילך הוא רק בחי' השתלשלות עילה ועלול, והכל מרוחני לרוחני אבל א\"א לה<sup data-n=\"341\">21</sup> להוות מציאות גשמי כלל לפי שאינו מערכו וממהותו וכחה<sup data-n=\"342\">22</sup> מוגבל כנ\"ל, אלא מבחי' רצה\"ע שלמעלה מהחכמה שהוא בחי' א\"ס ממש ונק' סוכ\"ע ומשם נמשך להיות עשי' גשמיות כי כל יכול הוא וז\"ש נעוץ תחב\"ס, כי בסופן דוקא כשצ\"ל התהוות הגשמי' שהוא למטה הרבה מן הרוחני' שם דוקא צ\"ל נעוץ תחלתן מבחי' רצה\"ע שלמעלה מהחכ' הנק' ראשית וכמאמר סוף מעשה עבמ\"ח תחלה.\n<b>ומה</b><sup data-n=\"343\">23</sup> שארז\"ל אין<sup data-n=\"344\">24</sup> לך עשב מלמטה שאין לו מזל מלמעלה שמכה בו ואומר לו גדל, הרי שגם גידול עשב גשמי הוא ממזל שלמעלה שהוא רק מבחי' ממכ\"ע, היינו שמגדלו בלבד ונותן בו טעם שהוא בחי' הרוחני' שמתלבש שזה נמשך מן המזל שמלמעלה, וכך הוא עד\"מ בפירות כמו מתיקות התפוח שהוא בחי' הטעם הרוחני שנתלבש בגשם חומר התפוח זהו שנמשך ונולד מן המזל שמלמעלה אבל גופו וממשו דהיינו בחי' חומר עצם העשב או עצם התפוח שבו מתלבש הטעם הוא מתהווה באמת מא\"ס ב\"ה הסוכ\"ע הכל יכול כנ\"ל, ולא מבחי' ממלא.\n<b>ואל</b> יפלא מאשר אנו רואים שיש ברואים הרבה בדצח\"מ וכאו\"א משונה ואינו שוה לזולתו, עם היות שכולם גשמיים, ואם הגשמיות נמשך דוקא מא\"ס ב\"ה מאין",[["339","19","<b>כל אשר חפץ הוי' עשה</b>: תהלים קלה, ו."],["340","20","<b>ראשית חכמה</b>: תהלים קיא, י"],["341","21","<b>לה להוות</b>: בכת\"י ב: להיות מהחכמה התהוות."],["342","22","<b>וכחה מוגבל כנ\"ל</b>: בכת\"י ב ליתא."],["343","23","<b>ומה שארז\"ל אין לך עשב מלמטה</b>: ראה לקמן ע' סא הגה\"ה מכ\"ק אדמו\"ר הצ\"צ השייכת לכאן, ומתחיל שם: שייך לתורה ע\"פ ביום השמע\"צ, הגם שאנו רואים שגם חומר העשב והתפוח נולד מכח הצומח שבארץ כו'."],["344","24","<b>אין לך עשב מלמטה</b>: ראה ב\"ר פ\"י, ו."]]],[2101920102,"יהי' התהוות שינוי המציאות שבהן מהקצה אל הקצה הלא א\"ס ב\"ה הוא אחדות פשוט בתכלית הפשיטות ואיך יולד ממנו הריבוי בהתחלקות המציאות מאד כנ\"ל. אך הענין שסיבת זה הוא לפי שההמשכה הוא ע\"י מדות חסד<sup data-n=\"345\">25</sup> דרועא ימינא גבורה דרועא שמאלא כו', והמדות הם בהתחלקות רב זמ\"ז וכך הוא שינוי הנבראים זה מזה, כגון התהוות המים מא\"ס ב\"ה הוא שנמשך ההארה ע\"י החסד לכן נתהווה מזה מים שהם בגשמיות כמו דוגמת בחי' החסד ברוחניות, ויהי<sup data-n=\"346\">26</sup> רקיע נמשך ע\"י הגבורה כו', ולפי שהמדות מתכללים זמ\"ז ויש בהם פרטי מדות רבים שונים כמו\"כ הוא ריבוי השינויים בנבראים גשמי' המתהווים מא\"ס ב\"ה על ידם שכ\"א יש לו תואר וטבע פרטי משונה מזולתו כפי אופן מהות המדה פרטי' שנמשך על ידה, ומ\"מ התהוותם הוא מאוא\"ס ב\"ה ממש ולא מהמדות עצמם שהרי הרוחני א\"א לו להוות את הגשמיות כנ\"ל, אלא שהוא עד\"מ כגרזן ביד החוצב כו' שהגם שהגרזן חוצב העץ ומחלקו לשניים עד\"מ מ\"מ האדם הוא העיקר והוא החוצב בכחו ועוצם ידו אלא שחוצב ע\"י הגרזן.\n<b>ויותר</b> יובן עד\"מ בידים עצמן שכשעושה דבר עד\"מ בידיו שמצייר ציור נאה או כותב איזה ספר שאע\"פ שהידים הם העושים ומציירים ובהם נעשתה אותה מלאכה ההיא, מ\"מ הרי מי העושה לא האדם עצמו הוא העושה, ולא יתכן לומר כלל ידיו של פלוני עשו ציור זה אלא פלוני עשה ציור זה, כי מי הכריח לידיו להתנוענע ולעשות המעשה אם לא כחו ועצמו שבכחו התנענעו הידים משא\"כ מצד עצמן הם כאבן דומם, כמו\"כ ממש הוא התהוות כל גשמי' הברואים שבעולם השפל אף שנמשכו ע\"י הספירות מים מחסד ורקיע מגבורה כו', מ\"מ א\"ס ב\"ה ממש הוא דוקא המהווה אותן שבכחו הבבע\"ג הוא שנתהוו לפי שהוא כל יכול אלא א\"ס ב\"ה הוא העושה זאת ומהוה אותם ע\"י החסד או הגבורה כו' משא\"כ החסד בעצמו לא הי' יכול להוות כן אלא השפעות רוחניות בלבד בעילה ועלול כנ\"ל, משא\"כ התהוות הגשמי' הוא מא\"ס ב\"ה דוקא רק שמהווה ע\"י הספירות כחוצב בגרזן כו', ומ\"מ לפי שעכ\"פ ההמשכה הוא ע\"י המדות לכן יש נבראים שונים כשינויי המדות שלמעלה, וזהו ענין ארץ קדמה במחשבה שארז\"ל שבחי' ארץ שהוא בחי' התהוות הגשמיות קדמה לשמים שהוא בחי' רוחני' כי התהוות הרוחני' הוא משלמעלה הימנו בבחי' השתלשלות עו\"ע משא\"כ התהוות גשמיות שהוא ע\"י א\"ס ב\"ה הסוכ\"ע דוקא כנ\"ל.\n<b>והנה</b> האדם מורכב וכלול מב' הבחי' מגשמיות ומרוחניות, שנמשכים מבחי' ממלא וסובב, כי גופו הגשמי התהוותו הוא מא\"ס ב\"ה הסוכ\"ע דוקא, שהוא הכל יכול כנ\"ל, ואמנם הנפש שבו שהיא רוחני' שהרי היא היתה במציאות גם קודם ירידתה בגוף כידוע שהנפש עם הגוף הן באמת שני דברים נפרדים ונבדלים זמ\"ז מצד עצמן כו', הנה היא נמשכת מבחי' ממכ\"ע דהיינו שנמשכת בבחי'",[["345","25","<b>חסד דרועא ימינא</b>: תקו\"ז בהקדמה ד\"ה פתח אליהו (יז, א)."],["346","26","<b>ויהי רקיע</b>: בראשית א, ו."]]],[2101920103,"השתלשלות כעלול מעילה שלמעלה ממנו, ודרך פרט נה\"ב נמשכת מפני שור שבמרכבה דעשי' ונה\"א מבחי' אדם שעל הכסא כו' והמה רוחניי', ובכדי שתתחבר הנפש ותתלבש בגוף דהיינו הרכבת רוחניות בגשמיות ובשרשן למעלה הוא התחברות ממלא וסובב, שמצד עצמן הם רחוקים ומובדלים בערך זמ\"ז כנ\"ל, הוא ע\"י התורה שהיא המחברת אותם יחד, וזהו שהתורה נק' שלום שהשלום הוא ענין התחברות שני הפכים כידוע, והכח הזה בתורה הוא לפי שיש בה בחי' שלמעלה מב' הבחי' הנ\"ל הנק' ממלא וסובב שהם בחי' ח\"ע ורצון העליון כנ\"ל, אבל בתורה יש עוד בחי' שלמעלה מעלה משניהם, והוא המחבר שניהם יחד. והענין הוא דהנה ידוע שהרצון יש בו ב' בחי', א' והוא הנק' רצון סתם, והב' והוא הנק' חפץ והוא בחי' פנימי' הרצון, משא\"כ רצון בעצמו הוא רק בחי' אחוריים, וע\"ז נאמר אחור<sup data-n=\"347\">27</sup> וקדם צרתני, וראית<sup data-n=\"348\">28</sup> את אחורי, הוא בחי' הרצון, אבל פני פי' פנימיות שהוא החפץ לא יראו.\n<b>וביאור</b> זה הוא כי ל' הרצון נופל גם על דבר שאין לו חשק ותענוג בו רק שרוצה בו מצד איזה תכלית שיצא לו ממנו, כענין שארז\"ל<sup data-n=\"349\">29</sup> כופין אותו עד שיאמר רוצה אני, הרי אף שבא לו מחמת מורא שייך לומר ע\"ז רוצה אני, שהרי מ\"מ יש לו רצון בזה אף שאינו בחשקו רק מחיצוניותו כו', וכן כל דבר כל שאינו מתענג ממש מפעולת אותו הדבר רק שהוא סיבה להדבר המעונג הנה שייך ע\"ז רק לשון רצון כמו החורש והזורע כו' או העוסק במו\"מ וקונה ומוכר כו', שהתכלית מזה הוא צמיחת הפירות או ריוח הממון וע\"ז שייך לשון חפץ שיש לו חשיקה בזה וחפץ וחומד בלקיטת הפירות ובקובצו הממון משא\"כ החרישה והזריעה שמתחלה או העסק לא שייך לומר שחפץ בהם רק שרוצה בהם משום דלא סגי בלא\"ה ומי שטרח תחלה כו', אבל אין לו חפץ בהם שאילו הי' באפשרי לו להשיג דבר הנחמד והמעונג לו מבלעדם לא הי' אפי' רוצה בהם כלל, נמצא שחפץ הוא תכלית הרצון ופנימיותו, וכמו\"כ יובן מזה הנמשל למעלה שבחי' ארץ קדמה במח' היינו שנמשכת מבחי' רצה\"ע רצון בלבד, ובאמת שגם הרצון הוא למעלה מן החכמה, שהוא ית' אינו בגדר בחי' חכמה כלל, ומחכמה ואילך הוא בחי' השתלשלות שהוא בחי' ממכ\"ע והיינו בחי' התהוות הרוחניות בעו\"ע כנ\"ל, משא\"כ הרצון הוא המשכת והטיית עצמותו ית' ממש הסוכ\"ע, ומזה נתהווה בחי' ארץ שהוא בחי' הגשמיות שא\"א לו להתהוות אלא ע\"י המשכת כח ועוז הא\"ס ב\"ה שהוא הבבע\"ג וכל יכול כנ\"ל, והיינו בחי' הרצון שלו שרוצה הוא בהתהוות העשי' גשמיות, אמנם מ\"מ עדיין אינו רק בחי' רצון בלבד ולא חפץ, שהרי לא כל עיקר המכוון ותכלית השלימות הוא רק שיתהוו שמים וארץ ואשר בהם אלא לכבודי בראתיו כו' הוא בחי' קיום המצות שיהי' עי\"ז שבהם הוא שיש לו ית' חפץ ותענוג, כענין נחת רוח לפני שאמרתי ונעשה כו', משא\"כ מה שבשביל זה מתקיימים כל סדרי בראשית משום דלא סגי בלא\"ה כו' לא שייך לומר שחפץ בהם שהרי אינו",[["347","27","<b>אחור וקדם צרתני</b>: תהלים קלט, ה."],["348","28","<b>וראית את אחורי</b>: תשא לג, כג."],["349","29","<b>שארז\"ל כופין אותו עד שיאמר רוצה אני</b>: ר\"ה ו, א. וראה רמב\"ם הל' גירושין ספ\"ב."]]],[2101920104,"חפץ בהתהוותם מצד עצמותם רק שרוצה בהם בשביל התכלית שימצא מהם אח\"כ בקיום המצות והוא רק בחי' חיצוניות, ומ\"מ הרי הוא רצונו ית' ממש שבבחי' א\"ס, אף שהוא בחי' חיצוניותו ית', וגדול כחו גם להוות בחי' הגשמיות שא\"א להתהוות מבחי' חכמה אף שהוא בחי' פנימיות, לפי שהוא בחי' החכמה שבהשתלשלות שבבחי' גבול, משא\"כ הוא ית' הכל יכול כנ\"ל, והוא ורצונו אחד וד\"ל.\n<b>והנה</b> בחי' החפץ הזה היא התורה כמ\"ש ה'<sup data-n=\"350\">30</sup> חפץ למען צדקו יגדיל תורה ויאדיר, והיינו בחי' תרי\"ג מצות שהם כללות כל התורה כולה שהם חפצו ית' שיש לו תענוג עד\"מ ברצון זה שבמצות וכמאמר אשר קדשנו במצותיו פי' אשר הוא בחי' תענוג דהיינו דבר המאושר וטוב ויפה ושם הם שרש המצות ומשם נמשך להיות קדשנו במצותיו כו', והוא המחבר את בחי' הרצון ובחי' החכמה שהם בחי' ממלא וסובב כנ\"ל, כי מחמת התענוג והחפץ שיש לו במצות הוא גורם להיות ירידות והתלבשות הרצון להוות סדרי בראשית הארץ וכל אשר בה בגשמיות, וכן להיות ירידות החכמה להוות השמים וכל אשר בהם ברוחניות והוא בחי' סובב וממלא כנ\"ל, שמהן נמשכים ארץ ושמים כו'. וז\"ש רז\"ל שהעוסק בתורה משים שלום בפמשמ\"ע ובפשמ\"ט, פי' שגורם התחברות החכמה והרצון שהם בחי' ממלא וסובב וזהו בפמלי' של מעלה, וישנם ג\"כ בתורה עצמה כי אורייתא<sup data-n=\"351\">31</sup> מחכמה נפקת הוא בחי' ממכ\"ע והרצון שבמצות הוא בחי' סוכ\"ע והתחברותם יחד הוא ע\"י החפץ שבהם שהוא תכלית פנימי' החכמה ופנימי' הרצון כו', וכן בפשמ\"ט היינו בנבראים שכאו\"א כלול מב' הבחי' ממלא וסובב כי כאו\"א יש לו גוף ונפש וחיות וקיום הגוף הוא מבחי' סוכ\"ע שהוא בחי' המשכות רצה\"ע שבו והנפש נמשכת מבחי' ממכ\"ע (כי אפי' בחי' צומח יש לו נפש הצומחת שהוא מלבד מנפש הדומם שיש גם בו לקיום גשם חומרו כו', וגם בחי' הדומם יש בו נפש המרכבת מפני שכלול מארמ\"ע כמ\"ש בגמ' אין<sup data-n=\"352\">32</sup> מוציאין אש לא מן האבנים ולא מן העפר, פי'<sup data-n=\"353\">33</sup> צפיעי בקר כו', מלבד העפר ממש שהוא יסוד פשוט, ולכאורה הנפש שבו שהוא לקיום חומרו הגשמי ממש הוא מבחי' סוכ\"ע דהיינו בחי' רצה\"ע שיש בהתהוות העפר וכנ\"ל דארץ קדמה כו' הגם שגם העפר יש בו חומר וצורה אין הצורה דבר נוסף על החומר כמו הנפש על הגוף רק שהיא הצורה של החומר, איך שיהי' ד\"מ מדת העפר ושיהי' עגול כו', ואף שצורה זו היא עפ\"י החכמה היינו שכולם<sup data-n=\"354\">34</sup> בחכמה עשה הרצה\"ע, אבל אינו ענין התלבשות החכמה ממש בתוך העפר כמו שהוא בצומח שנפש הצומחת מתלבש בגוף הדבר הצומח בבחי' תוספות על חומרו הגשמי כנ\"ל בענין אין לך עשב שאין לו מזל שהמזל רק מגדל העשב ונותן בו טעם כו'.",[["350","30","<b>ה' חפץ למען צדקו יגדיל תורה ויאדיר</b>: ישעי' מב, כא."],["351","31","<b>אורייתא מחכמה נפקת</b>: זח\"ב סב, א. פה, א. קכא, א. ועוד."],["352","32","<b>אין מוציאין אש לא מן האבנים ולא מן העפר</b>: ביצה לג, א."],["353","33","<b>פי' צפיעי בקר</b>: ע\"פ יחזקאל ד, טו. שו\"ע אדה\"ז או\"ח סתק\"ב ס\"א. וש\"נ."],["354","34","<b>בחכמה עשה הרצה\"ע</b>: בכת\"י ב: בחכמה עשית הארץ וכל אשר עלי'."]]],[2101920105,"<b>ולפי\"ז</b> צ\"ל מ\"ש בלק\"א<sup data-n=\"355\">35</sup> בשם האריז\"ל שגם באבנים ועפר יש בחי' נפש וחיות רוחניות דהיינו בחי' התלבשות אותיות הדיבור מעשרה מאמרות המחיות ומהוות את הדומם להיות יש כו', מה ענין העש\"מ שנמשכים מבחי' חכמה להוות מהות חומר הדומם כמו העפר שהרי נת\"ל שהתהוותו הוא מבחי' רצה\"ע דוקא כנ\"ל. ואולי הוא כמ\"ש<sup data-n=\"356\">36</sup> במ\"א שהאותיות יש בהם ב' בחי' א' חיצוניותן ונמשך מבחי' גלגלתא חיצוני' הכתר, והוא הרצון כנ\"ל, ופנימיותן דהיינו המכוון שיש בצירוף כמה אותיות יחד בתיבה שלימה הוא שנמשך מהחכמה כמ\"ש מצרף לחכמה, שכח הצירוף לצרף האותיות הוא שנמשך מהחכמה כו' ולא עצם האותיות וד\"ל. (מיהו לפי משנ\"ת ע\"פ יביאו לבוש מל' כו' שהסובב אינו מאיר אלא ע\"י אמצעות הממלא א\"כ מבואר שיש בעפר ג\"כ חיות המתלבש בתוך ממכ\"ע וכ\"ה כי יש ג\"כ בחי' עפר באצי' כמ\"ש ומן העפר אשר בקרקע המשכן כו' וזהו שרש דשרש דעפר הזה, ועיין בזוהר וישלח ע\"פ ויאבק מאן עפר כו'). והנה החפץ שבתורה הוא הגורם המשכותם מבעל הרצון ומקשרם ומחברם יחד ומשים שלום ביניהם כנ\"ל וד\"ל.\n<b>והנה</b> יום<sup data-n=\"357\">37</sup> מ\"ת נק' יום חתונתו כו', אף שהוא משל גשמי מאד, אבל כן הדבר באמת בנמשל למעלה שהקב\"ה נק' חתן<sup data-n=\"358\">38</sup> מלשון חות דרגא כלומר שמשפיל עצמו להיות משפיע לכנס\"י וכללות נש\"י נק' לכך בשם כלה על שהם בחי' מקבלים ממנו ית',וההשפעה עצמה היא התורה, דאורייתא מחכ' נפקת והיינו חכמתו ורצונו ית' והוא כמשל טפת דכורא שנמשכת ממוח החתן אל הכלה כו', ולכן נק' יום חתונתו. אמנם באמת יש בזה ב' בחי', א' יום הקדושין שהחתן מקדש את הכלה ונעשית אשתו לכל דבר, ע\"י שעומדים תחת חופה אחת, והב' הוא בחי' היחוד וביאה בהשפעת הטיפה להכלה כו'. וזהו ענין ההפרש בין יום מ\"ת שביוכ\"פ שעדיין ההארה בבחי' מקיף על הכלה וכעין<sup data-n=\"359\">39</sup> טבעת קידושין עגול שהחתן נותן לכלה ובשמע\"צ הוא המשכה שהמקיף נעשה פנימי והוא ענין המשכת הטיפה להכלה כו', ובנתיים צ\"ל ז' ימי הסוכות שאז נמשך בחי' דעת כדי שלהיות ראוי להשפיע הטפה בשמו\"ע. כי הנה כמו עד\"מ בגשמיות הדעת הוא הכלי להמשכה הטפה שאם יסיח דעתו מן הדבר לא יזריע ולכן נאמר והאדם<sup data-n=\"360\">40</sup> ידע את חוה, ידע דוקא, וכך גם למעלה א\"א להיות נמשכת טפת החכמה הוא בחי' התורה דמחכמה נפקת אלא ע\"י הדעת דוקא שהוא הכלי שבו ועל ידו נמשכת הטיפה הוא הארת",[["355","35","<b>בלק\"א בשם האריז\"ל שגם באבנים ועפר</b>: תניא שעהיחוה\"א פ\"א."],["356","36","<b>כמ\"ש במ\"א . . כמ\"ש מצרף לחכמה</b>: ע\"פ משלי יז, ג. וראה ס' מאמרי אדהאמ\"צ חתונה ח\"ב ע' תקעב. מאמרי אדה\"ז נ\"ך ע' קכ. ובמ\"מ שם."],["357","37","<b>יום מ\"ת נק' יום חתונתו</b>: שה\"ש ג, יא. תענית כו, ב."],["358","38","<b>חתן מלשון חות דרגא</b>: ראה יבמות סג, א."],["359","39","<b>וכעין טבעת קידושין עגול שהחתן נותן לכלה</b>: ראה תו\"א ויגש מד, א. שם דרושים למג\"א קכא, ד. לקו\"ת שה\"ש מח, א. ס' מאמרי אדהאמ\"צ דרושי חתונה ח\"ב ע' תרג וע' תרכט ואילך. אוה\"ת ברכה ע' א'תתמה. ובכ\"מ."],["360","40","<b>והאדם ידע את חוה</b>: בראשית ד, א."]]],[2101920106,"החכמה להאיר בכנס\"י, שהדעת הוא המחברם ומייחדם כו'. וכך יובן ג\"כ בנפש כדכתיב דע<sup data-n=\"361\">41</sup> את אלקי אביך כו', דהיינו שלא יהי' ההתבוננות בבחי' מחשבה בלבד שיהי' מחושבי שמו כחושב דבר שחוץ ממנו ואין נוגע לו באמת שאזי לא יתהווה מזה שום התפעלות כלל, אלא שיתקע דעתו ויקשר מחשבתו בחוזק כו' בבחי' ביטול המציאות ממש, ואז אח\"כ כשיעסוק בתורה ימשיך ההארה הנמשלת לטפה משום דמחכמה נפקת כו'.\n<b>והנה</b> אף שהיא מצוה הנוהגת בכל עת ובכל יום ויום צ\"ל כן ושזהו עיקר היסוד במצות ק\"ש שנאמר שמע<sup data-n=\"362\">42</sup> ישראל אחד ואהבת, וא\"א להיות התפעלות ממה שיתבונן בבחי' אחד ובשכמל\"ו יחו\"ע ויחו\"ת, אם לא ע\"י תקיעת הדעת, וזהו שמע ישראל פי' שמע והתבונן כו', ואח\"כ והיו הדברים האלה אשר אנכי מצוך היום, היינו בחי' המשכת התורה שהיא טפת החכמה שיכולה להיות נמשכת לפי שיש בחי' דעת שהוא הכלי להמשכה זו, עכ\"ז הנה התורה נדרשת בכלל ופרט, ומה שהוא בפרט בכל יום ויום ישנו בכלל בחודש תשרי<sup data-n=\"363\">43</sup> שנק' ראשית לכל השנה כולה, כמשל הראש שכולל חיות כל האיברים כו', והמשכת בחי' הדעת לכל השנה כולה הוא בסוכות שאז נמשך בחי' דעת לכללות נש\"י, והיינו ע\"י הלולב ומיניו כי ד'<sup data-n=\"364\">44</sup> מינים כלולים שבלולב הם כנגד ד' אותיות הוי' שהוא בחי' חכמה בחי' ביטול שעי\"ז נמשכת בחי' הביטול בכלללות נש\"י, והוא בחי' המשכת הדעת לכנס\"י שיהי' בהם כח ההתקשרות לקשר מוחו ותבונתו בהתבוננות בגדולת א\"ס ב\"ה שעי\"ז יוכל להיות אח\"כ המשכת הטיפה היא התורה כו', והכח הזה הוא דוקא ע\"י ד' מינים גשמיים המכונים כנגד ד' אותיות הוי' ע\"ש בחי' הביטול שבהם (כמשי\"ת לקמן בביאור), ולא ע\"י בחי' ביטול ברוחניות שאף גם אם יעמיק בהתקשרות דעתו בהתבוננותו עד שיבא לידי ביטול היש לא ימשיך כלל המשכה זו שע\"י הלולב ולא יצא בזה ידי חובת לולב אלא צריך לנענע ד' מינים גשמיים דוקא ואז יוצא י\"ח אף שאין בחי' הביטול בנפשו אז כו'. והטעם הוא עפ\"י הנז\"ל בענין ארץ קדמה כו' שבחי' גשמיות דוקא נתהווה מא\"ס ב\"ה הסוכ\"ע שלא בדרך השתלשלות עו\"ע משא\"כ בחי' רוחני' הוא בדרך השתלשלות עילה מעילה שלמעלה ממנו גבוה מעל גבוה כו'. ולכן ע\"י ד' מינים גשמים דוקא שנמצא בהם בחי' הביטול בגשמיות דוקא הוא שיכולים להמשיך בחי' דעת חדש מא\"ס ב\"ה הסוכ\"ע שמשם נלקחים ד' מינים אלו הגשמיים כו', משא\"כ בחי' ביטול רוחני שנלקח מעילתו ועילתו מעילה שלו ואינו מעורר כלל כ\"כ למעלה כו' וד\"ל.\n<b>והנה</b> ז' ימי הסוכות הם ז' ימי המשתה שאחר יוכ\"פ שהוא יום חתונתו, פי' יום הקידושין זה יום מ\"ת, כי יוכ\"פ וסוכות שניהם בחי' א' אלא שיוכ\"פ",[["361","41","<b>דע את אלקי אביך</b>: דה\"א כח, ט."],["362","42","<b>שמע ישראל אחד ואהבת . . והיו הדברים</b>: ואתחנן ו, ד-ו."],["363","43","<b>תשרי שנק' ראשית לכל השנה כולה</b>: ראה גם בעה\"ט עקב יא, יג."],["364","44","<b>ד' מינים כלולים שבלולב הם כנגד ד' אותיות הוי'</b>: פע\"ח שער הלולב פ\"א ופ\"ב. ועוד. ט\"ז או\"ח סתרנ\"א סקי\"ד (מהב\"י שם ורקאנטי ס\"פ אמור)."]]],[2101920107,"הוא בבחי' עלי' ממטה למעלה ובסוכות נמשך הארה זו ממעלה למטה אבל עדיין הוא רק בבחי' מקיף מלמעלה כמו ביוכ\"פ שהוא רק בחי' קידושין ששניהם תחת חופה א', והוא בחי' תשובה עילאה פי' בחי' תעלומות לב שהוא למעלה מהיות בא לידי גילוי בהתגלות רק בבחי' מקיף על הלב, והיינו בחי' פנימיות בינה, כי<sup data-n=\"365\">45</sup> עיקר תשובה בלב הוא בחי' בינה לבא הנק' תשובה עילאה, שעי\"ז מעורר ג\"כ למעלה בחי' המשכת מקיפים עליונים שמשם מקור הסליחה והמחילה כמ\"ש כי ביום<sup data-n=\"366\">46</sup> הזה יכפר עליכם, כלומר בבחי' מקיף שממעל כו' ועי\"ז מתמלאים כל החסרונות והפגמים שנעשו בכל השנה כולה ע\"י ביטול מ\"ע או עשיית ל\"ת כו', ונעשים זדונות כזכיות, פי' שמתמלאים האורות של המצות כאילו הי' מלא מצות מעיקרו כו', והוא גבוה במדריגה מבחי' מ\"ת שבשבועות שהוא המשכות האורות ע\"י מעשה המצות בפו\"מ, והיינו מבחי' מקור התו' ומצות שמשם יוכל להיות כפרה למלאות כל הפגמים שבתורה כמשל מעיין שנחרב ויבש שא\"א למלאותו אלא ע\"י שיחפרו בעומק יותר כו'.\n<b>וזהו</b> יום חתונתו זה מ\"ת פי' מתן תורה שכנגד בחי' בע\"ת שאין<sup data-n=\"367\">47</sup> צ\"ג יכולים לעמוד במקומם ובסוכות נמשכת הארה זו ממעלה למטה אבל הוא ג\"כ עדיין בבחי' מקיף ממעלה בלבד, וזהו ענין מצות הסוכה כי<sup data-n=\"368\">48</sup> בסוכות הושבתי אתכם כלומר בבחי' סכך שמקיף ממעלה והיינו ג\"כ מבחי' פנימי' בינה שביוכ\"פ אלא שאז הוא ממטה למעלה, בבחי' תשובה שהוא השבה ממטה למעלה, וכאן הוא בבחי' המשכה דהיינו בחי' שמחה, אם<sup data-n=\"369\">49</sup> הבנים שמחה, ושמחה זו היא ג\"כ בבחי' מקיף בלבד, משום שא\"א להכילה בפנימיות כו' וכנ\"ל בענין תעלומות לב כו', ואח\"כ בשמיני עצרת הוא שנמשך בבחי' פנימי', פי' שמה שהי' בבחי' מקיף ובהעלם נכנס בבחי' פנימיות להיות בגילוי בהמקבל, וע\"ז נאמר לשמש<sup data-n=\"370\">50</sup> שם אוהל בהם והוא כחתן יוצא מחופתו ישיש כגיבור לרוץ אורח, פי' שמתחלה הארת השמש שהוא בחי' סוכ\"ע הוא בבחי' אוהל ומקיף מלמעלה, והיינו ביוכ\"פ ובסוכות עם היות כי נק' יום חתונתו, היינו כחתן זה שמתחלה הוא רק תחת חופה א' עם הכלה ונותן לה טבעת קידושין, שהוא בחי' מקיף בלבד, ואח\"כ יוצא מחופתו ואז ישיש כגיבור לרוץ אורח, היינו בחי' אורח ושביל להשפעת הטפה בהכלה, והיינו שיהי' נמשכת התורה להתגלות בפנימיות ישראל ממש, וזהו ביום השמיני עצרת כו', ע\"י שמתחלה היו ז' ימי הסוכות שהם ז' ימי המשתה שאז נמשך בחי' הדעת בכנס\"י שהוא הכלי להשפעת הטיפה בשמע\"צ הוא בחי' התורה, דאורייתא מחכמה נפקת כטפה הנמשכת מן המוח כו'. ועם זה יובן בטוב טעם מה שנקבעה שמחת התורה ביום שמע\"צ דוקא, הגם שגם לוחות אחרונות ניתנו ביוכ\"פ, כי ביוכ\"פ עדיין הוא בבחי' מקיף בלבד",[["365","45","<b>כי עיקר תשובה בלב</b>: תניא פכ\"ט (לו, ב). וראה רמב\"ם הל' תשובה פ\"ב ה\"ב."],["366","46","<b>כי ביום הזה יכפר עליכם</b>: אחרי טז, ל."],["367","47","<b>שאין צ\"ג יכולים לעמוד במקומם</b>: ברכות לד, ב."],["368","48","<b>כי בסוכות הושבתי</b>: ע\"פ אמור כג, מב."],["369","49","<b>אם הבנים שמחה</b>: תהלים קיג, ט."],["370","50","<b>לשמש שם אוהל בהם והוא כחתן</b>: שם יט, ה-ו."]]],[2101920108,"כנ\"ל, אבל בשמע\"צ הוא גמר יום חתונתו, שאז הוא בחי' יחוד חתן וכלה שנמשך הטפה כו'<sup data-n=\"371\">51</sup>, ולכן אז שייך השמחה מהתורה שהוא בחי' הטפה שנמשכת ומתפשטת בפנימיותם.\n<b>והנה</b> עיקר ענין השמחה עם התורה שבשמ\"ע הוא מה שעושים הקפות שמקיפים עם הס\"ת את המקום שקורין עליו בספר בכל השנה. והענין בזה הוא לרמוז על כוונה הנ\"ל בענין שמים וארץ שהם חתן וכלה דארץ קדמה כו', כי הנה הס\"ת עצמה הוא בחי' מקרא בעשי' שהרי כ\"כ נשפלו ד\"ת שבה עד שנתלבשו בעשי' גשמיית שבדיו גשמי ועל קלף גשמי, אבל הקריאה שקורין בס\"ת בדיבור פה הוא בחי' רוחניות שהרי האותיות המה רוחניים כי כ\"ב אותיות קבועים בנפש כדת\"א<sup data-n=\"372\">52</sup> לנפש חי' לרוח ממללא כו', שהנפש שבאדם היא המדברת כי היא מליאה אותיות, הגם דאחה\"ע יוצא מהגרון בומ\"ף מהשפתיים כו', שה' מוצאות אלו הגשמיי' מהם הביטוי בא, היינו שהם בחי' כלים בלבד להאותיות, שאותיות<sup data-n=\"373\">53</sup> הנפש באות ונמשכות בה' מוצאות אלו שבהן ועל ידן הוא שיוצאי' במבטא כל כמה אותיות במוצא השייך להם ובבא האות בהנפש הוא מכה באותו מוצא וגורם תנועה זו כפי מזגה ותכונתה כו' כמ\"ש במ\"א, וז\"ש בעל ס\"י<sup data-n=\"374\">54</sup> כ\"ב אותיות קבען בפה בבחי' קביעות ממש, ומ\"מ שרשן בנפש עצמה והיינו שנמשכים מקדמות השכל וכמ\"ש בחכמה<sup data-n=\"375\">55</sup> יסד ארץ, וכדפי' בזוהר<sup data-n=\"376\">56</sup> אבא יסד ברתא כו', וכנראה בעליל ממה שהתינוק אינו יכול לדבר מפני שהוא מחוסר חכמה שכל, נמצא שהאותיות המה רוחניים ונמשכים מן השכל כנ\"ל, משא\"כ האותיות שבס\"ת הנכתבי' בדיו גשמי ע\"ג קלף המה גשמיים ממש, ומה שמקיפים עם הס\"ת גשמיות את המקום שקוראין עליו בדיבור פה הוא להורות שבחי' ארץ קדמה לשמים במחשבה, שהגשמיות נלקח מא\"ס ב\"ה הסוכ\"ע דוקא שהוא הכל יכול עד שתתלבש התורה בגשמיות משא\"כ בחי' דיבור שקוראים בתורה הוא בבחי' רוחניות עדיין ואינו אלא בבחי' השתלשלות עו\"ע כו', ועושים זה בשמ\"ע שאז הוא גמר יום חתונתו זמן היחוד ואז מראי' זה שארץ בחי' המקבל קדמה בשרש כל השרשים לשמים המשפיעים כו', וכן בשעת נישואי חתן וכלה בגשמיות נוהגים שהכלה מקפת את החתן תחת החופה והוא ג\"כ מטעם הנ\"ל וכמ\"ש<sup data-n=\"377\">57</sup> נקבה תסובב גבר והיינו מצד שרשה כו' וד\"ל.\n<b>ועתה</b> יובן פי' הפסוק ביום השמיני עצרת תהי' לכם עצרת לשון קליטה פי' כי הגם שנמשכה הטיפה אל הכלה בשמ\"ע עדיין יש חשש שלא תהי' פולטת",[["371","51","<b>כו'</b>: בכת\"י ב: כו' ואז משים שלום בפשמ\"ע ובפשמ\"ט."],["372","52","<b>כדת\"א לנפש חי' לרוח ממללא</b>: בראשית ב, ז."],["373","53","<b>שאותיות הנפש באות ונמשכות בה' מוצאות אלו . . כמ\"ש במ\"א</b>: ראה תניא אגה\"ק ס\"ה (קז, א ואילך). ובהנסמן בליקוט פירושים ומ\"מ שם."],["374","54","<b>ס\"י כ\"ב אותיות קבען בפה</b>: פ\"ב מ\"ג."],["375","55","<b>בחכמה יסד ארץ</b>: משלי ג, יט."],["376","56","<b>בזוהר אבא יסד ברתא</b>: זח\"ג רמח, ב. רנו, ב. ועוד."],["377","57","<b>וכמ\"ש נקבה תסובב גבר</b>: ירמי' לא, כא."]]],[2101920109,"ח\"ו ולזאת צ\"ל שתקלט הטפה במעיה עד שתתעבר ותוליד כו', וכמו\"כ בנשמות ישראל שמקבלים בחי' הטפה בשמ\"ע היא השפעת התורה שהיא טיפת החכמה הנשפעת בהם ולכן מתחילין לומר אז מוריד הגשם היא התורה שנמשלה לגשם, ובלשון הזוהר נק' שערות והיינו כמ\"ש קווצותיו<sup data-n=\"378\">58</sup> תלתלים תילי תילים של הלכות כי כמו השערות שהרבה שערות יוצאים מן המוח, וכאו\"א יש לה גומא מיוחדת ואין שתי שערות יונקות מגומא א', וכן טיפי מטר שיוצאים טיפין טיפין וכל טפה יש לה דפוס בפ\"ע ואין שני טיפין יוצאי' ממקום א', וכך הוא בחי' הלכות התורה שהם רבים ועצומים לאין קץ ממש וכולן נמשכות מח\"ע, אבל כל א' היא המשכה פרטיות מיוחדת, וכמ\"ש<sup data-n=\"379\">59</sup> במ\"א שזהו ענין מסלסל בשערו להפריד ההלכות זמ\"ז שלא יתערבו ויהי' קליעות שער והיינו ע\"י התירוצים שנק' פירוק\"א, כלומר כמפרק דבר כי הקושי' מערבת כו'.\n<b>והנה</b> המשכת התורה שבשמ\"ע נאמר ע\"ז עצרת תהי' לכם שתהי' נקלטת ונתפסת היטיב בלב איש ישראל להיות מזה כן על כל השנה כולה בק\"ש אחד ואהבת ע\"י הדעת ואח\"כ והיו הדברים כו', וכמו\"כ למעלה ע\"י קליטת הטפה בשמ\"ע נעשה אח\"כ הלידה בז' של פסח כו', והטעם לקליטת התורה בשמ\"ע דוקא ולא בשבועות ויוהכ\"פ שאז ניתנו ב' הלוחות, הוא מפני שבשבועות נאמר ויאמר ה', וידבר ה', שהי' בבחי' דיבור עדיין, וביוכ\"פ הי' בלב בחי' תשובה, ועיקר תשובה בלב, אבל בשמ\"ע הוא בבחי' מעשה, וארץ קדמה כו', לכך נקלט היטב להיות עצרת לכם וד\"ל.",[["378","58","<b>קווצותיו תלתלים תילי תילים של הלכות</b>: שה\"ש ה, יא. עירובין כא, ב."],["379","59","<b>וכמ\"ש במ\"א שזהו ענין מסלסל בשערו</b>: ראה תו\"א מקץ לא, ד. לקו\"ת אחרי כז, א. שה\"ש ו, ג ואילך. [ובהנסמן בתחילת המאמרים שם]. תו\"ח בראשית רכד, ד. ס' מאמרי אדהאמ\"צ דרושי חתונה ח\"ב ע' תקמ, תקמח, תשכו ואילך. ובכ\"מ."]]],[2101920110,"<h3>להבין שרשי הדברים</h3>\n<b></b><b>ביאור על הדרוש שמע\"צ הנ\"ל</b>\n<b>להבין</b><sup data-n=\"380\">1</sup> שרשי הדברים הנ\"ל, תחלה יש להבין ענין המשכת הדעת ע\"י ד' מינים אלו דוקא מה נשתנו אלו מכל מיני צמיחה שבעולם להיות ההמשכה על ידם דוקא ושהם דוקא מכוונים לנגד ד' אותיות הוי'. הנה ביאור ענין<sup data-n=\"381\">2</sup> זה ממורי הה\"מ ז\"ל עפ\"י הקדמה א', והוא מה שגבי יוצאי ירך יעקב כתי' ע'<sup data-n=\"382\">3</sup> נפש לשון יחיד וגבי עשו כתי' נפשות עשו ל' רבים, כי זהו כלל גדול שבכ\"מ שימצא ריבוי מדריגות שונות אזי כשהם כאו\"א בבחי' יש ודבר בעצמותו א\"א להיות ביניהם אחדות משא\"כ כשהם בבחי' ביטול נעשה אחדות ביניהם אף כי רבים המה כו', וכמ\"ש המשל<sup data-n=\"383\">4</sup> ופחד עמו עושה שלום במרומיו, וענין השלום היינו בין שר של מים ושר של אש שהם ב' הפכים בעצם ועכ\"ז אין מכבין זא\"ז, והיינו ע\"י שהמשל ופחד עמו שלכך הוא עושה שלום כו', דהיינו שמתגלה הארה שלמעלה מערך השגתם ואזי מתבטלים ממציאותם התמידי כאשר הם בחי' יש בפ\"ע כשהשגתו שלימה וכל מהותו על מצבו ומעמדו ע\"י הפחד מגילוי הנורא הזה, וע\"י ביטול זה שכ\"א ואחד מתבטל ממציאותו הנה הוא יכול להתחבר גם עם זולתו אף שהוא הפכי ומנגד לו שזה אש וזה מים כי כ\"ז לא שייך אלא כשהם בבחי' יש בעצמותם וכאו\"א מוגבל ומוגדר בטבעו ואזי אינו יכול לסבול את זולתו שמהותו מנגד למהות היש כו', משא\"כ כשמתבטל ממהותו ואובד ישותו עד שלא ירגיש שזולתו מנגד לו, והיינו בחי' אין שמתפשט בהם מגילוי הארה הנ\"ל שלמעלה מערכם ואז המים אינם מים והאש אינו אש עד\"מ ונעשים כולם כא' ומתחברים יחד לפי שכולם בבחי' אין כו', וזהו עושה שלום במרומיו בין שר של מים לשר של אש שכשהם בבחי' יש אינם בשלום זע\"ז שא\"א להם להתחבר כו', אבל הוא ית' עושה שלום ביניהם ע\"י גילוי אורו עליהם בתוס' אור ואז נעשו שניהם בבחי' אין ואובדים ישותם ומתחברים יחד וד\"ל.\n<b>וכך</b> הוא ג\"כ ביוצאי ירך יעקב שהם היו בבחי' ביטול אליו ית' לכן נאמר בהם ע' נפש שעם היותם ע' בחי' מחולקות היו כולם נפש א' ממש מצד בחי' האין שבהם כנ\"ל, משא\"כ בעשו כתיב נפשות ל' רבים לפי שהם בבחי' יש ודבר בעצמותו ואין בהם בחי' הביטול כו', ולפי שכ\"א מובדל במהותו ומדריגתו מזולתו לכך אינם יכולים להתחבר יחד כי זולתו מחולק ממנו במהותו ושניהם יש ודבר ואינם סובלים זא\"ז. ואמנם מה שנאמר ביעקב דוקא ל' זה דע' נפש ל' יחיד הוא מפני כי באמת מדריגות יעקב בפרט הוא מבחי' האין בחי' הביטול המחבר ב' הפכים והוא העושה שלום כו' כי הוא בריח התיכון המבריח מן הקצה אל הקצה ונק' יושב אוהלים",[["380","1","<b>להבין שרשי הדברים הנ\"ל</b>: זהו נוסח שני ובאריכות יותר של ביאור ד\"ה ביום השמע\"צ. וראה לעיל במ\"מ בתחילת הביאור נוסח הראשון, ובמ\"מ לעיל בתחילת המאמר."],["381","2","<b>ענין זה ממורי הה\"מ ז\"ל</b>: ראה לעיל בנוסח הראשון, ובמ\"מ שם."],["382","3","<b>ע' נפש . . נפשות עשו</b>: ויגש מו, כז. וישלח לו, ו. ראה ויק\"ר פ\"ד, ו. פירש\"י ויגש מו, כו."],["383","4","<b>המשל ופחד עמו עושה שלום במרומיו .ֿ. בין שר של מים ושר של אש</b>: איוב כה, ב. במד\"ר פי\"ב, ח."]]],[2101920111,"שמחבר ב' אוהלים שהן חו\"ג המחולקים מצד עצמם זמ\"ז והיינו ג\"כ למטה בחי' אברהם ויצחק ויעקב<sup data-n=\"384\">5</sup> שלימו דאבהן הוא המחברם, וזהו ליעקב<sup data-n=\"385\">6</sup> אשר פדה את אברהם כו' וכמ\"ש במ\"א. לכן ביוצאי יריכו הוא שנאמר לשון ע' נפש ל' יחיד כי הוא המחברם כו' וד\"ל.\n<b>ועפי\"ז</b> יובן ג\"כ ענין הלולב ומיניו שבהן ועל ידן דוקא ממשיכים בחי' הדעת לנוק' שהוא המשכת בחי' אין וביטול המחבר כו', מפני שהם הם ג\"כ מבחי' זו דאין וביטול, כי הלא ידוע דכל הדברים הגשמיים יש להן שרש למעלה ברוחניות וכפי מציאות אותו השרש ברוחניות כך בדוגמתו הוא מציאות אותו הדבר בגשמיות, וכמו ענין עה\"ח ועה\"ד שהיו עצים גשמיים, ואעפי\"כ אם אכל מעה\"ח וחי<sup data-n=\"386\">7</sup> לעולם וכשאכלו מעה\"ד נפקחו עיניהם כו' לפי שנשתלשלו ממש משרש עה\"ח ועה\"ד שלמעלה וכמ\"ש במ\"א, וגם כאן הנה ד' מינים הנ\"ל נמשכים מבחי' אין המחבר ב' הפכים שהוא הגורם בחי' ההתאחדות ברוחניות וממנו נשתלשל בחי' זו בגשמיות עד שגם בגשמיות ימצא בהם טבע ההתאחדות וההתחברות ולכן הם דוקא המסוגלים להמשכה זו דוקא כו'. והענין כי הנה באתרוג ארז\"ל שנק' פרי עץ הדר<sup data-n=\"387\">8</sup> ע\"ש שדר באילנו משנה לשנה שסובל ב' הפכים קיץ וחורף קור וחום, ואף גם בא\"י שאין שם קור כ\"כ מ\"מ יש שינוי גדול בין עת הקיץ לעת החורף וימות החמה לימות הגשמים, וכן גם עפ\"י אמת מצד שרשן למעלה הם ב' מדריגות חלוקות שונות זמ\"ז ניסן הוא בחי' א' המתחלת להאיר בו עד אחר אלול, ותשרי הוא בחי' אחרת שכנגדו כו', ולכן כל הפירות שגדלים בקיץ ומקבלים מאותה בחי' ומדריגה אינם יכולין לגדל בחורף כי אינן יכולים לסבול בחי' החורף שהוא כנגדם, וכן גם בגשמיות אינן יכולים לסבול הקור כו' מלבד האתרוג שדר באילנו משנה לשנה, והיינו מצד בחי' אין שבו שלכך הוא סובל ב' הפכים כי מצד בחי' אין וביטול יכולים להתחבר גם ב' הפכים כנ\"ל באריכות. וכן הלולב הוא משונה באופן גידולו מכל מיני צמיחה שבעולם שעליו הם שוכבים ביושר ומדובקים להתיומת, שהוא החוט האמצעי אלו לאלו עד שעולים בקנה א' ממש, ולא ככל האילנות שענפיה מתפרדות זה פונה לכאן וזה לכאן, ואף גם אם אינן בקצוות רחוקים, אלא לא ימצא שיהיו קרובים אלו לאלו כמו בלולב שעליו מדובקים ממש עם היותן רבים הם כולם כאחד ונק' לכך כפות תמרים מלשון כָפות כלומר שהוא כפות ועומד ומקושר ומדובק יחד והיינו מחמת בחי' האין שבו המחבר כנ\"ל, וכן ההדס גדל בדיבוק מאד עד שעליו חופים את עצו, והערבה ארז\"ל שנק'<sup data-n=\"388\">9</sup> אחוונא ע\"ש שגדלים באחוה, והיינו מפני בחי' אין שבהם המחברם,",[["384","5","<b>ויעקב שלימו דאבהן</b>: ראה זח\"א קמז, ב. קנב, א. קעב, א. זח\"ב כג, א."],["385","6","<b>ליעקב אשר פדה את אברהם כו' וכמ\"ש במ\"א</b>: ישעי' כט, כב. וראה ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' פח. דברים ח\"א ס\"ע שלב. וש\"נ."],["386","7","<b>וחי לעולם . . נפקחו עיניהם . . וכמ\"ש במ\"א</b>: ראה תו\"א בראשית ה, ג ואילך. תו\"ח בראשית ל, א ואילך."],["387","8","<b>פרי עץ הדר ע\"ש שדר באילנו משנה לשנה</b>: אמור כג, מ. סוכה לה, א."],["388","9","<b>שנק' אחוונא ע\"ש שגדלים באחוה</b>: ראה שבת כ, א וברש\"י שם. ובמ\"מ לעיל בנוסח הראשון."]]],[2101920112,"ולכן בהם ועל ידם דוקא הוא המשכת הדעת שהוא ענין המשכת הביטול בכללות נש\"י והמשכת החכמה כו', והיינו ההמשכה מכל ד' אותיות הוי' שד' מיני' אלו מכוונים בפרטיות לנגד ד' אותיות משם הוי' כמו האתרוג<sup data-n=\"389\">10</sup> יש בו טעם וריח, וההדס יש בו ריח בלא טעם, והלולב והערבה אין בהם לא טעם ולא ריח, ובכלל כולם יש בהם בחי' האין כנ\"ל ועי\"ז נמשכת ההארה מד' אותיות הוי' שהם בדרך פרט ג\"כ כדוגמת ד' מינים הנ\"ל, ובכללות הם מבחי' אין מעולם האחדות כידוע וד\"ל.\nב) <b>אלא</b> שעדיין צריכים אנו להבין למה ההמשכה דוקא ע\"י ד' מינים גשמיי' שהארת האין שבהם היינו שנתלבש בגשמיות להיות מזה התחברות ואחדות גשמיות שעי\"ז מעוררים בחי' אין שלמעלה כנ\"ל ולמה לא יהי' ההמשכה ע\"י ביטול רוחני שיכוון בכוונה עצומה עד שיבא לבחי' אין וביטול במציאות שאעפ\"כ לא יצא י\"ח המצוה אא\"כ קיים במעשה דוקא לנענע בד' מינים גשמיים שיש בהם בחי' הביטול כו'.\n<b>והנה</b> תוכן הדבר כבר נא' למעלה בפנים שהוא מפני כי התהוות הגשמיות הוא ממקום עליון יותר ממקור התהוות הרוחניות כי הרוחניות נמשך בדרך השתלשלות עו\"ע והיינו מבחי' ממכ\"ע כמו נה\"ב<sup data-n=\"390\">11</sup> שבאדם ונפשות הבהמות שהם רוחניי' נמשכים מפני שור הרוחני שבמרכבה ונפש האלקי' מפני אדם כו', והיינו מפני שהוא בערך אחד עם עילתו שהוא רוחני כמוהו ונמשך מעצמותו ומהותו של עילתו, כמו עד\"מ חיות רוחני הנק' נפש הבהמי' נלקחת מעצמות מהות חיות רוחני של פני שור הנ\"ל, לכן יוכל העילה להוות העלול ולהפריש חלק מה ממנו כניצוץ מן הנר כו', אבל להיות ממנו התהוות הגשמיות כמו שיהווה אותו בחי' פני שור שבמרכבה את גוף הבהמה גשמיות עד\"מ זהו דבר שא\"א כלל, שהרי מהות הגשם אינו מסוג ומערך מהות הרוחני' כלל לא מיני' ולא מקצתי', ולא שייך לומר כלל שיתהווה הגשמיות מהרוחניות בבחי' עילה ועלול שהוא ענין הפרשת חלק מה מעצם רוחני שיתהווה ממנו העשי' גשמיי' מאחר שמהות הרוחני מובדל בערך לגמרי ואינו מסוג הגשמיות כלל, ולא שייך לומר עילה ועלול כ\"א בדבר שהוא בערך שאזי העילה מהווה את העלול ממנו, פי' שמפריש הארה מעצמותו להיות ממנה התהוות העלול שהוא ממהות א' עמו כנ\"ל בענין התהוות חיות שבבהמות שמפני שור כו' ששניהם רוחניים משא\"כ להיות התהוות הגשמיות זהו דבר שא\"א כלל בשום פנים, וכמבואר<sup data-n=\"391\">12</sup> כ\"ז גם בספר מורה נבוכים להרמב\"ם שלא ידעו ולא הבינו שום אופן כלל להתהוות הגשמיות, כי אפי' יהי' אלף ירידות והשפעות עילה ועלול, ומעלול לעלול ממנו, כי מרוחניות לא יתהווה מזה הגשמיות מאחר שאין הרוחניות בסוג הגשמיות כלל ולא שייך ע\"ז ענין עו\"ע כנ\"ל.",[["389","10","<b>האתרוג יש בו טעם וריח</b>: ראה ויק\"ר פ\"ל, יב."],["390","11","<b>נה\"ב</b>: בכת\"י ב: נה\"א ונה\"ב."],["391","12","<b>וכמבואר גם בספר מורה נבוכים להרמב\"ם</b>: ראה ח\"ב פכ\"ב."]]],[2101920113,"<b>אמנם</b> באמת כן הוא אלא שהתהוות הגשמיות הוא מא\"ס ב\"ה עצמו שהוא הכל יכול, ונק' למעלה מהשתלשלות, פי' שאין ההתהוות ע\"י המשכות והתלבשות הארה בו כנ\"ל בענין עו\"ע, שכל התלבשות הארה א\"א להיות כ\"א מבחי' ממכ\"ע שהוא בחי' החיות המוגבל בכלים מכלים שונים שיכול להיות נתפס ומתלבש בתוכיות איזה דבר מה המגבילו ומכילו, ומזה א\"א להיות התהוות הגשמיות מאחר שאינו מסוג זה כלל, אבל א\"ס ב\"ה שכשמו כן הוא ואין לו תחלה כו', ואינו מתלבש אפי' בעליונים הרוחניי' כלל כי כולם מוגבלים ואין ערוך אליו ית', והוא ית' הוא הכל יכול, גם להיות ממנו התהוות הגשמיות והיינו רק ע\"י רצונו ית' שרוצה להיות התהוות הגשמיות ומיד כן הי', כי<sup data-n=\"392\">13</sup> הוא צוה ונבראו כו', והיינו לפי שבחי' רצון עליון זהו המשכת והטיית עצמותו ית' הבלתי מוגבל ונק' לכך סוכ\"ע שאינו מתלבש בעולמות כלל, משא\"כ מבחי' חכמה ואילך הוא בחי' התלבשות שהעליון מתלבש ונתפס ממש בתחתון ונק' לכך בשם ממכ\"ע והיינו לפי שמחכמה ואילך הוא בבחי' גבול כי גם החכמה שהיא ראשית ההשתלשלות הוא מציאות ומהות נבדל ממהות עצמותו ית' הבלתי מוגבל שאינו בערך חכ' כלל כידוע ומכ\"ש שאינו בערך חסד כו' כמ\"ש בת\"ז<sup data-n=\"393\">14</sup> ולאו מכל אינון מדות איהו כלל, ולהיותה בבחי' גבול יכולה היא שתתלבש ותהי' נתפסת בשלמטה הימנה והשפעה כזו נק' עילה ועלול שחלק<sup data-n=\"394\">15</sup> מהעצם העילה מתלבש בהעלול כו', אמנם מזה א\"א להיות כ\"א התהוות דבר שבערך ומהות א' עם מקורו, והיינו רוחניות מרוחניות ונק' השתלשלות יש מיש אבל לא התהוות הגשמיות שאינו מערך א' וכחו מוגבל ואינו יכול להוות כ\"א דבר שבערכו ע\"י התלבשות כו', משא\"כ ע\"י הרצון העליון שהרצון הוא ענין הטיית והמשכת עצמותו ית' הבלתי מוגבל ומיד שהוא רוצה בהתהוות הגשמיות אזי מיד יתהווה הגשמיות מאחר שהוא ית' אין סוף וא\"כ הוא כל יכול כו', ולא ע\"י שהרצון מתלבש ממש בהגשמיות, מאחר שהוא בבחי' א\"ס, ואפי' בעליונים אינו מתלבש, רק ע\"ד מ\"ש כי הוא צוה ונבראו, פי' ונבראו ממילא משמע, ולא ענין כח הפועל בנפעל, אלא שהרצון שיש בעצמותו בהתהוות הגשמיות הוא המקיים התהוות הגשמיות כי כל יכול הוא ואשר חפץ כן נעשה וד\"ל.\n<b>וז\"ש</b> אני<sup data-n=\"395\">16</sup> ראשון ואני אחרון, פי' אנ\"י אותיות אי\"ן<sup data-n=\"396\">*16</sup> הוא בחי' כתר וכשם שאני ראשון בחי' הכתר שמהווה את החכמה ראשית ההשתלשלות בדרך יש מאין ולא בבחי' השתלשלות עו\"ע כידוע, כך אני אחרון שמתלבש בבחי' מל' כדי להוות מציאות הגשמיות שהוא סוף כל דרגין שבהשתלשלות ונק' כתר מל', כי התהוות הגשמיות א\"א להיות כ\"א מבחי' כתר שהוא רצונו ית' הבלתי מוגבל והוא הכל יכול כנ\"ל משא\"כ כל המדריגות שבנתיים מחכמה ואילך עד העשי' גשמיות כולם",[["392","13","<b>כי הוא צוה ונבראו</b>: תהלים קמח, ה."],["393","14","<b>בת\"ז ולא מכל</b>: בהקדמה ד\"ה פתח אליהו."],["394","15","<b>שחלק מהעצם</b>: בכת\"י ב: שחלק מה מעצם."],["395","16","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."],["396","*16","<b>אנ\"י אותיות אי\"ן</b>: ראה פרדס ש\"ג פ\"א. תו\"ח שמות (הוצאת תשס\"ג) ח\"א נ, ד. וש\"'נ."]]],[2101920114,"נמשכים בדרך השתלשלות עו\"ע מחכמה בלבד, וכמ\"ש אין<sup data-n=\"397\">17</sup> כל חדש תחת השמש פי' שמש הוא בחי' חכמה ותחת השמש אין כל חדש רק השתלשלות יש מיש, רוחני מרוחני עו\"ע כנ\"ל, רק החכמה בעצמה הנק' ראשית הוא שמאין תמצא כי תחת השמש הוא דאין כל חדש אבל השמש עצמה הוא בבחי' חידוש יש מאין, וכמו\"כ נעוץ תחלתן בסופן כשצ\"ל התהוות סוף כל דרגין הוא בחי' העשי' גשמיות שם דוקא נעוץ תחלתן בחי' רצון העליון כנ\"ל וד\"ל.\n<b>ובזה</b> יובן ג\"כ מ\"ש כולם<sup data-n=\"398\">18</sup> בחכמה עשית דמשמע לכאורה שהעשי' היא ג\"כ ע\"י החכמה, אבל באמת אינו כן וכך הוא דקדוק הלשון בחכמה עשית מבואר שאין החכמה היא העושה אלא שעם החכמה עשית אתה, והיינו שהרצון עליון הוא העושה אלא שהעשי' זאת בחכמה כי הרי כל דבר ואפי' העשי' גשמיות יש לו חומר וצורה פי' גשם הדבר הוא החומר ומדת אורכו ורחבו וכיוצא זהו צורה שלו. והנה אף שהתהוות הגשם שהוא החומר הוא מצד הרצון כנ\"ל אבל שיהי' צורתו כך וכך דוקא כפי שהוא עתה, שהרי יכול להיות גם באופן אחר כו', זהו מצד החכמה המשכלת להיות כך וכך צורת החומר אבל לא שהחכמה מהוה את החומר כלל אלא שהחכמה מתלבשת ברצה\"ע ואז הרצון מהוה את החומר בצורה זו כמו שגזרה החכמה והיינו לפי שרוצה כך כמו שהשכילה החכמה וזהו<sup data-n=\"399\">19</sup> ענין התלבשות החכמה בתוך הרצון וד\"ל.\n<b>ומזה</b> מובן ג\"כ הטעם לריבוי התחלקות הנמצאים בגשם וגופות דדצח\"מ כנ\"ל, אף שהוא ית' ורצונו אחדות פשוט כו', שהענין הוא מצד החכמה כנ\"ל שממנה נמשך הצורה ומצד הצורה הוא השינוים כו'. וזהו ענין ארץ קדמה ששרש התהוות הגשמיות הוא מבחי' עליונה יותר מבחי' שממנה התהוות הרוחניות, וכמובן מכל הנ\"ל דשרש התהוות הרוחניות הוא מחכמה שהוא הנק' ראשית לנאצלים וממנה מסתעפים כל הכחות רוחניי' שלמטה הימנה בהשתלשלות עו\"ע והרי החכמה עצמה הוא בחי' כח מוגבל נחשב לגבי א\"ס ב\"ה שאינו מערך חכמה כלל כנ\"ל, משא\"כ הגשמיות נלקח מבחי' רצה\"ע שהרצון הוא הטיית עצמותו והוא בבחי' א\"ס, ומ\"מ בחי' הרצון הוא חיצוני' ולכן מתהווה מזה הגשמיות שאין בהם לא טעם כו', והחכמה הוא בחי' פנימיות ולכן מתהווה ממנה הרוחניות שהוא בחי' הפנימיות שבכל דבר כמו טעם הפרי וצמיחת התפוח כו', אבל מ\"מ הוא חיצוניות דבחי' עליונה יותר כי הוא בחי' כתר שחיצוניותו גבוה יותר מן החכמה אף שהוא פנימיות באצי' כו', כידוע<sup data-n=\"400\">20</sup> בענין הע\"ס שפעמים הכתר נמנה בכלל י\"ס ופעמים אינו נמנה,",[["397","17","<b>אין כל חדש תחת השמש</b>: קהלת א, ט."],["398","18","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["399","19","<b>וזהו ענין התלבשות החכמה בתוך הרצון</b>: להלן אחרי המאמר נדפס ביאור ארוך השייך לכאן, ומתחיל: ”שייך לביאור שעל תורה הנ\"ל\"."],["400","20","<b>כידוע בענין הע\"ס שפעמים הכתר נמנה בכלל י\"ס ופעמים אינו נמנה</b>: ראה ע\"ח שער מוחין דצלם (שכ\"ג) פ\"ה ופ\"ח. שער דרושי אבי\"ע (שמ\"ב). ס' שער ההקדמות דרוש בענין הכתר (רנב, א). וראה לקו\"ת שלח מט, ג. ס' מאמרי אדה\"ז עה\"ת ח\"ב ע' תרטו, ובמ\"מ שם. ובארוכה ביאוה\"ז לאדהצ\"צ ח\"א ע' ערה ואילך (ובהנסמן שם)."]]],[2101920115,"והיינו כי כשמונים ע\"ס בבחי' פנימיות אזי אין הכתר נמנה כי פנימי' הכתר שהוא בחי' החפץ פנימי' הרצון אינו בכלל ספירה כלל ואז בחי' חכמה היא ראשונה שבי\"ס כי היא ראשונה בבחי' י\"ס פנימי' ונמנה הדעת במקום הכתר כו', וכשמונים ע\"ס בבחי' חיצוניות אזי נמנה הכתר והיינו בחי' הרצון שהוא חיצוניות הכתר ומ\"מ הוא ראשון ואחריו החכמה כו' ומטעם הנ\"ל.\n<b>ובזה</b> מובן הטעם מה שבמצות נטילת לולב שהכוונה להמשיך בהם בחי' הביטול בחי' הדעת כו', הוא בד' מינים גשמיים שיש בהם בחי' האין ולא ע\"י ביטול רוחני כו', כי כל המשכות אור חדש הוא מכתר ובשבעה ימי הסוכות שצריך להמשיך בחי' הדעת מחדש אף גם שההמשכה הוא רק מבחי' אצי' מבחי' חכמה כו', אבל מ\"מ צ\"ל ג\"כ המשכת אור חדש מכתר כי א\"א להיות המשכה זו מן החכמה והדעת למטה אם לא ע\"י שמתחלה יומשך תוס' הארה חדשה מן המקור שהוא הכתר בחכמה עד\"מ הנהר כשרוצים להמשיך מימיו אנה ואנה בריחוק מקום יותר כשיעור התמשכותם תמיד אזי מתחלה צריך לחפור בעומק שלו שהוא מקורו להרחיבו יותר את הנהר בעצמותו ואז יהי' התפשטותו ג\"כ מגעת להלאה יותר כו'. (ועוד<sup data-n=\"401\">21</sup> כי הרי הדעת הוא חיצוניות הכתר א\"כ כדי שיומשך בחי' הדעת צ\"ל מתחילה ההמשכה מבחי' כתר) וההמשכה מכתר הוא דוקא ע\"י גשמיות שנלקחים מכתר כנ\"ל משא\"כ ע\"י רוחניות א\"א להמשיך משם כלל כי מקור כל השתלשלות והתהוות הרוחניות הוא מחכמה בלבד כנ\"ל. וכן מצות סוכה הוא דוקא ע\"י סכך גשמי כו', כי בחי' סוכות הוא פנימי' בינה והוא בחי' א' עם יוכ\"פ שהוא בחי' תשו\"ע שהוא בחי' בינה כנ\"ל, ולכן נעשה בבחי' סכך ומקיף מלמעלה כי אינו יכול להתלבש בבחי' פנימיות ולכך חמתה<sup data-n=\"402\">22</sup> מרובה מצילתה פסולה כי בסוכות הוא ההמשכה מבחי' שלמעלה מן החמ\"ה שהחמה היא ההארה המאירה בגילוי ובבחי' פנימיות אבל בסוכות הוא ההמשכה מבחי' מקיפים והיינו ענין הצל שהוא בחי' מקיף והוא בחי' חשך שלמעלה מהאור כמ\"ש ישת<sup data-n=\"403\">23</sup> חושך סתרו וכתי' חשכת מים כו', וכן במשנה כמראה<sup data-n=\"404\">24</sup> חמה העמוקה מהצל הרי שצל הוא למעלה מהחכמה, והוא מבחי' פנימיות בינה הנ\"ל, הנק' רקיע השמיני כו' כמ\"ש במ\"א באריכות. וא\"א להיות המשכה זו כ\"א ע\"י מעשה גשמיות בסכך גשמי דוקא, וכן ביוכ\"פ בהעלאת עשן מסממני קטרת הגשמיים כו', כי הגשמיות נעלית יותר ובו ועל ידו הוא שנמשך הארת הכתר כו'.\nג) <b>ועתה</b> יובן ג\"כ שרש ענין התורה<sup data-n=\"405\">25</sup> שנק' שלום בפמשמ\"ע ובפמשמ\"ט כו', כי הנה באמת כל דבר כלול ומורכב מב' מיני חיות שנמשכים מסובב וממלא, וכמו עד\"מ האדם גופו שהוא גשמי חיותו מבחי' סוכ\"ע כנ\"ל, ונפשו החיונית",[["401","21","<b>(ועוד כי הרי הדעת . . מבחי' כתר)</b>: שורות אלו ניתוספו מכת\"י ב. ובכת\"י א ליתא."],["402","22","<b>חמתה מרובה מצילתה פסולה</b>: סוכה ב, א."],["403","23","<b>ישת חושך . . חשכת מים</b>: תהלים יח, יב."],["404","24","<b>כמראה חמה העמוקה מהצל</b>: ראה ב\"ב פד, א. תו\"כ תזריע יג, ג. ובכ\"מ."],["405","25","<b>התורה שנק' שלום בפמשמ\"ע ובפמשמ\"ט</b>: סנהדרין צט, ב."]]],[2101920116,"ומכ\"ש נפשו האלקית הן מבחי' ממכ\"ע, שהרי הן המה רוחניים בעצם מציאותן, רק שאחר שנתהווה הגוף הם יורדים ומתלבשים בו ומתאחדים עמו כו', ולכן כדי שיהיו מתחברים ומתאחדים זע\"ז צ\"ל ע\"י איזה דבר המחברם, והוא הארה<sup data-n=\"406\">26</sup> שיש בה בחי' שלמעלה משניהם המחברם כו'. והענין כי על התורה אתמר בזוהר<sup data-n=\"407\">27</sup> אורייתא מחכמה נפקת, אך אינה בחי' החכמה שהוא חיות העולמות דהיינו בחי' ממכ\"ע המתלבשים בפנימיות המקבלים כמ\"ש כולם<sup data-n=\"408\">28</sup> בחכמה עשית כו', כי חכמה זו היא רק נובלות<sup data-n=\"409\">29</sup> מחכמה שלמעלה דהיינו שההארה בלבד מאותה חכמה שלמעלה כטיפה מן הים וכמשל יניקת השערה מן המוח כו', הוא שנשפלה להיות מאיר בבחי' פנימי' במקבלים ומתחלקת לל\"ב נתיבות, ועז\"נ כולם בחכמה עשית, אבל עצמיות החכמה שלמעלה היא נפלאת ומובדלת בערך מחכמה זו כנ\"ל, ושם הוא התורה שהיא חכמתו ית' חכים<sup data-n=\"410\">30</sup> ולא בחכמה ידיעא, שאינה מערך בחי' החכמה שבהשתלשלות שהיא בחי' נובלות בלבד ממנה כו'. וכן המצות עצמן שבתורה עם היות שנק' רצון העליון רצון בלבד, היינו בחי' התגלותם שבגילוי למקבלים הוא כאלו אינו רק רצון בלבד בלא טעם כו', אבל באמת יש בהם תענוג עצום ורב בכל מצוה בפרט, ונקראים חפץ ה', וכמ\"ש ה'<sup data-n=\"411\">31</sup> חפץ למען צדקו יגדיל תורה כו', כי בחי' החפץ והתענוג שבמצות מאיר ומתגלה באותה פנימית חכמה שבתורה כידוע, ולכן התורה היא המשים שלום בב' הפמלי' כו', פי' שהיא הגורמת להיות קיום סדרי ההשתלשלות שאינו אלא ע\"י שיתוף התלבשות החכמה ורצון הנק' סובב וממלא בעלמין המתהווה מהם כו', והתחברות זו היא ע\"י התורה, פי' שבחי' התענוג שבתורה הוא הגורם התלבשותן שיהי' לו ית' רצון בהתהוות העולמות, ואזי רצון זה יהווה ויעשה העשי' גשמיות כנ\"ל. וסיבת רצון זה הוא מחמת התענוג שיש לו מקיום המצות וא\"א להיות נשלם כ\"א ע\"י התהוות עולם העשי' כנ\"ל, לכן רוצה עי\"ז בהתהוות העשי', ורצון זה הוא המקיים ומחיי' את העשי', וכעד\"ז ברוחניות להיות המשכת והתלבשות החכמה להשפיע חיות רוחני' בעולמות, סיבת המשכת והשפעה זו היא ג\"כ מצד התענוג שיקבל אח\"כ מקיום התורה ומצותיה כו'. ואף גם שיש כמה דברים בעולם שלא נעשו בהם מצות כלל, ומעט מזעיר הם הנעשי' בהם מצות צמר לציצית וקלף לתפילין כו', מ\"מ כולם לא<sup data-n=\"412\">32</sup> נבראו אלא לצוות לזה דהיינו שהם בחי' טפל לדבר המצוה עצמה, שעכ\"ז הם ג\"כ פעולה וגרמא לעשיית המצוה כמו לחם לאכול ובגד ללבוש שעי\"ז יהי' כח באדם לקיים המצות כו', וכל<sup data-n=\"413\">33</sup> מה שברא בעולמו לא ברא דבר לבטלה ח\"ו אלא מה שנצרך לקיום העולם כדי שיושלמו עשיות המצות כו', שבהם הוא שיש לו תענוג ונק' חפץ, והוא הגורם המשכות והתלבשות הרצון והחכמה בכל סדרי ההשתלשלות המתהווה מהם, וזהו ענין שלום בפשמ\"ט וכמו\"כ",[["406","26","<b>הארה</b>: בכת\"י ב: התורה."],["407","27","<b>בזוהר אורייתא מחכמה נפקת</b>: זח\"ב סב, א. פה, א. קכא, א. ועוד."],["408","28","<b>כולם בחכמה עשית</b>: תהלים קד, כא."],["409","29","<b>נובלות מחכמה שלמעלה</b>: ראה ב\"ר פי\"ז, ה."],["410","30","<b>חכים ולא בחכמה ידיעא</b>: תקו\"ז בהקדמה ד\"ה פתח אליהו (יז, א)."],["411","31","<b>ה' חפץ למען צדקו</b>: ישעי' מב, כא."],["412","32","<b>לא נבראו אלא לצוות לזה</b>: ברכות ו, ב."],["413","33","<b>וכל מה שברא בעולמו לא ברא דבר לבטלה ח\"ו</b>: שבת עז, ב."]]],[2101920117,"שלום בפשמ\"ע התחברות סובב וממלא, שהם בחי' כתר וחכמה כנ\"ל, דהיינו שיהי' הארת הכתר הנק' רצה\"ע נמשכת להאיר בי\"ס דאצי' הוא ג\"כ ע\"י בחי' חפץ ופנימי' חכמה שבתורה כנ\"ל.\nד) <b>והנה</b> יש ב' בחי' בתורה, הא' הוא מ\"ת שבשבועות שהוא כנגד בחי' צדיקים שבישראל ולכן ניתנה בקולי קולות כי הרי הצדיקים כל מעשיהם באתגליי' לקיים ככתוב בס' התורה, ואינן מתייראין משום מקטרג ומסטין אחר ששלמים הם בעבודתם ולכן ניתנו לוחות אלו בפרהסיא בשבועות, והב' בחי' לוחות שביוכ\"פ שניתנו בצינעא לפי שהם כנגד בחי' בע\"ת שבישראל שמכסה פשעיו הוא ומתיירא לגלותם מפני המקטרג כו', וא\"כ גם אחרי ששב לה' בתשובה שלימה עד שכל זדון מזדונותיו<sup data-n=\"414\">34</sup> נעשו לו כזכיות כלומר שנמשכים כל האורות שהצדיק ממשיך ע\"י זכיותיו זה ממשיכם בשעה א' ע\"י התשובה מעומקא דליבא שאז באותה שעה נהפכים הזדונות והיו לזכיות ממש, וזהו ענין מ\"ת שביוכ\"פ לבע\"ת לפי שאז הוא בחי' תשו\"ע מעומקא דליבא ממעמקים<sup data-n=\"415\">35</sup> קראתיך הוי' ואזי בנעילה<sup data-n=\"416\">36</sup> הוא עליי' המל' עד דיקנא דא\"א ונק' עת רצון שמשם הוא מקור הסליחה והמחילה שיתמלאו כל הפגמים והחסרונות, וגם שיהיו הזדונות כזכיות ונק' מ\"ת כו', כלומר שניתנו להם כל אורות עליונים הנ\"ל שהצדיק ממשיך כל ימיו ע\"י מעשה המצות בשעה א' של התשובה ששב לה' מעומקא דליבא כו'. ומ\"מ צ\"ל הכל בסתר כמ\"ש אשרי<sup data-n=\"417\">37</sup> נשוי פשע כסוי חטאה כו', וכמ\"ש<sup data-n=\"418\">38</sup> במ\"א ע\"פ בכסא ליום חגינו דסיהרא איתכסית לאתר דאתמר בי' במכוסה ממך בל תחקור בשביל שיהיו יכולים לעשות תשובה כו' ע\"ש באריכות המענה.\n<b>והנה</b> מכ\"ז מובן שבחי' מ\"ת דיוכ\"פ הוא יותר נעלה ממ\"ת דשבועות מאחר שיכול להפך מזדונות שהם ההיפך מן הזכיות ממש להיות הן עצמן נעשים זכיות א\"כ בהכרח שהוא מבחי' שלמעלה גם מן הזכיות, כלומר שהוא מבחי' שלמעלה מהאורות דמצות כו' שעי\"ז הוא יכול למלאות כל החסרונות שנעשו בעברם על המצות כנז\"ל המשל ממילוי הנהר שנחרב ויבש שהוא ממקורו דוקא, אמנם ביוכ\"פ הארה זו היא רק מבחי' מקיף והוא בחי' פנימי' ותעלומות לב שלמעלה מהגילוי כו', ובסוכות הוא ג\"כ עדיין בבחי' מקיף בלבד שזהו ענין הסכך שמלמעלה כנ\"ל, רק שההפרש בין סוכות ליוכ\"פ הוא רק מה שבסוכות נמשכים מקיפים אלו מלמעלה למטה וביוכ\"פ הוא ממטה למעלה, כלומר שהמקבל עולה למעלה ושם מקבל הארת המקיף כו', אלא שבשמ\"ע הוא שנעשים מקיפים אלו דסוכות פנימיי' ממש שנמשכים",[["414","34","<b>מזדונותיו נעשו לו כזכיות</b>: יומא פו, ב."],["415","35","<b>ממעמקים קראתיך הוי'</b>: תהלים קל, א."],["416","36","<b>בנעילה הוא עליי' המל' עד דיקנא דא\"א</b>: ראה פע\"ח שער יוהכ\"פ ספ\"א ופ\"ה. לקו\"ת מסעי צג, ד. אוה\"ת פ' ראה ע' תשכב. ובכ\"מ."],["417","37","<b>אשרי נשוי פשע</b>: תהלים לב, א."],["418","38","<b>וכמ\"ש במ\"א ע\"פ בכסא ליום חגינו . . ע\"ש באריכות המענה</b>: ראה ביאוה\"ז לאדהאמ\"צ קכג, ג ואילך. אוה\"ת שופטים ע' תתנט. ביאוה\"ז להצ\"צ ח\"ב ע' תתרלה. וראה סה\"מ תרכ\"ט ס\"ע שנ ואילך (ובמ\"מ שם)."]]],[2101920118,"ומתפשטים בבחי' פנימיות ממש בכללות נש\"י, והיינו ע\"י שבעת ימי הסוכות שהן שבעת ימי המשתה שאז נמשך בהם בחי' הדעת ע\"י הלולב ומיניו ונעשים ראוים להולדה ולהמשכת הטפה כנ\"ל באריכות. ולכן עושים אז דוקא שמחת תורה לשמוח בהמשכת התורה שניתנה ביוכ\"פ אשר בו ביום נמשכת מההעלם לגילוי ממקיף לפנימי כו'. ועיקר השמחה הוא ענין ההקפות שמקיפים עם הס\"ת את המקום שקוראים בו בספר כל ימי השנה, להורות ענין הנ\"ל דארץ קדמה כו', ואיך שכללות נש\"י המקבלים יש בהם מעלה יתירה כו' כמ\"ש נקבה<sup data-n=\"419\">39</sup> תסובב כו', שכך מקיפים עם הס\"ת הגשמיות הנכתבת ע\"ג קלף ודיו גשמי שהיא בחי' עשי' שהרי כל הדקדוק בדיני הס\"ת הוא שלא יהי' בהם חסר ויתיר באותיות ונגיעה באותיות שזהו הוראה שהוא מפני שנתלבש כל קדושתה בעשי' גשמיות דוקא, שאם הי' זה בשביל הקריאה בפה בלבד לא הי' הנגיעה פסולה שהרי גם שיהי' נגיעה באיזה אות מ\"מ יוכל לקרותו בדיבור פה ולהבינו כו', אלא משום שמקרא<sup data-n=\"420\">40</sup> בעשי' פי' שכל קדושתה נתלבש בעשי' גשמיות דוקא ולכן צ\"ל שלימה באותיותיה הגשמיים כראוי ע\"פ הרוחני' הנעלם וגנוז בעשי' זו כו', ומה שמקיפים בה על המקום שקוראים בו בתורה בדיבור פה שהוא בחי' רוחני' לגבי העשי' היינו מטעם הנ\"ל דארץ קדמה שהגשמיות נעלה יותר שמה שנתלבש בחי' המקרא בעשי' הוא מצד שרשו הנעלה יותר כו', ולכן הוא מקיף על הרוחניות והוא בחי' סובב שממעל לממלא וד\"ל.\n<b>ואז</b> נאמר עצרת תהי' לכם פי' עצרת מלשון עוצר, שטפה זו הנמשכת בשמ\"ע דהיינו בחי' פנימי' הנעשה מן המקיף תהי' נקלטת ומתעכבת ברחם הנוק' היינו בכנס\"י ולא תהא פולטת ח\"ו, ועי\"ז תתעבר ותוליד בזש\"פ הנשמות, וזהו שאז נאמר ובנ\"י<sup data-n=\"421\">41</sup> הלכו ביבשה כלומר שנולדו מן ההעלם דעיבור כו'. והענין כי מצינו כמה חלוקות בנש\"י פעמים נק' אחים וריעים למקום כמ\"ש למען<sup data-n=\"422\">42</sup> אחיי וריעיי אדברה כו' ופעמים נק' בנים כמ\"ש בני<sup data-n=\"423\">43</sup> בכורי ישראל ופעמים נק' עבדים עבדי<sup data-n=\"424\">44</sup> ישראל כו'.\n<b>והנה</b> מ\"ש אם<sup data-n=\"425\">45</sup> כבנים ואם כעבדים משמע ששניהם למטה מבחי' אחים ולכן יש להסתפק אם כבנים כו'. והענין כי בחי' עבד היינו כשהוא מציאות נפרד לגמרי בפ\"ע רק שאעפי\"כ עובד לרבו ומבטל עצמו אליו בחיצוניות, משא\"כ הבן הוא חלק מהאב כמ\"ש ברא<sup data-n=\"426\">46</sup> כרעא דאבוה ומ\"מ הוא חלק שהופרש ממנו שהרי",[["419","39","<b>נקבה תסובב כו'</b>: ירמי' לא, כא."],["420","40","<b>שמקרא בעשי'</b>: פע\"ח שער הנהגת הלימוד (שי\"ז). טעהמ\"צ ושער המצות פ' ואתחנן. תניא פ\"מ (בהגה\"ה אחרונה). לקו\"ת ויקרא ה, א ואילך. ס' מאמרי אדהאמ\"צ נ\"ך ע' קל, ובמ\"מ שם."],["421","41","<b>ובנ\"י הלכו ביבשה</b>: בשלח יד, כט. טו, יט."],["422","42","<b>למען אחיי וריעיי</b>: תהלים קכב, ח."],["423","43","<b>בני בכורי ישראל</b>: שמות ד, כב."],["424","44","<b>עבדי ישראל</b>: ע\"פ ישעי' מא, ח."],["425","45","<b>אם כבנים ואם כעבדים</b>: פיוט היום הרת עולם במוסף דר\"ה."],["426","46","<b>ברא כרעא דאבוה</b>: ע\"פ פירש\"י ד\"ה כבעל — כתובות צב, א. תוד\"ה מקמי — יבמות ג, א."]]],[2101920119,"נאמר בן<sup data-n=\"427\">47</sup> מכבד אב ועבד אדוניו, א\"כ שייך הכיבוד מן הבן לאב מכלל שאינו עצם א' עמו ממש, והוא דבר נמוך ממנו לכן יכבד האב כו', אבל בחי' אחים וריעים היינו שניים שהם בערך והשואה אחת זע\"ז (וכמ\"ש במ\"א בענין אורך ורוחב אין<sup data-n=\"428\">48</sup> קורין אבות אלא לשלושה שהם חג\"ת כולם נק' אבות להיותם בערך א' והוא עד\"מ הרוחב שכולו במקום ומצב א', משא\"כ י\"ב שבטים שהם מדריגה נמוכה מן האבות נק' אורך שנמשך מלמעלה למטה וזהו ענין שנז\"ל אורך קומה של יוצר בראשית ורוחב בין זרוע לזרוע כו' ע\"ש). כמו\"כ יובן למעלה שיש ג' בחי' בנשמות מתחלה כשהם בעצמות האצי' טרם התמשכותם בבטן הנוק' דז\"א הן נקראים אחים וריעים למקום פי' שהם בחי' אחים לז\"א דאצי' הנק' מקום כי הם בערך א' עמו כי אז הם בחי' אלקות ממש שהוא ית' מיוחד בהן כמו שמיוחד בכלים דאצי' עצמן הנק' גרמוהי שנאמר עליהם איהו<sup data-n=\"429\">49</sup> וגרמוהי חד רק שהם קטנים מהכלים ומ\"מ בערך א' יחשבו וכמ\"ש במ\"א ששרש<sup data-n=\"430\">50</sup> נש\"י הם ס\"ר אותיות המחשבה שמלבישים את המדות ונראים כעצם א' עם המדות ממש, וזהו פי' אחי\"ם כו', ואח\"כ כשנמשכים בנוק' דז\"א ונמשלים לטפה היורדת מן המוח שמתגשמת מרוחניות לגשמיות מפני שיורדת דרך<sup data-n=\"431\">51</sup> ח\"י חוליות השדרה כו' כמ\"ש במ\"א, עד שאז נק' בנים למקום כלומר שהופרשו מבחי' עצמיות אלקות להיות דבר לעצמם ולכן בן יכבד אב הוא בחי' ז\"א דאצי' הנק' אב לנשמות שברחם הנוק' כידוע, ומ\"מ הוא חלק מהאדם עכ\"פ עדיין ואינו נפרד לגמרי, אבל אח\"כ בירידתם בבי\"ע נעשים בחי' יש לעצמם ממש ובבחי' פירוד מאלקות עד שמשפט הבחירה לו גם להיות מורד כו', ומה שאעפי\"כ אינו מורד ומבטל ישותו לכך נק' עבד כו', וז\"ש על היום הרת עולם בחי' עיבור אם כבנים כלומר אם כמו שאנחנו בעיבור במעי הנוק' או כעבדים כשירדנו כבר בבי\"ע להיות יש גמור כו'. והנה<sup data-n=\"432\">51</sup> בשביעי של פסח הוא הלידה כלומר זמן הירידה בבי\"ע אבל בשמ\"ע הוא זמן המשכת הטפה בנוק' להיות נק' בנים וע\"ז נאמר עצרת תהי' לכם שתהי' הטפה נקלטת ברחם הנוק' להיות מתעכבת עד\"מ ושיתהווה בחי' הנשמה הנק' בן ואח\"כ ע\"י ז' חדשים שעד זש\"פ ובכל יום אוכלת<sup data-n=\"433\">53</sup> ממה שאמו אוכלת כו' ומתגדלת עד שנעשים בחי' יש ממש ובוקע ויוצא בזש\"פ ונק'<sup data-n=\"434\">54</sup> לידה וד\"ל.",[["427","47","<b>בן מכבד אב ועבד אדוניו</b>: מלאכי א, ו."],["428","48","<b>אין קורין אבות אלא לשלושה</b>: ברכות טז, ב."],["429","49","<b>איהו וגרמוהי חד</b>: תקו\"ז בהקדמה (ג, ב)."],["430","50","<b>ששרש </b> [בכת\"י ב: שס\"ר]<b> נש\"י הם ס\"ר אותיות המחשבה</b>: לקו\"ת פ' צו טז, ג. סה\"מ תקע\"א ע' קנד ואילך."],["431","51","<b>דרך ח\"י חוליות השדרה כו' כמ\"ש במ\"א</b>: ראה אוה\"ת בלק ע' א'טו. א'כד. ובהוספות שם ע' 67. ועוד."],["432","51","<b>והנה בשביעי של פסח הוא הלידה</b>: ראה פע\"ח שער הלולב (שכ\"ט) ספ\"ח. וראה להלן ריש ד\"ה שחורה אני (ש\"פ וירא). וש\"נ."],["433","53","<b>אוכלת ממה שאמו אוכלת</b>: ראה נדה לא, א."],["434","54","<b>ונק' לידה וד\"ל</b>: בסוף המאמר נרשם בשולי העמוד (מכ\"ק אדמו\"ר הצ\"צ): שארה כסותה ועונתה, ג' בחי' הנ\"ל ממכ\"ע וסוכ\"ע והשלום."]]],[2101920120,"<h3>קיצור על הנ\"ל</h3>\n<b>[קיצור<sup data-n=\"435\">1</sup>]</b>\n(א) <b>הד'</b> מינים יש בהם בחי' אין, על כן על ידם הוא המשכת הדעת. (ב) ומה שאין ההמשכה ע\"י ביטול רוחני לבד כ\"א ע\"י ד' מינים גשמיים שיש בהם בחי' אין וביטול הוא מפני שהגשמיות שרשו גבוה יותר מבחי' כתר סוכ\"ע, והיינו חיצוניות הכתר שהוא חיצוניות מבחי' עליונה ביותר, לכן גבוה מהחכ' אף שהוא בחי' פנימיות. (ג) וענין התורה שלום בפמשמ\"ע. (ד) וענין שמע\"צ וההקפות בס\"ת וקליטת הנשמות.",[["435","1","<b>קיצור</b>: בהכתבי-יד נרשם אחר המאמר קיצור זה ושאר ההגהות שנדפסו להלן. והם מכ\"ק אדמו\"ר הצ\"צ."]]],[2101920121,"<h3>שייך לתורה ע\"פ ביום השמע\"צ<sup data-n=\"436\">1</sup></h3>\n<b>הגם</b> שאנו רואים שגם חומר העשב והתפוח נולד מכח הצומח שבארץ, זה אינו קושיא כלל כי באמת בארץ יש הכח הזה מעצמות א\"ס ב\"ה שתוכל להצמיח ולהוליד מאין ליש, ע\"י צירופי אותיות מאמר תדשא<sup data-n=\"437\">2</sup> הארץ כו' תוצא הארץ, שניתן כח בארץ שתוכל להצמיח מאין ליש, וכח זה הוא ממש מעצמות א\"ס ב\"ה שלמעלה מבחי' ממכ\"ע, ולכן הוא מתלבש בארץ דוקא, כי נעוץ תחילתן בסופן דוקא וכנ\"ל בענין רוחניות וגשמיות, שבסוף וסיום הרוחניות כשצ\"ל התהוות הגשמיות שהוא הולדה חדשה, וכך הוא ע\"פ הקבלה מן העולם ועד העולם, שבכל עולם מבחי' חכמה שבו ואילך הוא בחי' השתלשלות עילה ועלול, לפי שהכל בערך וסוג א' בינה מהחכמה, והמדות מבינה כו', עד\"מ רוחניות מרוחניות והיינו עד בחי' מל' שבו סיומא דכל דרגין, וכשצ\"ל התהוות עולם שלמטה הימנו שהוא מסוג אחר לגמרי כגשמיות לגבי רוחניות עד\"מ, אז צ\"ל ההמשכה עליונה מלמעלה מבחי' החכמה שבאותו עולם, כי מחכמה א\"א להיות התהוות זו כי הוא בבחי' גבול שהאור מלובש בכלי ע\"ד הנ\"ל, אלא ממקום שנתהווה החכמה, והיינו בחי' כתר שהוא ענין בחי' סוכ\"ע והארת הכתר מתלבש במל' דוקא ועי\"ז המל' מהוה עולם שלמטה ממנו, וז\"ש אני<sup data-n=\"438\">3</sup> ראשון ואני אחרון, וכך ממש הוא בארץ הגשמי' שהוא מבחי' י\"ס דעשי' שנתגשמו שמים הם מבחי' ז\"א דעשי' וארץ מבחי' מל' דעשי', ולכן בה דוקא נמצא ומתלבש הכח מבחי' כתר",[["436","1","<b>שייך לתורה ע\"פ ביום השמע\"צ</b>: הגהת כ\"ק אדמו\"ר הצ\"צ, ושייך על המאמר לעיל פיסקא ד\"ה ומה שארז\"ל אין לך עשב מלמטה."],["437","2","<b>תדשא הארץ כו' תוצא הארץ</b>: בראשית א, יא. כד."],["438","3","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."]]],[2101920122,"שתוכל להוליד הולדה חדשה ולהוציא צמחה, אלא שהקושיא ממ\"ש חז\"ל אין לך עשב מלמטה כו' הוא על לשון מזל מלמעלה שארז\"ל דמשמע מלמעלה ממש ולא מהארץ, ועוד לשון מזל שהוא משמע מזל מיוחד פרטי לאותו העשב והיינו מבחי' ממכ\"ע, וע\"ז התירוץ שפיר שהוא רק לענין הגידול של העשב ולא להתהוות חומרו וממשו, ולענין נתינת טעם בו כמו להיות מר או מתוק או כלול משניהם שזה אינו מהכח הצומח שאינו מהוה רק עצם חומר הפשוט של העשב או התפוח שהוא בחי' הגשמיות, אבל איך ומה שיהי' אופן גידולו ואופן טעמו שזהו בחי' רוחניות המתלבש באותו גשם פרטי ונק' צורה של החומר זהו מן המזל שמלמעלה כי הצורה נמשכת באמת מבחי' ממכ\"ע כמשי\"ת.\n<b>אך</b> יש להקשות ע\"ז ממה שיש ארץ מגדלת פירות אלו וארץ אינה מגדלת אלו אלא אחרים כו', ואם סיבת שינויי הפירות הוא רק מצד המזל שמלמעלה כי הכח המצמיח שבארץ אינו מצמיח רק גשם החומר ולא הטעם והריח כו', למה ישתנו הארצות הרי בכולם יש כח הצומח, מאחר שעכ\"פ מצמיח מיני פירות אחרים ולמה לא יצמיח גם ממיני פירות אחרים כו'. אך הטעם כי השינויים שמצד המזל שמלמעלה המגדלו ונותן בו טעם הוא תלוי ג\"כ בשינויי הארצות שארץ זו מקבלת ממזלות אלו והשני' ממזלות אחרים וכמ\"ש<sup data-n=\"439\">4</sup> בענין ממגד תבואות שמש וממגד גרש ירחים יש פירות שגדלים מן החמה ונמצאים בארצות החמות ויש מן הלבנה בארצות הקרות שהלילה גדולה כו'.\n<b>אמנם</b> באמת יש לומר בענין אחר שענין מזל מלמעלה המכה ואומר לו גדל הנק'<sup data-n=\"440\">5</sup> גם כח הצומח והוא פועל רק הצמיחה בלבד של הגשם וכדקדוק לשון כח הצומח, פי' שמצמיח בלבד, וכן אומר לו גדל, אבל התהוות תחלת גשם החומר הוא מלמעלה ממש מא\"ס ב\"ה הסוכ\"ע. והענין כי הנה נת'<sup data-n=\"441\">6</sup> בע\"ח בענין ד' יסודות ארמ\"ע שהם יסודות פשוטים ואינם כלולים זמ\"ז אבל דצח\"מ שלנגד ארמ\"ע כלולים זמ\"ז, כי הדומם עיקרו מיסוד העפר ומ\"מ כלול גם ממים ושמן כו', והנה העפר או האפר שבכל דבר זהו עצם פשוט שלו מיסוד העפר שבו ולכן נשאר גם אחר שריפת העץ כו' ואינו כלול משום דבר והוא עיקר הגשמיות שאנו אומרים שנלקח מבחי' סובב, משא\"כ בחי' הצמיחה שבדבר הצומח הוא בחי' תוספת על הגשם ונק' צורה של הגשם והוא בחי' רוחני' ממש אלא שמתלבש בגשמיות לכן כלה ע\"י השריפה שהרי כמו האפר הנשאר מועט מכמות העץ מפני שלא נשאר רק יסוד העפר שבו ואשכחן אפר שנק' עפר כו', אבל שאר היסודות שבו מצומח ואילך מסתלקים להיותן רוחניים והן המה נמשכים באמת רק מבחי' ממכ\"ע שהרי המה בחי' רוחניות ולא גשמיות כמו הצמיחה של הפרי או הטעם",[["439","4","<b>וכמ\"ש בענין ממגד תבואות שמש</b>: ברכה לג, יד. וראה סידור עם דא\"ח קמב, א. ס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תרב, ובמ\"מ שם."],["440","5","<b>הנק'</b>: בכת\"י ב': הוא נק'."],["441","6","<b>נת' בע\"ח בענין ד' יסודות ארמ\"ע שהם יסודות פשוטים</b>: ראה ע\"ח שמ\"ב (שער דרושי אבי\"ע) פ\"א."]]],[2101920123,"של הפרי שהוא דבר נוסף על גשמיותו כו', כמו החיות שבגוף החי והדיבור שבאדם שהם דבר נוסף מבחי' ממלא כו', וכ\"ה ע\"פ הקבלה נפש של יסוד העפר הוא לקיום גשם חומרו משא\"כ בצומח נוסף עליו נפש א' שיש בו גם לקיום גשם חומרו והוא יסוד הפשוט שבו כנ\"ל ונוסף בו נפש הצומחת, וכן בדומם כאבנים שכלולים ג\"כ מד' יסודות ארמ\"ע נוסף נפש המרכבת כו', ולפ\"ז כמו הצומח שהו\"ע נפש הצומחת הכללי' אינה מהוות החומר גשמי של הפרי שהוא מבחי' עפר שבו רק שמצמיחתו וזהו ענין אומר לו גדל, ומדנקט אומר לו, מכלל דיש מציאות גם קודם והוא חומרו הגשמי שנמשך מן הסובב כנ\"ל משא\"כ כל אלה הצומח וחי כו' נמשכים מבחי' ממלא.\n<b>ויובן</b> זה גם ע\"פ הקבלה שלמעלה ענין ד' יסודות ארמ\"ע היינו מל' שנק' עפר וז\"א נק' מים ונק' ג\"כ צומח כו', כי המל' היא בחי' אותיות שהם כמו עפר בעצם שאינן בהם תנועה וגידול, משא\"כ המדות בחי' התפעלות וגידול כו', ומל' דוקא הוא ששורשה בכתר הסובב כ\"ע כי נעוץ סופן וכידוע שכתר נק' מדבר מקור האותיות כו', והיינו לפי שהוא עד\"מ בחי' החומר ונק' עפר משא\"כ הז\"א וחו\"ב שהם ענין צומח כו' בחי' רוחניים הם מבחי' ממלא בלבד, כי מחכמה ואילך אין כל חדש רק יש מיש וז\"ש נעוץ תחילתן כו' והמ\"י. ואמנם לפעמים נק' המל' אבן ולא עפר שהוא בחי' דומם שאינו יסוד פשוט וגם נק' אתרוג שהוא צומח וגם נק' אילה שהוא חי וגם נק' אימא תתאה ואדם תתאה שהוא מברר, והטעם כי גם היא כלולה מי\"ס חו\"ב שבמל' עד מל' שבמל' ולכן יש לה ע' שמות נגד ז' מדות הכלולים מיו\"ד וד\"ל."],[2101920124,"<h3>שייך לביאור שעל תורה הנ\"ל<sup data-n=\"442\">1</sup></h3>\n(א)<sup data-n=\"443\">2</sup> <b>וזהו</b> ענין התלבשות החכמה בתוך הרצון כו', לכאורה זהו סותר למ\"ש<sup data-n=\"444\">3</sup> בפנים שההמשכה הוא ע\"י המדות חסד דרועא ימינא כו' רק שהוא כגרזן ביד החוצב כו', דמשמע להדיא שההמשכה הוא מן המדות רק שא\"ס ב\"ה הוא העושה בהם כאדם הכותב בידו כו', וכאן משמע להיפוך שהחכמה מתלבשת ברצון ומזה בא סיבת ההתחלקות בנבראים, אבל לעולם ההמשכה היא מעצמיות הרצון. אך באמת קאי הא וקאי הא, והענין כי מובן מכל הנ\"ל כי עם היות שבדרך כלל נחלקים לב' בחי' חומר וצורה אבל באמת גם החומר עצמו יש בו צורה כמו יסוד העפר שהוא חומר פשוט מ\"מ יש בו צורה איך ומה שהוא בכמותו ומהותו ובארכו ורחבו וקומתו כו', אמנם אין בחי' צורה זו כמו בחי' הצורה שבצומח וחי כו', שהצמיחה שבצומח שהוא בחי' הרוחניות ונק' צורה שלו הוא דבר נוסף ממש על הגשם שהוא החומר וכן החיות שבחי משא\"כ הצורה של העפר אין זה דבר נוסף כלל על החומר שהרי אין כאן רק מציאות העפר כ\"א מה שהוא נמצא והי' במציאות זה שהוא עתה באורך ורוחב כו', זהו הנק' צורה שלו.\n<b>והנה</b> זהו הכלל שהגשמי שהוא עצם החומר פשוט הוא שנמשך ומתהווה מן הרצון עליון ונק' סובב כמ\"ש כל<sup data-n=\"445\">4</sup> אשר חפץ הוי' עשה כו', אמנם מה שנתהווה בצורה כמו אורך ורוחב כו' זהו מצד החכמה שגזרה להיות רוצה בכך, אבל אין שייך לומר שהחכמה מתלבשת ממש ביסוד העפר, והוא בחי' הצורה שבו, מאחר שאין הצורה דבר נוסף כלל על החומר ואין כאן אלא החומר שהוא הגשם בלבד הנמשך מרצה\"ע דוקא, רק שהענין שהחכמה מתלבשת ברצון להטותו איך ומה שירצה ועם היות שהחכמה גוזרת איך שיהי' הרצון מ\"מ אח\"כ אין כאן אלא מהות רצון בלבד רק שהוא רצון מוגבל עכ\"ז החכמה שהגבילתו להיות רוצה כך וכך, ולכן מתהווה ממנה חומר מוגבל כך וכך כפי הרצון המוגבל וזהו הנק' הנק' צורה שלו, וא\"כ מובן שצורה זו היא מצד החכמה אבל לא שנמשכת מהחכמה וה\"ז עד\"מ כאומן העושה דבר עפ\"י לוח שנחקק שם צורת אותו הדבר שהעשי' הוא מאומן וצורת העשי' אינו דבר נוסף כו', רק שצורה זו היא כמו שעושים בלוח אבל לא שהלוח עושה, וכך נא' כולם<sup data-n=\"446\">5</sup> בחכמה עשית הרצון עליון אבל [לא] שהחכמה הוא העושה כו', אמנם כ\"ז הוא בעשיי' גשמיי' דוקא שנמשכת מהרצון עליון ממש רק ע\"י התלבשות החכמה ברצון להטות איך ומה לרצות וכך יהי' הצורה כו', והיא צורת החומר, אבל בבחי' הצורה הנוספת על החומר כמו בחי' הצמיחה שבצומח והחיות שבחי כו' שהמה רוחניים ממש כידוע שיש נפש הצומחת וכן נפש החי כו' שהם נבדלים בעצם מחומר הפשוט של העץ והחי",[["442","1","<b>שייך לביאור שעל תורה הנ\"ל</b>: כאן הוא הגה\"ה והוספה מאת כ\"ק אדמו\"ר הצ\"צ על הביאור לד\"ה ביום השמע\"צ דלעיל."],["443","2","<b>(א) וזהו ענין התלבשות החכמה בתוך הרצון כו'</b>: לעיל שם בסוף הפיסקא: ובזה יובן ג\"כ."],["444","3","<b>למ\"ש בפנים שההמשכה הוא ע\"י המדות</b>: ראה לעיל במאמר (ד\"ה ביום השמע\"צ) פיסקא: ואל יפלא."],["445","4","<b>כל אשר חפץ ה' עשה</b>: תהלים קלה, ו."],["446","5","<b>כולם בחכמה עשית</b>: תהלים קד, כד."]]],[2101920125,"כו', הן הן נמשכים באמת מבחי' ממכ\"ע ומתלבשים בחומר הפשוט הנמשך מסוכ\"ע ומתאחדים עמו, כמו בחי' נפש החי הנמשכת מחכמה ראשית, והחכמה<sup data-n=\"447\">6</sup> תחי', ונפש הצומחת מן המדות עליונות שנמשכים מחכמה דרך עו\"ע ונק' צומח כו', וע\"ז שייך לומר שהוא ית' הוא העושה אותו כגרזן ביד החוצב בו, שההמשכה הוא ממש מן המדות שהם הגרזן רק שהוא ע\"י כח א\"ס ב\"ה החוצב בהם כו', פי' כי להיות התהוות מחיות רוחני דחכמה חיות גשמי דחי אף שלגבי הגשמיות נחשב זה לרוחניות, מ\"מ הרי הוא מלובש בגשמיות ונק' רוחניות שבגשמיות, וכעד\"ז להיות טעם רוחני שבמזל מתלבש להיות ממנו טעם גשמי בפרי או נפש הצומחת להיות ממנה צמיחת העץ כו', שרוחניות זו מתלבש מכוון בגשמיות, ולכן כח הגשמה זו אינה מהמדות עצמם רק ע\"י כח א\"ס ב\"ה הכל יכול, ומ\"מ ההמשכה היא מן המדות וזהו מכוון למשל כגרזן ביד החוצב כו', או כאדם העושה דבר בידיו שהידים הן ממש עושים ומ\"מ מי גורם לידים שיכתבו הלא האדם כו', וכך ממש אין כח במדות עליונות עצמם להשפיע רוחניות בגשמיות ולהיות גידול העשב ממזל המכה אם לא ע\"י כח א\"ס ב\"ה שהוא המכה במזל כו', ולכן יש שינויים רבים במציאות דדצח\"מ לפי שיש בהם התלבשות בחי' ממלא ממש שהם החכמה והמדות עליונות שמתחלקים לרבבות מדרגות לאין קץ ותכלית כנודע המתיקות נמשך מחסדים והחמיצות מגבורה ומהתכללותם נמשך טעם הכלול ממתיקות וחמיצות כו', משא\"כ יסוד העפר שהוא העשי' גשמיי' נמשך מהרצון ממש שהוא אח\"פ רק שהתלבשות החכמה בו להגבילו איך ומה ירצה כו'.\n<b>והנה</b> באמת לא העשי' גשמיות בלבד הוא שאמרז\"ל ארץ<sup data-n=\"448\">7</sup> קדמה כו', שהיא הנמשכת מרצון עליון דוקא, אלא גם ברוחניות והוא כללות עולמות בי\"ע לגבי אצי' נק' בשם ארץ, ונק' עשי' כי בחי' אצי' הוא אלקות שהחסד הוא חסד שלו כו', משא\"כ אהבה וחסד דמיכאל שבבריאה הוא בבחי' פירוד שהוא יש לעצמו כו', ולכן א\"א להם להתהוות מעצמיות האצי' שבו הוא בחי' ההשתלשלות עו\"ע מחכמה לבינה כו' מפני שכולם אלקות ואלו הי' ההמשכה בדרך זה לא הי' מתהווה מזה לעולם מציאות נפרד כשם שלא הי' התהוות הגשמיות ממש מן הרוחניות כו' אלא שהתהוותם הוא ג\"כ מהרצ\"ע שממנו נתהווה חכמה ראשית האצי' כו'. ומה<sup data-n=\"449\">8</sup> שבמ\"א נת' שהמלאכים נמשכים מכלים דאצי' בבחי' השתלשלות עו\"ע וכנזכר באריכות בענין ההפרש בין המשכה שבאברהם להיות המון גוים שהוא רק מבחי' שערות בלבד משא\"כ ההמשכה בסט' דקדושה שבבי\"ע הוא מעצמיות החסד דאצי', גם זה אמת כי המלאכים<sup data-n=\"450\">9</sup> יש בהם חומר וצורה כמו שהאדם יש בו גוף ונשמה כמ\"ש הרמב\"ן, והנה הנפש שלהם הוא אלקות ממש ונמשכת בבחי' השתלשלות מכלים דאצי' והוא ענין זיווג נשיקין כו', אבל החומר וגוף שלהם נמשך מרצה\"ע הכל יכול,",[["447","6","<b>והחכמה תחי'</b>: קהלת ז, יב."],["448","7","<b>ארץ קדמה כו'</b>: חגיגה יב, א."],["449","8","<b>ומה שבמ\"א נת' שהמלאכים נמשכים . . וכנזכר באריכות בענין ההפרש בין המשכה שבאברהם</b>: ראה ד\"ה להבין המאמר דר' בנאה בסה\"מ תקע\"א ע' קע ואילך. אוה\"ת חיי\"ש קכ, א ואילך."],["450","9","<b>המלאכים יש בהם חומר וצורה . . כמ\"ש הרמב\"ן</b>: בשער הגמול. וראה לקו\"ת ברכה צח, א (ובמ\"מ שם)."]]],[2101920126,"ואמנם גם הגוף שהוא החומר שלהם יש בו צורה ולא גרע מגוף האדם שיש בו נפש הצומחת, מלבד צורת החומר הנ\"ל, וכך ידוע דיש ריבוי מלאכים מחנה מיכאל מחסד ומחנה גבריאל מגבורה כו', והשינוי הוא מצד גופותם, כי נשמת המלאך אינה מובדלת כ\"כ מגופו כנשמת האדם מגופו והיינו לפי שגם הגופות הנה עצם חומרם הפשוט הוא שנמשך מרצ\"ע עצמו, וגם הצורה שבו ע\"י התלבשות החכמה ברצון, אמנם הצורה שבגופו הנוספת על עצם חומרם הפשוט כמשל הצמיחה שבגוף האדם שהוא מלבד נשמתו הוא שנמשך מן המדות רק כגרזן ביד החוצב כו', אבל נשמת המלאך ממש נמשכת מהמדות בבחי' השתלשלות כו', וע'<sup data-n=\"451\">10</sup> מ\"ש ע\"ז בביאור דנ\"ח מימין כו', על הקושיא מ\"ש כל אשר חפץ הוי' עשה וכתיב אמר ויהי אמר דווקא, ונת' דשניהם אמת כי בשעה שאמר יהי אור נתהווה האור והאמירה נמשכת מהחכמה, ואמנם עיקר התהוות חומר האור בשעה שאמר כו' ופעולת האמירה הוא על התהוות צורת ההארה שבגוף הכדור המאיר שנמשכת מהחכמה בבחי' השתלשלות כו', ולפי שצורה זו שבגוף הכדור הוא דבר נוסף על עצם חומרו והיינו בחי' התלבשות הארה ממש מבחי' ממלא בתוכו, לכן צריך לומר יהי אור שבאותיות אלו מלובש הארת החכמה שבחסד כו' משא\"כ צורת החומר שאינו דבר נוסף עליו נמשכת מעצמיות הרצון רק שהחכמה מלובשת בו כו', ולפי שהמלאכים יש בגופותם ב' מיני צורות הנ\"ל, לכן א' שעוף<sup data-n=\"452\">11</sup> יעופף זה מיכאל כו' על התהוות הצורה שבגופו גם שאינו נשמתו ממש וכן לנשמתו שהן מבחי' הכלים דאצי' הנשמה בהשתלשלות והצורה כגרזן כו', משא\"כ עצם חומרו נמשך מעצמיות הרצון, ולכן יש בהם שינוי במציאות רבים על היות הארת המהות<sup data-n=\"453\">12</sup> מתלבש בתוכיותם כנ\"ל בענין הצומח כו', ואמנם באמת כן באצי' עצמו יש חומר וצורה והחומר הוא שאינו נמשך בבחי' השתלשלות עו\"ע רק שרשו למעלה יותר ארץ קדמה כו', והיינו בחי' אורות וכלים שהאורות הן נמשכות מבחי' הקו\"ח, שהוא בחי' הארה מצומצמת שנמשך מא\"ס ב\"ה ומתלבש בעולמות ממש בבחי' פנימיותם ונק' ממכ\"ע משא\"כ הכלים שהם מהותים ומציאותים נפרדים ואינן ממהות הא\"ס ב\"ה שהרי הוא ית' בלי מה ולא מכל אינון מדות איהו כלל וכמו\"כ הם האורות בלי מ\"ה משא\"כ הכלים הם מהותים מוגבלים חסד וגבורה כו', ולכן עפ\"י השתלשלות מן הקו לא הי' באפשרי להיות התהוות הכלים כי הי' הכל רק אורות פשוטים ולא הי' באפשרי להתהוות מזה מציאות מוגבל כשם שא\"א להיות התהוות הגשמיות מן הרוחניות, וכמו שא\"א להיות התהוות הנפרדים ממש שהם גופות הרוחניות של המלאכים מכלים דאצי' שהם אלקות אף שהם מציאותים מוגבלים כו', וכך ממש לא הי' באפשרי להיות התהוות הכלים דאצי' עצמן שהם מציאות מוגבלים חו\"ג כו', מאורות עצמן הנמשכים מן הקו שהם פשוטים כו', והיינו לפי שהקו הוא מה שנתצמצם כבר בבחי' גבול מא\"ס ב\"ה הפשוט ומשם ואילך הוא בחי' השתלשלות ואין כל חדש כו' כנ\"ל.",[["451","10","<b>וע' מ\"ש ע\"ז בביאור דנ\"ח מימין כו'</b>: ראה תו\"א מא, ג ואילך. ובהנסמן לתחילת המאמר שם."],["452","11","<b>שעוף יעופף זה מיכאל כו'</b>: בראשית א, כ. זח\"א מו, ב."],["453","12","<b>המהות</b>: בכת\"י ב: המדות."]]],[2101920127,"<h3>סלח לנו אבינו</h3>\n<b>סלח</b><sup data-n=\"454\">1</sup> לנו אבינו כי חטאנו כו'. לכאורה כי זה אין לו שום שימוש כלל כאן, דמשמע כאילו הוא נתינת טעם למה יסלח לו מפני שחטא וזה פלאי, אלא הו\"ל אשר חטאנו כו'.\n<b>אך</b> הענין דזה קאי עמ\"ש קודם לזה החזירנו בתשובה שלימה לפניך כו' ואזי סלח לנו כו', שענין מחילה הוא החזרת הרצון שנסתלק ע\"י העונות, כי הנה המצות הם רצון העליון וכשחוטא אזי מסתלק הרצון ממנו וזה נק' תרעומות שאינו עושה לו שום מעשה כלל רק שמתרעם עליו, וענין התערומות<sup data-n=\"455\">2</sup> היינו הסתלקות הרצון, ואח\"כ המחילה הוא החזרת הרצון. ואמנם בחי' רצון זה אינו אותו הרצון שהי' תחלה מאחר שהוא נסתלק למה עתה יחזור כו' אלא מבחי' רעוא<sup data-n=\"456\">3</sup> דרעוין מקור הרצונות שממנו נמשך השראת הרצון מחדש והוא יותר נעלה מבחי' הרצון שנסתלק כו', וז\"ש סלח לנו אבינו פי' גלה לנו רצונך מבחי' רעוא דרעוין הנק' רצון העליון כי<sup data-n=\"457\">4</sup> יש גם רצון אחר שהוא תחתון כו'. וכ\"כ למה כי חטאנו ונסתלק ממנו רצון שבמצות ומאחר שעשינו תשוב' א\"כ צריך לגלות לנו רצונו העליון להיות סלח לנו כו'.\n<b>וזשרז\"ל</b> זדונות<sup data-n=\"458\">5</sup> נעשו לו כזכיות וא\"כ כל שיש לו זדונות יותר הרי זכיותיו מרובים אח\"כ מאחר שעל כל זדון צ\"ל המשכת רצון העליון להיות מחילה כו' והוא בחי' זכיות אחרי' שלא כשל הצדיקי' שזכיותיהם הם רק המשכת הרצון שבמצות כו', ולכן במקום<sup data-n=\"459\">6</sup> שבע\"ת עומדים צדיקי' גמורי' אינן יכולי' לעמוד, וכתי' שלום<sup data-n=\"460\">7</sup> לרחוק שנעשה קרוב ברישא והדר לקרוב, וכן יובן כי הזדונות הם ממה שנפל מבחי' אלה<sup data-n=\"461\">8</sup> המלכים למטה מטה ולכן כשמתעלי' ע\"י התשוב' הוא מאד נעלה יותר ממעשה המצות של הצדיקים. וכך הוא ענין הרפואה שטפה א' מהסממני רפואה יש בה כח רב לחיזוק הגוף כהרבה יין ושמן עד\"מ וא\"א לגוף לקבל ולהחזיק כ\"כ מזונות בתוכו משא\"כ בסממני' שפועל כזאת בטפה אחת וז\"ש ישלח<sup data-n=\"462\">9</sup> דברו",[["454","1","<b>סלח לנו</b>: נדפס כאן מגוכי\"ק הצ\"צ בס' תקע\"ב [מס' 1116]. וראה המאמר בס' מאמרי אדה\"ז על מארז\"ל ע' תמח. ובשינויים בדרמ\"צ מצות וידוי ותשובה פ\"ג (לט, א-ב). ובתוס' ביאור בד\"ה בורא ניב שפתיים, סה\"מ תרל\"ג ח\"ב ע' תקכו ואילך. וסה\"מ תרח\"צ ע' מז וע' נד-ה וד\"ה זה תשמ\"ח (נדפס בקונטרס ר\"ח כסלו תשנ\"ג). וראה גם אוה\"ת ויחי תתשיח, א."],["455","2","<b>התערומות</b>: כ\"ה בגוכי\"ק."],["456","3","<b>רעוא דרעוין</b>: זח\"ב פח, א. זח\"ג קכט, א. רפח, ב. ובכ\"מ."],["457","4","<b>כי יש גם רצון אחר שהוא תחתון</b>: ראה תו\"א ויקהל פז, ד. דרמ\"צ פח, ב. ובכ\"מ."],["458","5","<b>זדונות נעשו לו כזכיות</b>: יומא פו, ב."],["459","6","<b>במקום שבע\"ת עומדים</b>: ברכות לד, ב. וראה בארוכה במקורות ובדיוק הלשון ”אין יכולים לעמוד\" בסה\"מ תש\"ט ע' 183 וסה\"מ מלוקט ח\"א ע' ערה."],["460","7","<b>שלום לרחוק שנעשה קרוב</b>: ישעי' נז, יט: בורא ניב שפתים שלום שלום לרחוק ולקרוב אמר ה' ורפאתיו. ובברכות שם: מקום שבע\"ת עומדין כו' שנאמר שלום שלום לרחוק ולקרוב לרחוק ברישא והדר לקרוב כו'."],["461","8","<b>אלה המלכים</b>: וישלח לו, לא."],["462","9","<b>ישלח דברו וירפאם</b>: תהלים קז, כ. וראה גם בארוכה בד\"ה ישלח דברו בס' מאמרי אדה\"ז הקצרים ע' רלא ואילך."]]],[2101920128,"וירפאם שהם צירופי אותיות שנשלחי' ברפואות<sup data-n=\"463\">10</sup> סארסה פרילע כו'. וכך הוא ענין התשו' שהתהפכו' זדונות של הבע\"ת נעלה יותר ממעש' המצות של הצדיקי' לפי שהם למטה ביותר שהוא מפני ששרשם בתהו הוא מלמעלה מעלה ביותר, וז\"ש רז\"ל כל<sup data-n=\"464\">11</sup> העושה תשובה מביא רפואה לעולם וד\"ל.",[["463","10","<b>ברפואות סארסה פרילע</b>: בהערת כ\"ק אדמו\"ר זי\"ע בסו\"ס דרמ\"צ (שם הובא ג\"כ לשון זה) כ' ע\"ז: סארס\"ה פריל\"ע — עץ, מובא בס' הרפואה הקודמים (גם בשם סאלסא פארילא), וגם עתה משתמשים בהיוצא ממנו, בשרשיו לרפואה. וצ\"ע מפני מה הובאה כאן דוקא רפואה זו. ע\"כ."],["464","11","<b>כל העושה תשובה מביא רפואה לעולם</b>: ראה יומא פו, א. וראה גם לקו\"ת פ' ראה כה, ג. נצבים מה, ג. דרך חיים כב, ד ואילך. מג, א ואילך. ובכ\"מ."]]],[2101920129,"<h3>למרבה המשרה</h3>\n<b>[ישעי' ט, ו]</b>\n<b>למרבה</b><sup data-n=\"465\">1</sup> המשרה<sup data-n=\"466\">2</sup> ולשלום אין קץ על כסא דוד ועל ממלכתו להכין אותה ולסעדה היינו בנין המל' שהוא ממלכיות דז\"א, ממל' שבחסד נעשה חסד שבמל', והיינו שאמרו הני<sup data-n=\"467\">3</sup> עשרה מלכיות כנגד מי כו', ונודע שכל ספי' כלולה מי' וי' מי' וכמ\"ש בת\"ז<sup data-n=\"468\">4</sup> שיש ששה אלפי' רבבות ספי' וא\"כ יש הרב' בחי' מלכיות וז\"ש למרבה המשרה מל' שררה כלומר ריבוי שררות ומלכיות, וענין המל' הוא היש של המדה כי חכמ' היא האין ביטול והמלוכה היא הישות, וכן בכל מדה כגון בחי' חסד הט\"ס שבה הם בבחי' ביטול כי חסד נמשך מחכמה אב הרחמן ונק' ענף החכמ' וכל הט\"ס שבו הכל עדיין בבחי' ביטול ואמנם בחי' היש של המדה כשנרא' החסד ליש ודבר זה נק' מל' שבחסד, ואזי צ\"ל ולשלום עד אין קץ כדי שיתחברו יחד כי מטבע הישות גורם הפירוד שאין א' סובל את זולתו וכמו שבתהו שהיו בבחי' וימלוך<sup data-n=\"469\">5</sup> לא<sup data-n=\"470\">6</sup> הוו משגיחין אפין באפין משא\"כ בכרובי'",[["465","1","<b>למרבה המשרה</b>: נדפס כאן מגוכי\"ק הצ\"צ בס' תקע\"ב [מס' 1116]. וראה המאמר בס' מאמרי אדה\"ז על נביאים ע' ס. ושם נדפסו עוד נוסחאות (באריכות) של מאמר זה (ושם ע' סט הוא הנחת כ\"ק אדהאמ\"צ). וראה עניני המאמר באריכות בס' מאמרי אדהאמ\"צ קונטרסים ע' שנא ואילך. סה\"מ עזר\"ת ע' נה ואילך. המשך תער\"ב ח\"א ע' תסו ואילך. וראה מאמר ד\"ה שלום שלום לרחוק ולקרוב בס' מאמרי אדה\"ז על נביאים ע' קסט, שהוא ביאור על מאמר זה."],["466","2","<b>למרבה המשרה ולשלום אין קץ</b>: ישעי' ט, ו."],["467","3","<b>הני עשרה מלכיות כנגד מי</b>: ר\"ה לב, א. וראה פרדס ש\"ב פ\"א."],["468","4","<b>בת\"ז שיש ששה אלפי' רבבות ספי'</b>: ראה שם ת\"ע קלה, א. ע\"ח שער דרושי אבי\"ע (שמ\"ב) ספ\"ה. וראה ס' מאמרי אדהאמ\"צ במדבר ח\"א ע' מב וע' רסג. דברים ח\"ג ע' תתיט. תו\"ח בראשית מה, ד. וש\"נ."],["469","5","<b>וימלוך</b>: וישלח לו, לא ואילך."],["470","6","<b>לא הוו משגיחין אפין באפין</b>: זח\"ב קעו, ב."]]],[2101920130,"כתי' ופניהם<sup data-n=\"471\">7</sup> איש אל אחיו ומשחרב בהמ\"ק החזירו פניהם לאחוריהם זמ\"ז כו' והיינו כי עצמיו' הספי' יכולי' להתחבר יחד מפני שהם בביטול, וז\"ס מ' סתומ' שבלמרבה שיש לה קביעות שמרובעת מלמטה משא\"כ בכל האותיו' שעגולי' בתחתיתן כמו הט' רק הב' והס' אמנם הב' פתוח מצד א' והס' עגול רק המ' סתומה והוא בחי' בינה<sup data-n=\"472\">8</sup> עילא' דיתבא על בנין שיש לה קביעות והיא העושה שלום כו', וכמ\"כ תיבת נח הי' מרובעת שלא ככל הספינות שרחבי' באמצעיתן והולכי' ומתקצרי' בב' הצדדים, והיינו לפי שהיא מבחי' בינה. ואח\"כ על כסא דוד להכין אות' להיות המשכ' מל' אלו דז\"א במל' בשביל בנין הנוק' להכין אותה כו' מעתה ועד עולם, וזה יהי' בימות המשיח או חזקיה<sup data-n=\"473\">9</sup> שבקש הקב\"ה כו' כדאית' בגמ'.",[["471","7","<b>ופניהם איש אל אחיו</b>: תרומה כה, כ."],["472","8","<b>בינה עילאה דיתבא על בנין</b>: ראה זח\"א ו, ג. ובכ\"מ."],["473","9","<b>חזקיה שבקש הקב\"ה כו' כדאית' בגמ'</b>: סנהדרין צד, א."]]],[2101920131,"<h3>ענין ר\"ח</h3>\n<b>ענין</b><sup data-n=\"474\">1</sup> ר\"ח שהוא<sup data-n=\"475\">2</sup> י\"ט של נשים שמשמרות אותו יותר מהאנשים משום שלא רצו ליתן נזמיהן לבעליהן במעשה העגל לפיכך נתן להם הקב\"ה שכרן שיהא משמרות ר\"ח כו'. ויובן בהקדים כללות ענין מעשה העגל, שאמרו הערב רב לישראל בראותם כי האיש משה איננו, אלה<sup data-n=\"476\">3</sup> אלהיך ישראל, שזה פלאי לכאורה לחשוב כן על עגל עשוי מזהב דומם גשמי. אמנם<sup data-n=\"477\">4</sup> הענין הוא כי הנה עיקר טעות פרעה מלך מצרים שאמר מי הוי' אשר אשמע בקולו, וגם אמר לא<sup data-n=\"478\">5</sup> ידעתי את הוי', וכן גם שאר כל האומות, אין הענין שמכחישים ממש באמיתית המצאו, כי כולם יודעים היותו ית' יוצר כל היצורים והוא נצחי וקרו<sup data-n=\"479\">6</sup> לי' אלקא דאלקייא כמ\"ש הודו לאלקי האלקים, אלא שזה הוא טעותם שאומרים עזב<sup data-n=\"480\">7</sup> ה' את הארץ ביד השרים ונתן להם שיהי' הם המנהיגים את הארץ כפי רצונם ואות נפשם ואין לו",[["474","1","<b>ענין ר\"ח</b>: נדפס כאן מגוכי\"ק הצ\"צ בס' תקע\"ב [מס' 1116]. וראה המאמר בס' מאמרי אדה\"ז על ענינים ע' שפג. המאמר נמצא ג\"כ בשינויים והוספות באוה\"ת תשא ע' א'תתקפה [ושם מתחיל: איתא בפדר\"א פמ\"ה הובא ברש\"י מס' מגילה (דכ\"ב ע\"ב) שמעו הנשים]. וראה להלן נוסח שני של המאמר. המאמר הובא ג\"כ באוה\"ת נ\"ך כרך ב' ע' תתקכז."],["475","2","<b>שהוא י\"ט של נשים . . שלא רצו ליתן נזמיהן כו'</b>: ראה פדר\"א פמ\"ה. רש\"י מגילה כב, ב. טור ושו\"ע או\"ח סתי\"ז. וראה עוד ביאור בענין זה (באופן אחר) באוה\"ת תשא שם ע' א'תתקפז. יהל אור להצ\"צ ע' תא."],["476","3","<b>אלה אלהיך ישראל</b>: תשא לב, ד. ח."],["477","4","<b>אמנם הענין . . מי הוי' אשר אשמע בקולו</b>: שם ה, ב. ובהבא להלן ראה בארוכה ספר הערכים — חב\"ד כרך ב ע' רעז."],["478","5","<b>לא ידעתי את הוי'</b>: שם."],["479","6","<b>וקרו לי' אלקא דאלקייא</b>: סוף מנחות."],["480","7","<b>עזב ה' את הארץ</b>: לשון הכתוב — יחזקאל ח, יב. ט, ט."]]],[2101920132,"חלק בה, להיות כי הוא מרומם ונעלה מערך זה, ואומרים השמים<sup data-n=\"481\">8</sup> שמים לה' אבל הארץ נתן להשרים, וז\"ש אלקא דאלקייא כי הם עובדים להמזלות המשפיעים לדעתם חיות בארץ יון<sup data-n=\"482\">9</sup> למזל בתולה שלכך על הרוב נקבות הם המנהיגים הממלכה כו' וקורים להם אלהות שהוא ענין המשפיע לארץ ולדרי' עלי' והוא ית' נק' אלקא דאלקי' כלומר מקור להם אבל אינו מושל בארץ רק אלקא דאלקי' בלבד, ולכן אמר פרעה ע\"ע לא ידעתי את הוי' כי אינו שייך לי כלל, אמנם ישראל אינן בדעת כן כי אין<sup data-n=\"483\">10</sup> מזל לישראל אלא כמ\"ש משה וידעתם<sup data-n=\"484\">11</sup> כי ה' הוא האלהי' בקרב הארץ דייקא לומר שגם למטה הכל תחת ממשלתו ב\"ה בהשגחתו הפרטי' ואין עוד מלבדו גם בארץ מתחת, וע\"ז היו כל האותות שהראה משה למצרים לומר כי ה' הוא האלקי' בארץ דאין מקום למזלות כלל, ובראות כולם גודל המפלות שהי' לפרעה ולמצרים האמינו כולם לזה בראותם כי מזל מצרים לא יכול להתקוממם<sup data-n=\"485\">12</sup> נגדו ולהצילם אין זה מחמת כי אצבע אלקים הוא ית' המושל בכל, ואמנם הערב רב רצו לכפור בזה אח\"כ כאשר זמן שמשה האיש איננו ואז חזרו ורצו גם להשמיע לישראל שהאמת הוא כאשר דימו מתחלה שהמזלות הם המנהיגים בעולם ומה שלקו מצרים ושלא הי' המזל שלהם יכול לעוזרם הוא מסיבה אחרת יען כי י\"ב מזלות המה ומזל מצרים הוא טלה כמ\"ש משה הן<sup data-n=\"486\">13</sup> נזבח את תועבת מצרים כו' כידוע שכל ענין מצות קרבן פסח הי' בשביל זה לשחוט שה ועצם<sup data-n=\"487\">14</sup> לא תשברו בו כ\"א על כרעיו ועל קרבו להראות איך שאין ממש באלהי מצרים שעובדים לשה כמש\"כ גבי יוסף כי<sup data-n=\"488\">15</sup> לא יכלו המצרים לאכל עם העברים, ודימו הערב רב לומר כי מזל שור נלחם עם מזל טלה וגבר עליו כי הרי מצינו שהמזלות נלחמי' זע\"ז כמש\"כ<sup data-n=\"489\">16</sup> בדניאל כו', אבל באמת שהמזלות הם העיקר בארץ ולכן יעצו לעשות עגל לעבוד למזל שור.\n<b>אמנם</b> הנשים לא רצו בזה מצד שרש נשמותיהם היותם מעלמא דנוקבא אשר מלכותו<sup data-n=\"490\">17</sup> בכל משלה שהיא בחי' ראש על כל הע' שרים ויודעי' ומרגישים איך שאין ממש בהם יותר מאשר יודעים האנשים שנשמותם מעלמא דדכורא בחי' ז\"א דאצי' שהוא מרומם ונשגב למעלה מבחי' בי\"ע לגמרי, ולכן האומות אומרים על<sup data-n=\"491\">18</sup> השמים כבודו של מקום בחי' ז\"א דאצי' ועזב את הארץ שהיא המל', וע\"כ",[["481","8","<b>השמים שמים לה'</b>: לשון הכתוב — תהלים קטו, טז."],["482","9","<b>יון למזל בתולה</b>: ראה בחיי דברים לא, טז: וכן אמרו בספרי החכמה כו' מזל עקרב לארצות ישמעאל מזל קשת לפרס מזל גדי לפלשתים מזל בתולה או מאזנים לאדום."],["483","10","<b>אין מזל לישראל</b>: שבת קנו, א."],["484","11","<b>וידעתם כי ה' הוא האלהי'</b>: ראה וארא ח, יח."],["485","12","<b>להתקוממם</b>: כ\"ה בגוכי\"ק."],["486","13","<b>הן נזבח את תועבת מצרים</b>: שם, כב."],["487","14","<b>ועצם לא תשברו בו</b>: בא יב, מו. וראה זח\"ג רנא, א (צויין באוה\"ת שם)."],["488","15","<b>כי לא יכלו המצרים לאכול עם העברים</b>: ראה מקץ מג, לב, תרגום אונקלוס שם."],["489","16","<b>כמש\"כ בדניאל</b>: ראה סי' ח-י."],["490","17","<b>מלכותו בכל משלה</b>: ראה תהלים קג, יח."],["491","18","<b>על השמים כבודו</b>: ראה שם קיג, ד."]]],[2101920133,"מונין<sup data-n=\"492\">19</sup> לחמה ואין מונין ללבנה עם היות כי החמה היא למעלה במדרגה יותר, היא הנותנת כי בזה הוא טעותם באומרי' שעל השמים כבודו ברוחניות אבל אין לו חלק בגשמיות, וישראל מונין ללבנה כלומר כמ\"ש אלקי<sup data-n=\"493\">20</sup> הארץ שהוא למטה דוקא, עם היות כי זהו למטה במדרגה אבל הסיבה לזה הוא דוקא מחמת כי הוא מגביהי<sup data-n=\"494\">21</sup> לשבת למעלה מעלה לכן משפילי לראות בשמים ובארץ, והנשים שרשן ממל' דוקא כי כמו שבלבנה יש מיעוט וריבוי בכל חדש כן הוא עונת הנשים בוסתן מל'<sup data-n=\"495\">22</sup> ליום טמאה ומתקדשת, ולכן הם לא קבלו מהערב רב בענין העגל כאשר קבלו האנשים שמעלמא דדכורא, ולכן ניתן להם ר\"ח שהוא יו\"ט של הלבנה ועת התגלותה כו'.",[["492","19","<b>מונין לחמה</b>: סוכה כט, א."],["493","20","<b>אלקי הארץ</b>: מלכים ב יז, כו. ועוד."],["494","21","<b>מגביהי לשבת</b>: ראה תהלים קיג, ה ואילך."],["495","22","<b>מל' ליום</b>: כ\"ה בגוכי\"ק. ואוצ\"ל: מל' יום לל' יום."]]],[2101920134,"<h3>להבין ענין ר\"ח</h3>\n<b>נוסח אחר</b>\n<b>להבין</b><sup data-n=\"496\">1</sup> ענין ר\"ח שהוא יו\"ט של נשים שמשמרות אותו יותר מן האנשים כמשארז\"ל<sup data-n=\"497\">2</sup> מפני שלא רצו ליתן נזמיהן לבעליהן במעשה העגל לפיכך נתן להם הקב\"ה שכרן שיהיו משמרות את יו\"ט של ר\"ח כו', ודבר זה פלא לכאורה מה שייכות יש לר\"ח עם מעשה העגל כו'.\n<b>אך</b> הנה תחלה י\"ל כללות ענין מעשה העגל שאמרו הערב רב לישראל אלה<sup data-n=\"498\">3</sup> אלקיך ישראל, דלכאורה זה פלא גדול איך יאמרו על עגל זהב גשמי אלה אלקיך כו', אמנם הענין הוא להיות ידוע שגם אוה\"ע מאמינים באחה\"פ שהוא יוצר הכל והוא נצחי וקדמון כו' ואינם מכחישים כלל בזה רק דקרו לי' אלקא דאלקיא פי' שטועים לומר דההנהגה וההשגחה בעולם השפל הוא ע\"י השרים והמזלות שנק' אלקיא שהם המשפיעים כל שפע לדעתם לארץ ולדרים עליה ומושלים בהנהגה כפי רצונם, וגם שמקבלים שפעם לעצמם מאלקי האלקים שהוא בחי' אח\"פ עילת כל העילות כו' וכמ\"ש וצבא<sup data-n=\"499\">4</sup> השמים לך משתחוים וע\"כ קרו לי' אלקא דאלקיא ממש מ\"מ טועים לומר עזב ה' את הארץ להיות ההשפעה לארץ בידי השרים והמזלות להיותו מרומם ונבדל בערך הרבה מהיות בחי' מקור משפיע לארץ אלא הוא בחי' מקור משפיע לאלקיא בלבד ומן המזלות נמשך השפע בכל עניני השגחה פרטיות כו' וכמ\"ש רם<sup data-n=\"500\">5</sup> על כל גוים כו', וטעותם זה הוא ממ\"ש",[["496","1","<b>לה\"ע ר\"ח</b>: נוסח אחר ממאמר הקודם. וראה במ\"מ שם בתחילת המאמר ולהלן ברשימת המאמרים."],["497","2","<b>כמשארז\"ל</b>: נסמן לעיל בנוסח הא'."],["498","3","<b>אלה אלקיך ישראל</b>: ראה תשא לב, ד. ח."],["499","4","<b>וצבא השמים לך משתחוים</b>: נחמי' ט, ו."],["500","5","<b>רם על כל גוים</b>: תהלים קיג, ד."]]],[2101920135,"השמים<sup data-n=\"501\">6</sup> שמים לה' והארץ נתן לבנ\"א כו' שנתן הארץ בידי השרים כו', וזהו שאמר פרעה לא<sup data-n=\"502\">7</sup> ידעתי את ה' כי הוא רם ונבדל למעלה מן הארץ אלא על השמים כבודו כו', אך לא באלה חלק יעקב כי אין<sup data-n=\"503\">8</sup> מזל לישראל אלא ה' הוא אלקים לישראל בקרב<sup data-n=\"504\">9</sup> הארץ דוקא, דהיינו שגם למטה בארץ אין הממשלה וההשגחה פרטיות בכל מיני שפע רק מאת ה' שהוא אלקים בארץ דוקא ואין עוד מלבדו כמ\"ש בשמים<sup data-n=\"505\">10</sup> ממעל וגם על הארץ מתחת אין עוד ואין המזלות רק כמו הגרזן ביד החוצב ממש וכמ\"ש כמצביא<sup data-n=\"506\">11</sup> עבד בחיל שמיא כו' להשפיל ולהרים על מלכי האדמה באדמה ומה'<sup data-n=\"507\">12</sup> מצעדי גבר כו' עד שאין<sup data-n=\"508\">13</sup> אדם נוקף כו' וכמ\"ש עינך<sup data-n=\"509\">14</sup> פקוחות כו', עיני<sup data-n=\"510\">15</sup> ה' משוטטות בכל הארץ, ונק' אלקי הארץ דוקא בלתי יש תפיסת מקום כלל למזלות ושרים כו' וד\"ל. ועל קוטב ויסוד זה הוא שהראה משה כל האותות ומופתים לפני פרעה להראות כי ה' הוא האלקים בארץ דוקא ואין מקום למזל ושר של מצרים לנגדו כי כולא<sup data-n=\"511\">16</sup> קמי' כלא חשיב כו' וכמ\"ש בכל<sup data-n=\"512\">17</sup> אלקי מצרים אעשה שפטים אני ה' עד שהודו חרטומי מצרים ואמרו אצבע<sup data-n=\"513\">18</sup> אלקים הוא המושל בארץ בכל המזלות כו'. אך הנה הערב רב גם שהאמינו בדבר זה בראותם כל האותות והמופתים במצרים, מ\"מ כאשר ראו שהאיש משה איננו חזרו לדמות בנפשם טעותם הראשון שהמזלות עיקר בארץ כי עזב ה' את הארץ ומה שלא הי' ביכולת המזל ושר של מצרים לעמוד לעזרם וגם הוא עצמו נלקה בשפטים גדולים היינו לפי שי\"ב מזלות המה ויש מלחמה ונצוח ביניהם זה עם זה ואולי מזל ישראל מזל שור שגבר על מזל טלה שהוא שר של מצרים כמ\"ש הן<sup data-n=\"514\">19</sup> נזבח את תועבת מצרים כו' שהיו עובדים לשה וכן גבי יוסף ואחיו אמר כי<sup data-n=\"515\">20</sup> לא יוכלו המצרים לאכול עם העברים כו' וכמו שמצינו בדניאל שהשרים והמזלות נלחמו זע\"ז, וע\"כ יעצו הערב רב לישראל לעשות עגל זהב ואמרו אלה אלקיך ישראל אשר העלוך מארץ מצרים כו'.\n<b>אמנם</b> הנה הנשים לא רצו ליתן נזמיהן לבעליהן כי לא רצו להאמין להם בזה, והטעם שהנשים לא רצו בזה יותר מן האנשים הוא מפני ששרש נשמות הנשים בבחי' עלמא דנוק' למעלה שהוא בחי' המל' דכתיב מלכותך<sup data-n=\"516\">21</sup> מלכות כל",[["501","6","<b>השמים שמים לה'</b>: שם קטו, טז."],["502","7","<b>לא ידעתי את ה'</b>: שמות ה, ב."],["503","8","<b>אין מזל לישראל</b>: שבת קנו, א."],["504","9","<b>בקרב הארץ</b>: וארא ח, יח."],["505","10","<b>בשמים ממעל</b>: ואתחנן ד, לט."],["506","11","<b>כמצביא עבד בחיל שמיא</b>: ראה דניאל ד, לב."],["507","12","<b>ומה' מצעדי גבר כו'</b>: תהלים לח, כג."],["508","13","<b>שאין אדם נוקף</b>: חולין ז, ב."],["509","14","<b>עינך פקוחות</b>: ירמי' לב, יט."],["510","15","<b>עיני ה' משוטטות</b>: ראה זכרי' ד, י. דה\"ב טז, ט."],["511","16","<b>כולא קמי' כלא חשיב</b>: זח\"א יא, ב."],["512","17","<b>בכל אלקי מצרים אעשה שפטים</b>: ראה בא יב, יב."],["513","18","<b>אצבע אלקים הוא</b>: וארא ח, טו."],["514","19","<b>הן נזבח את תועבת מצרים</b>: שם, כב."],["515","20","<b>כי לא יוכלו המצרים לאכול עם העברים</b>: ראה מקץ מג, לב."],["516","21","<b>מלכותך מלכות כל עולמים</b>: תהלים קמה, יג."]]],[2101920136,"עולמים כידוע וכתיב ומלכותו<sup data-n=\"517\">22</sup> בכל משלה שבחי' המל' מתפשטת למטה מטה להיות מושל בכל גם במדריגות התחתונות ביותר כמו במזלות ושרים עד שמושל בכל דרכי הטבע בעולם השפל הזה כמ\"ש מלך<sup data-n=\"518\">23</sup> במשפט יעמיד ארץ דוקא וכתיב השופט<sup data-n=\"519\">24</sup> כל הארץ כו' וכמ\"ש מלך<sup data-n=\"520\">25</sup> אלקים על גוים, מי<sup data-n=\"521\">26</sup> לא יראך מלך הגוים כו', וע\"כ היו הנשים מרגישים ומכירים יותר איך שאין ממש במזלות ושרים מצד בחי' שרש נשמותיהן למעלה בבחי' הנוק' יותר מן האנשים כי שרש נשמות האנשים הוא בבחי' עלמא דדכורא דהיינו בבחי' ז\"א דאצי' שלמעלה מבחי' מל' שהוא בבחי' מדות דאצי' שנק' שם הוי' שהוא נשגב ומרומם בבחי' סובב כו' למעלה מהיות גם בחי' מקור לעולמות דבי\"ע כידוע כמ\"ש יהללו<sup data-n=\"522\">27</sup> את שם הוי' כי נשגב שמו לבדו [וגם לאבות לא נגלה כמ\"ש ושמי<sup data-n=\"523\">28</sup> הוי' לא נודעתי להם כו'] וז\"ש עזב<sup data-n=\"524\">29</sup> ה' את הארץ פי' בחי' המל' נק' ארץ כמ\"ש והארץ<sup data-n=\"525\">30</sup> הדום רגלי כו' ואומרים אוה\"ע על השמים כבודו פי' כבוד הוי' הוא בבחי' סובב נשגב ומרומם ונק' כבודו של מקום שהוא בחי' ז\"א בחי' ו\"ק כמ\"ש הנה<sup data-n=\"526\">31</sup> מקום אתי, וכן אלכה<sup data-n=\"527\">32</sup> ואשובה אל מקומי, וכן ממקומו כו', ועזב ה' את הארץ שהוא בחי' המל' להיות ההנהגה ע\"י השרים כו' כמ\"ש השמים<sup data-n=\"528\">33</sup> שמים לה' כו' וע\"כ האנשים האמינו יותר לממשלת השרים והמזלות מן הנשים וד\"ל.\n<b>ובכ\"ז</b> יובן מה שאוה\"ע<sup data-n=\"529\">34</sup> מונין ימי השנה לחמה וישראל מונין ללבנה, ולכאורה הי' ראוי להיות להיפך מאחר שאוה\"ע אינן יודעין את הוי' כו' כי רם עליהם ונשגב כו' כנ\"ל. אך אדרבה היא הנותנת דמשום דטועים לומר שאין הארת אור ושפע משם הוי' בארץ כלל כי עזב ה' את הארץ כנ\"ל להיותו נשגב ורם כו' ועל השמים כבודו בבחי' הרוחני' ולא יצא מאתו אור ושפע למטה בגשמי' ע\"כ כל ימי השנה שתלויין בבחי' הרוחני' דוקא כמ\"ש עוד<sup data-n=\"530\">35</sup> כל ימי הארץ כו' וכן כי<sup data-n=\"531\">36</sup> צל ימינו עלי ארץ כמ\"ש ימים<sup data-n=\"532\">37</sup> יוצרו כו' ונק' ימי<sup data-n=\"533\">38</sup> השמים על הארץ ע\"כ מונין לחמה שהוא בבחי' מדריגה עליונה בשמים דוקא ואין מונין ללבנה שהלבנה היא בבחי' מל' שנק' אלקי הארץ דוקא כי לדעתם עזב ה' את הארץ כנ\"ל וד\"ל, אבל ישראל מונין ללבנה דוקא כי אין מזל לישראל וה' הוא האלקים לישראל בארץ דוקא כנ\"ל באריכות, ואע\"פ שזהו בחי' ומדריגה תחתונה יותר להיות מושל גם בעולם השפל ובאמת נשגב שמו לבדו כו', אדרבה היא הנותנת לומר שאא\"ס נשגב",[["517","22","<b>ומלכותו בכל משלה</b>: שם קג, יח."],["518","23","<b>מלך במשפט יעמיד ארץ</b>: משלי כט, ד."],["519","24","<b>השופט כל הארץ</b>: וירא יח, כה."],["520","25","<b>מלך אלקים על גוים</b>: תהלים מז, ט."],["521","26","<b>מי לא יראך מלך הגוים</b>: ירמי' י, ז."],["522","27","<b>יהללו את שם ה' כי נשגב</b>: תהלים קמח, יג."],["523","28","<b>ושמי הוי' לא נודעתי להם</b>: וארא ו, ג."],["524","29","<b>עזב ה' את הארץ</b>: יחזקאל ח, יב. ט, ט."],["525","30","<b>והארץ הדום רגלי</b>: ישעי' סו, א."],["526","31","<b>הנה מקום אתי</b>: תשא לג, כא."],["527","32","<b>אלכה ואשובה אל מקומי</b>: ראה הושע ה, טו."],["528","33","<b>השמים שמים לה'</b>: תהלים קטו, טז."],["529","34","<b>שאוה\"ע מונין . . לחמה</b>: סוכה כט, א."],["530","35","<b>עוד כל ימי הארץ</b>: בראשית ח, כב."],["531","36","<b>כי צל ימינו עלי ארץ</b>: איוב ח, ט."],["532","37","<b>ימים יוצרו</b>: תהלים קלט, טז."],["533","38","<b>ימי השמים על הארץ</b>: ראה עקב יא, כא."]]],[2101920137,"ומרומם יותר משהוא נשגב ומרומם בדעת הגוים דקרו לי' אלקא דאלקי', כי הנה מאחר שהוא ית' מושל ומשגיח למטה מטה כ\"כ זהו מפני שהוא מרומם למעלה מעלה ביותר שכל המרומם ביותר יותר יכול להשפיל א\"ע למטה יותר כמ\"ש המגביהי<sup data-n=\"534\">39</sup> לשבת המשפילי לראות, דמשום שמגביהי לשבת ע\"כ הוא משפילי לראות, דהא בהא תליא, והטעם הוא משום שלגבי עצמיות אא\"ס ממש מעלה ומטה שוין ממש ע\"כ הוא מושל למטה כמו למעלה ממש בהשוואה אחת כמ\"ש את<sup data-n=\"535\">40</sup> השמים ואת הארץ אני מלא בהשואה אחת וכמ\"ש כי<sup data-n=\"536\">41</sup> כל בשמים ובארץ ותרגומו דאחיד בשמיא ובארעא, לפי שהוא עצמו למעלה מבחי' מעלה ומטה כמשל העיגול הסובב כו' כידוע, וזהו כי<sup data-n=\"537\">42</sup> ה' הוא האלקים שניהם שווין [אע\"פ שהוי' הוא למעלה באצי' ואלקים הוא למטה בארץ בבחי' ממלא כ\"ע כו', קמי' עצמותו שניהם שוין] להיותו למעלה לגמרי מבחי' מעלה ומטה, ובכללות היינו בחי' עצמיות אא\"ס שלפני הקו\"ח שאין שם בחי' מעלה ומטה כלל כמ\"ש בע\"ח, וזהו כמ\"ד<sup data-n=\"538\">43</sup> שמים וארץ כאחד נבראו כמ\"ש במ\"א וד\"ל.\n<b>ואחר</b> כ\"ז יובן ענין ר\"ח שהוא יו\"ט של נשים דוקא מטעם שלא רצו ליתן נזמיהן לבעליהן במעשה העגל כנ\"ל דהנה מבואר למעלה דעיקר מעשה העגל הוא העבודה לכוכבים ומזלות כמו מזל שור והנשים מפני שרשן בעלמא דנוק' שהוא בחי' המל' שמלכותו בכל משלה בכל הארץ דוקא ע\"כ היו יודעים יותר שאין ממש במזלות כו' וא\"כ הרי שרשם בבחי' הלבנה שהוא בחי' הנוק' כמו הלבנה שמקבלת מן השמש וכך הנשים בחי' מקבלים כו' וכידוע בזהר דשמשא וסיהרא הוא בחי' דכר ונוק' כמו דסיהרא<sup data-n=\"539\">44</sup> לית לה מגרמה כלום רק מה שמקבלת מן השמש כך הנשים אין בהן בחי' כח המוליד רק כשמקבלים ממ\"ד דדכורא כו', וגם אנו רואים בזמן קידוש הלבנה כשמתקדשת בכל ר\"ח הוא מל' יום לל' יום שבל' יום הללו יש בה מיעוט ורבוי דהיינו באמצע החודש מתמלאת בקבלתה מן השמש ומתמעטת עד סוף החודש שנעשי' כמו נקודה אחת שזה נק' תכלית הריחוק פגימת הלבנה ובר\"ח חוזרת ומתקדשת בב\"ד שאומרים מקודש עד ז' ימים בחודש שראוי' לקדש ממש וחוזר חלילה כו' וכך הוא עונת הנשים בזמן וסתן שהוא ג\"כ מל' יום לל' יום שבזמן וסתה נעשית טמאה לבעלה בתכלית הריחוק וחוזרת ומתקדשת מטומאתה עד סוף ל' יום שבא אורח בזמנו כו' הרי יש בל' יום הללו קירוב וריחוק כמו בשמש ולבנה כו' וד\"ל. וזהו שלא רצו הנשים ליתן נזמיהן לבעליהן כי לא קבלו הדבר מהערב רב כמו האנשים והיינו שישראל מונין ללבנה שהוא בחי' המל' שמלכותו בכל משלה כנ\"ל, ולזה הטעם נתן הקב\"ה לנשים שכרן",[["534","39","<b>המגביהי לשבת</b>: תהלים קיג, ה ואילך."],["535","40","<b>את השמים ואת הארץ אני מלא</b>: ירמי' כג, כד."],["536","41","<b>כי כל בשמים ובארץ ותרגומו דאחיד בשמיא ובארעא</b>: דה\"א כט, יא. זח\"א ל, א. זח\"ג רנז, א. ז\"ח קג, ב (ונצוצי זהר שם)."],["537","42","<b>כי ה' הוא האלקים</b>: ואתחנן ד, לט. ועוד."],["538","43","<b>כמ\"ד שמים וארץ כאחד נבראו</b>: חגיגה יב, א."],["539","44","<b>דסיהרא לית לה מגרמה כלום</b>: ראה זח\"ב רטו, א. ובכ\"מ."]]],[2101920138,"שיהיו משמרות את ר\"ח שהוא זמן קידוש הלבנה דוקא שמשם שרש הנשים בחי' הנוק' להיותו יו\"ט של הלבנה כשמתקדשת מטומאתה בידי החיצונים בפגימת הלבנה כידוע והנשים שלא רצו ליטמא בטומאת ע\"ז דעגל הזהב אלקים אחרים דמזל שור ע\"כ זכו לשמור ליו\"ט של ר\"ח שהוא יו\"ט של הלבנה וע\"כ הוא יו\"ט של הנשים יותר מן האנשים מטעם הנ\"ל וד\"ל (וכמ\"ש<sup data-n=\"540\">45</sup> במ\"א בענין עיירות מוקפות חומה מימות יהושע קורין בט\"ו משום דפני<sup data-n=\"541\">46</sup> יהושע כפני לבנה ובט\"ו זמן מילוי הלבנה כו' וד\"ל).",[["540","45","<b>וכמ\"ש במ\"א בענין עיירות מוקפות</b>: סה\"מ תק\"ע ע' מא. אוה\"ת מג\"א ע' ערה ואילך."],["541","46","<b>דפני יהושע כפני לבנה</b>: ב\"ב עה, א."]]],[2101920139,"<h3>שחורה אני</h3>\n<b>שחורה</b><sup data-n=\"542\">1</sup> אני ונאוה בנות ירושלים כו'. הנה בז'<sup data-n=\"543\">2</sup> של פסח הוא זמן לידת הנשמות כידוע בענין קי\"ס, והוא<sup data-n=\"544\">3</sup> מבחי' העיבור ז' חדשים משמע\"צ שאז זמן הקליטה כו', ויולדת<sup data-n=\"545\">4</sup> לז' יולדת למקוטעין כו'.\n<b>וביאור</b> ענין הלידה הוא בהקדים ענין או\"כ, דהנה עיקר ההפרש בין האורות וכלים הוא שבחי' הכלים הן מוגבלים במציאותם ואין לחסד שיתוף וחיבור",[["542","1","<b>שחורה אני</b>: מאמר זה הוא הנחת כ\"ק אדהאמ\"צ, ונדפס כאן ע\"פ כמה כת\"י מעתיקים. נוסח שני נדפס בס' מאמרי אדה\"ז כתובים ח\"ב ע' סב [שם בכותרת: ”ליל ש\"ק פ' וירא ביאור לתורה שחורה אני דשבת נחמו\"]. ותוכן קצר של המאמר נמצא גם בלקו\"ת שה\"ש דף ח, ג ודף י, ג-ד. וראה ד\"ה שחורה אני בלקו\"ת שם ו, ג ואילך. ס' מאמרי אדהאמ\"צ נ\"ך ע' רכג ואילך.\nהמאמר נדפס כאן ע\"פ כמה כת\"י מעתיקים, ובכת\"י אחד הוא מופיע בתור ”ביאור שלישי\" לד\"ה שחורה אני ונאוה שנאמר בש\"פ ואתחנן (שבת נחמו) תקע\"א. וכ\"ה בס' מאמרי אדה\"ז כתובים שם. וראה גם סו\"ס מאמרי אדה\"ז תקע\"א ע' שטז-שיז. אך תוכן המאמר הוא גם כענין בפ\"ע.\nמאמר זה הובא בדרמ\"צ להצ\"צ קע, א: ”ועוד מצאתי ראי' ממ\"ש ע\"פ שחורה אני ונאוה פ' וירא תקע\"ב\" [בענין כלים דאצי' שהם בגבול ואעפ\"כ הם אלקות]. ובאוה\"ת בהעלותך ע' שמט ז\"ל: ”ועמ\"ש ע\"פ שחורה אני ונאוה וויטעפסק תקע\"ב עשי' ול\"ת שערות לבנים חסד מ\"ע ודז\"א שחורות ל\"ת\"."],["543","2","<b>בז' של פסח הוא זמן לידת הנשמות</b>: ראה שער הכוונות להאריז\"ל ענין סוכות דרוש ט (יום ט'). פע\"ח שער הלולב (שכ\"ט) סוף פ\"ח. משנת חסידים מס' סוכה פי\"ב. וראה גם לקו\"ת צו טז, ב ואילך. סה\"מ תקס\"ב ח\"ב ע' תח ואילך. תק\"ע ע' פ. לעיל בסוף ביאור ד\"ה ביום השמע\"צ. שער האמונה לאדהאמ\"צ פס\"ב (צז, א) ואילך. ס' מאמרי אדהאמ\"צ ויקרא ח\"א ע' שפז ואילך. סה\"מ תרל\"ג ח\"ב ע' תקצח (ושם ג\"כ ע\"פ שחורה אני ונאוה). וראה גם תניא אגה\"ק ס\"כ (קל, ב). לקוטי שיחות חל\"ט ע' 408."],["544","3","<b>והוא מבחי' העיבור ז' חדשים משמע\"צ</b>: בכ\"מ מהנ\"ל הגירסא ”ו' חדשים\", וראה בארוכה בהמ\"מ בס' מאמרי אדהאמ\"צ ויקרא שם."],["545","4","<b>ויולדת לז' יולדת למקוטעין</b>: ר\"ה יא, א. ובכ\"מ."]]],[2101920140,"כלל עם הגבורה כמו חסד<sup data-n=\"546\">5</sup> דרועא ימינא וגבורה דרועא שמאלא הרי בימין רק חסד ובשמאל רק דין<sup data-n=\"547\">6</sup>, אבל מצד האורות הרי יכול להיות אור<sup data-n=\"548\">7</sup> החסד בכלי הגבורה ואור הגבורה בכלי החסד כו', כי בחי' האורות הן מבחי' הארת אור המאציל עצמו, שמושלל מכל בחי' מציאות דבר מה, וכידוע דאא\"ס אחדות פשוט בתכלית, לאו<sup data-n=\"549\">8</sup> מכל אינון מדות כלל, וע\"כ נק' ע\"ס<sup data-n=\"550\">9</sup> בלי מה בלי מהות, כי האורות פשוטים כמו שעצמות אא\"ס פשוט.\n<b>והענין</b> הוא כי בחי' הכלים הן המוגבלים<sup data-n=\"551\">10</sup> להיות בבחי' מציאות יש ודבר מה כמו חכמה מוחא חסד דרועא כו', הרי חו\"ב וחו\"ג שבכלים הללו הן בבחי' מציאות דבר מה כי הרי אין החכמה נק' חכמה במציאות חכמה ידיעה רק בהיותה מוגבלת בכלי שלה שנק' מוחא וכן חסד דרועא אין החסד עדיין בבחי' מציאות דבר מה רק בהיותה בדרועא ימינא להשפיע חסד וכה\"ג, אבל מצד בחי' האורות עצמן דחו\"ב וחו\"ג אין אור החכמה והחסד בבחי' מציאות מהות דחכמה וחסד אלא בבחי' אין ממש דאחדות פשוטה כו', ולזה הטעם יוכל להיות אור החסד בכלי הגבורה גם שהכלי דגבורה הוא הפוכה מאחר שאין אור החסד עדיין במציאות חסד ממש רק בבחי' אין ההיולי כו' אין כלי הגבורה הפוכה כלל, ונמצא בחי' אורות עם בחי' הכלים הן ב' הפכים שהאורות הן בבחי' אין דאא\"ס, והכלי\"ם הן בבחי' יש בבחי' הסתר האור דא\"ס ע\"כ הן מגבילים האור אך מ\"מ יש קשר וחיבור האורות בכלים והוא ע\"פ המשכה מעצמות המאציל וכמ\"ש אנת<sup data-n=\"552\">11</sup> הוא דמייחד לון ומקשר לון כו' וכמ\"ש במ\"א וד\"ל.\n<b>והנה</b> ג\"כ בבחי' הכלים דע\"ס יש ב' מדריגות והוא פנימי' הכלים וחיצוני' הכלים, ונשמות<sup data-n=\"553\">12</sup> נמשכים מפנימי' הכלים כידוע, וביאור בחי' פנימי' הכלים וחיצוני' הכלים מבואר במ\"א אך זהו ג\"כ בבחי' עיבור ולידה, דהנשמות שהן בבחי' עיבור הרי אמרו שהעובר<sup data-n=\"554\">13</sup> ירך אמו הוא כאחד מאיבריה מתאחד עמה, וג\"כ אמרו שהולד",[["546","5","<b>חסד דרועא ימינא</b>: תקו\"ז בהקדמה ד\"ה פתח אליהו."],["547","6","<b>דין</b>: בכת\"י ב: גבורה."],["548","7","<b>אור החסד בכלי הגבורה</b>: ראה זח\"א פז, א ובמק\"מ שם. וראה בס' מאמרי אדה\"ז ענינים ע' סב, ד\"ה ”להבין מ\"ש בע\"ח שער מטי ולא מטי דלפעמים יכול האור להחליף את הכלי\". ובהמ\"מ שם מצויין בארוכה. וראה ג\"כ ס' מאמרי אדה\"ז עה\"ת ח\"ב ע' תשח. שער היחוד לאדהאמ\"צ קלא, א. תו\"ח שמות (הוצאת תשס\"ג) ח\"ב שפט, ב. ובמ\"מ שם."],["549","8","<b>לאו מכל אינון מדות כלל</b>: תקו\"ז בהקדמה שם."],["550","9","<b>ע\"ס בלי מה</b>: ס' יצירה פ\"א מ\"ד."],["551","10","<b>המוגבלים</b>: בכת\"י ב: המגבילים."],["552","11","<b>אנת הוא דמייחד לון ומקשר לון כו' וכמ\"ש במ\"א</b>: ראה תו\"ח שמות שפט, ב: וכמאמר אנת הוא דמייחד לון ומקשר לון כו' כמ\"ש בע\"ח דמצד האורות יוכל להיות אור החסד בכלי הגבורה כו', מפני שהאורות מצד עצמם כלולים בעצמות אוא\"ס, וזהו דמקשר לון ומייחד לון שאמר ב' דברים קשר ויחוד כו'. וראה שערי אורה עא, א. ועד\"ז בכ\"מ."],["553","12","<b>ונשמות נמשכים מפנימי' הכלים כידוע</b>: ראה לקו\"ת דברים כו, ג ואילך. שם דרושים ליוהכ\"פ ע, ג. לקו\"ת שה\"ש שם ז, ג. ח, ג."],["554","13","<b>שהעובר ירך אמו הוא</b>: יבמות עח, א. ובכ\"מ."]]],[2101920141,"במעי אמו אוכל ממה שאמו אוכלת<sup data-n=\"555\">14</sup> כו', אבל אחר שנולד ויצא לאויר העולם הרי הוא נבדל מאמו ונעשה ברי' בפ\"ע במציאות אחר בלתי קשור ואחוז באמו כלל כו', והדוגמא מזה יובן ג\"כ למעלה שיש ב' מיני נשמות ושניהם מבחי' פנימי' הכלים הא' אותן שבבחי' עיבור במעי אימא עילאה או אימא תתאה שאוכל מה שאמו אוכלת כו' ומתאחד בעצמותה ממש דהיינו כל בחי' הארות והמשכות מאור המאציל שנמשך לבחי' בינה אימא עילאה להיות לה למזון עליון כמו בכל שבת ויו\"ט שניתוסף אור באימא עילאה ע\"י הקרבנות וקידוש והתפילות כידוע והוא מאותו הבירור שנברר ועולה מלמטה למעלה כידוע כמו המזון דלחם הגשמי כו' הרי מבחי' מזון זה שאימא עילאה אוכלת וניזונית הוא שאוכל וניזון אותה הנשמה אלקית בהיותה כלולה בבחי' עיבור כו', והן ז' חדשים דמשמע\"צ זמן הקליטה עד ז' של פסח שהוא זמן העיבור דנשמות כידוע, שבזמן העיבור ניזונת הנשמה ממה שאמו אוכלת כו' ומתגדלים בגידול גמור כו' עד ז' של פסח שיוצאות הנשמות בבחי' לידה להיות בבחי' בריאה ומהות בפ\"ע ונק' נפש ונשמה האלקית שכלולה מפרצוף שלם במוחין ומדות בפ\"ע, כמשל הילד שיצא לאויר העולם כנ\"ל וכמו בולד גשמי שמלמדין<sup data-n=\"556\">15</sup> אותו כל התורה בבטן אמו ואח\"כ צריך ללמוד ביגיעת עצמו כו' כך הנשמה מלמדין אותה כל התורה עילאה דאצי' בהיותה בבינה דאצי' בבחי' עיבור ואח\"כ משגת בהשגת עצמה כו'.\n<b>והנה</b> הנשמות בעודן בבחי' האצי' ממש כנ\"ל נק' בנות ירושלים פי'<sup data-n=\"557\">16</sup> ירושלים יראה שלום הוא בחי' בינה ומל', ירושלים שלמעלה וירושלים שלמטה, ששם בחי' התגלות שלימות העליון שנק' שלימותא דכולא כו', וע\"כ גם הנשמות שניזונים מאימא כו' כנ\"ל נק' בנות ירושלים שמקבלים היראה בבחי' שלימות דא\"ס כו' משא\"כ הנשמות שיוצאות בבחי' לידה במהות בפ\"ע כנ\"ל אין היראה שלהם בבחי' השלימות דא\"ס מאחר שנעשי' בבחי' יש נפרד בהשגת עצמן שהן מוגבלים מאין ליש כו' אלא הן נק'<sup data-n=\"558\">17</sup> כלה מלשון כלתה נפשי כמו מתי<sup data-n=\"559\">18</sup> אבוא ואראה כו' שעדיין",[["555","14","<b>שהולד במעי אמו אוכל ממה שאמו אוכלת</b>: נדה ל, ב."],["556","15","<b>שמלמדין אותו כל התורה</b>: נדה שם."],["557","16","<b>פי' ירושלים יראה שלום</b>: כ\"ה בכת\"י א. ובכת\"י ב: יראה שלם. וכ\"ה בב\"ר פנ\"ו, י, ובתענית טז, א בתוד\"ה הר: יראה שלם. וכ\"ה בשאר מקומות בדא\"ח (וכ\"ה גם בנו\"א של המאמר שלפנינו, בס' מאמרי אדה\"ז כתובים ח\"ב ע' סד. וכ\"ה בד\"ה שחורה בלקו\"ת שה\"ש ו, ג. ז, ב. ובמאמרי אדהאמ\"צ נ\"ך ע' רלב). אולם כהגירסא ”יראה שלום\" נמצא בילקו\"ש תהלים רמז תתיד. ובלקו\"ת פ' ראה לא, ג ז\"ל: בירושלים יראה שלם אך עוד יש לפרש פי' שלם ג\"כ לשון שלום וכמ\"ש בת\"י ע\"פ שובי שובי השולמית דהיינו ירושלים וכן פי' הראב\"ע והרד\"ק בשרשים סוף שרש שלם דהשולמית היינו בירושלים הנק' שלם והרי במדרש שה\"ש פירשו השולמית לשון שלום, וגם בלא\"ה ענין שלימות שייך לענין שלום כמו שפרש\"י פ' וישלח בפסוק שלמים הם אתנו בשלום ובלב שלם ובפ' ויקרא בפסוק ואם זבח שלמים פרש\"י שמטילין שלום בעולם ובזח\"ג ויקרא (די\"ב ע\"ב) פירשו לשון שלימות ולשון שלום וע' בזח\"א קע\"ב סע\"ב ע\"פ ויהי בשלם סוכו. ע\"כ."],["558","17","<b>נק' כלה מלשון כלתה נפשי</b>: תהלים פד, ג. ראה גם תו\"א שמות (בהוספות) קו, א. לקו\"ת במדבר ח, ב. שה\"ש א, א. ובכ\"מ."],["559","18","<b>מתי אבוא ואראה</b>: תהלים מב, ג."]]],[2101920142,"לא ראה רק שמצפה לראות כו' כך כל השגות הנשמות שבבחי' לידה א\"א שישיגו ויראו במהות אא\"ס כמו שהן משיגים בהיותם כלולים באימא עילאה כו' רק מרחוק ה' נראה להם כמ\"ש צמאה<sup data-n=\"560\">19</sup> לך נפשי מתי אבוא כו', ע\"כ יש להם בחי' כלות הנפש בתשוקה מרחוק בלבד כו' כי כל תשוקה אינה אלא מרחוק כי כאשר כבר בא והשיג הדבר אשר אליו יכסוף לא שייך בחי' כלות הנפש בתשוקה כידוע, וע\"כ נק' כלה.\n<b>ומזה</b> יובן בכללות נש\"י שכאשר נולדו מאין ליש מאצי' לבי\"ע שאז הן בבחי' נפרד מאין ליש אז נק' כלה והקב\"ה נק' חתן כמו במ\"ת שנאמר וביום<sup data-n=\"561\">20</sup> חתונתו כו' שהקב\"ה נק' חתן וכנ\"י נק' כלה והוא בחי' משפיע ומקבל שהקב\"ה השפיע את התורה לבנ\"י ובנ\"י נק' בחי' מקבל שקבלו את התורה ממנו כו' וד\"ל.\n<b>ואמנם</b> הנה מובן מכ\"ז דגם דבנות ירושלים הן במעלה יתירה מנשמות שבבחי' לידה מטעם הנ\"ל, מ\"מ יש יתרון מעלה בנשמות שהן במהות בפ\"ע שנק' כלה שהן בחי' מקבל לקבל אור השפע מעצמות אא\"ס שבחכ' כמו במ\"ת שירד אור השפע מאא\"ס שבח\"ע לכנ\"י שנק' כלה כמו הכלה גשמי' שיש לה בחי' בית קיבול לקבל את השפעת התורה משא\"כ נשמות דאצי' שנק'<sup data-n=\"562\">21</sup> בתולות או בנות ירושלים בהיות שאין בהם בחי' כלי לקבל וע\"כ נק'<sup data-n=\"563\">22</sup> ג\"כ עלמות ע\"ש בחי' העלם שאינם יכולים לקבל [וגם שבעיבור מלמדין אותו כו' זהו רק בבחי' העלם המקיף שהרי שוכח מיד שסטרו על פיו] וכמ\"ש בתולות<sup data-n=\"564\">23</sup> אחרי' כו', אבל הנשמות שירדו מאצי' לבי\"ע בבחי' יש בפ\"ע גם שרחוקים מהארת אא\"ס שבאצי' כנ\"ל אשר ע\"כ יתכן בהם בחי' התשוקה כו' כנ\"ל מ\"מ בזאת יתרון מעלתם על שהם בחי' מקבל לקבל כל השפע כו'.\n<b>וראי'</b> לזה הוא ממה שמצינו שהנשמות בג\"ע לומדים כל התורה כולה כמו בעובדא דרבב\"נ שנחלקו<sup data-n=\"565\">24</sup> במתיבתא אם בהרת קדמה לשער לבן כו' וכן בכל דיני ההלכות לומדין הנשמות, רק שיש הרבה חלוקי מדריגות בזה בכל עולם לפי מה שהוא, כי התורה באה בהתלבשות בכל עולם לפי מדריגתו כידוע<sup data-n=\"566\">25</sup> שיש תורה דבריאה ותורה<sup data-n=\"567\">26</sup> דיצי' כו' ובכל עולם כמה מדריגות חלוקות עד עולם שלנו שנתנה לנו תורה בגשמיות, ובכל עולם כל התורה כולה מקבלים הנשמות בבחי'",[["560","19","<b>צמאה לך נפשי</b>: ע\"פ תהלים שם. ותהלים סג, ב."],["561","20","<b>וביום חתונתו כו' שהקב\"ה נק' חתן וכנ\"י נק' כלה</b>: שה\"ש ג, יא. תענית כו, ב. וראה גם לקו\"ת ברכה צג, סע\"ד ואילך."],["562","21","<b>שנק' בתולות</b>: ראה לקו\"ת שה\"ש ו, ג: ”ונקראו בנות ירושלים בבחי' בתולות אחרי' רעותי' מובאות לך\" (ראה להלן בסמוך). וראה גם תו\"א ויחי מט, ב. לקו\"ת שה\"ש שם ח, ד. מג, א. ובכ\"מ. וראה גם עמוס ה, ב. איכה ב, יג."],["563","22","<b>נק' ג\"כ עלמות</b>: שה\"ש ו, ח."],["564","23","<b>בתולות אחרי'</b>: תהלים מה, טו."],["565","24","<b>שנחלקו במתיבתא אם בהרת</b>: ב\"מ פו, א."],["566","25","<b>כידוע שיש תורה דבריאה</b>: לקו\"ת להאריז\"ל ר\"פ בראשית. וראה סה\"מ תרצ\"ו ע' 10. סה\"מ ה'ש\"ת ע' 68. וש\"נ."],["567","26","<b>ותורה דיצי'</b>: בכת\"י ב: ותורה דאצי'."]]],[2101920143,"הרוחני' של הגשמי' כמו ענין הלכות נגעים שלומדים הנשמות בג\"ע דבי\"ע כו' שא\"ז רק בבחי'<sup data-n=\"568\">27</sup> הרוחני' דנגעים הגשמי כמ\"ש במ\"א, אבל בנשמות דאצי' שנק' בנות או עלמות ובתולות כו' אין להם בחי' כלי קבלה לקבל מבחי' מ\"ה דאור אבא כו' כמו הנשמות שבבי\"ע שנק' בעולות כמ\"ש כי<sup data-n=\"569\">28</sup> בועליך עושיך כו' ואין האשה כורתת ברית אלא למי שעשאה כלי בביאה ראשונה כו' שזהו במ\"ת שהי' כמו יחוד חתן וכלה כידוע וד\"ל.\n<b>וזהו</b> שחורה אני ונאוה כו' כנס\"י אומרת לבנות ירושלים שהן בבחי' האצי' שחורה אני בירידתי לבי\"ע בבחי' נפרד כו' בבחי' לידה כנ\"ל. והטעם לבחי' שחרות הזאת הנה יובן מבחי' לידת הנשמות בעוה\"ז דנר<sup data-n=\"570\">29</sup> הוי' נשמת אדם ומנשמה פרטית יוכלו להבין בבחי' נשמה כללי' דכנ\"י שנולדי' מבחי' מל' כו'. דהנה כתיב לפתח<sup data-n=\"571\">30</sup> חטאת רובץ ויש להבין מהו לפתח. אך הנה אמרו<sup data-n=\"572\">31</sup> רז\"ל דהיצה\"ר מתלבש מיד בנשמה האלקי' בצאתה לאויר העולם (כי בבטן אמו גם שכבר מלובשת נשמה בגוף כי ג'<sup data-n=\"573\">32</sup> שותפים כו' אבל אין יצה\"ר שולט כלל וכלל וז\"ש מי<sup data-n=\"574\">33</sup> יתנני כירחי קדם כו', ומ\"ש בחטא<sup data-n=\"575\">34</sup> יחמתני אמי היינו נפש דנוגה דמצד האב ואם כו') וזהו לפתח דוקא חטאת רובץ, לפתח הרחם מיד שנפתח ונולד הולד ויצא לאויר העולם מיד חטאת רובץ שם להלביש לנשמה האלקי' ולהכתירה מכל צד וכמו רשע<sup data-n=\"576\">35</sup> מכתיר את הצדיק כקליפת האגוז כו', והיצ\"ט<sup data-n=\"577\">36</sup> אינו בא עדיין עד היותו בן י\"ג שנה כידוע. מזה יובן ג\"כ בבחי' לידת הנשמה למעלה בכללות נש\"י דמיד שנולדים לפתח חטאת רובץ דהיינו לבחי' פתח הרחם דנוק' דז\"א כשנפתח להוליד נשמות מאין ליש שם חטאת רובץ בחי' נוגה להלביש הנשמות כו' וד\"ל.\n<b>אך</b> הנה יש בזה חילוקי מדריגות בכל עולם לפי מה שהוא, דבעולם<sup data-n=\"578\">37</sup> הבריאה בחי' נוגה שבו רובו טוב ומעוטו רע ע\"כ בחי' לבוש דנוגה שמלביש לנשמות דבריאה אינו לבוש גס כ\"כ כי רובו טוב כו', וביצירה בחי' נוגה מחצה טוב ומחצה רע, ובעשי' רובו רע כו', וידוע שבכל עולם מג' עולמות יש התכללות מבי\"ע וא\"כ גם נשמות דעשי' יש בהן ג' מדריגות ונחלקים לרבבות מדריגות ע\"כ יש נשמות רבות דעשי' שיצה\"ר שלהם אינו רע כ\"כ ויש נשמות שיצה\"ר שלהן רע ביותר כו',",[["568","27","<b>בבחי' הרוחני' דנגעים הגשמי כמ\"ש במ\"א</b>: לקו\"ת תזריע כב, סע\"ב ואילך. וראה בהמ\"מ שם."],["569","28","<b>כי בועליך עושיך כו' ואין האשה כורתת ברית</b>: ישעי' נד, ה. סנהדרין כב, ב."],["570","29","<b>דנר הוי' נשמת אדם</b>: משלי כ, כז."],["571","30","<b>לפתח חטאת רובץ</b>: בראשית ד, ז."],["572","31","<b>אמרו רז\"ל דהיצה\"ר מתלבש מיד</b>: ירושלמי ברכות פ\"ג ה\"ה. זח\"א קעט, ב. ובכ\"מ."],["573","32","<b>ג' שותפים</b>: נדה, לא, א. ובכ\"מ."],["574","33","<b>מי יתנני כירחי קדם</b>: איוב כט, ב."],["575","34","<b>בחטא יחמתני אמי</b>: תהלים נא, ז."],["576","35","<b>רשע מכתיר את הצדיק</b>: חבקוק א, ד."],["577","36","<b>והיצ\"ט אינו בא עדיין עד היותו בן י\"ג שנה כידוע</b>: ראה גם שו\"ע אדה\"ז או\"ח מהדו\"ק ס\"ד ס\"ב, ובמ\"מ שם."],["578","37","<b>דבעולם הבריאה . . רובו טוב ומיעוטו רע</b>: ראה ע\"ח שער ק\"נ (שמ\"ט) פ\"ו. וראה במ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"ג ע' תתלג. ח\"ד ע' א'תצג."]]],[2101920144,"ודרך כלל מי שיש לו נשמה דבריאה בחי' נוגה שבו רובו טוב כו', וכן דרך כלל נחלקים לג' מדריגות נשמה רוח נפש, נשמה<sup data-n=\"579\">38</sup> בבריאה ורוח ביצי' כו' ויש נר\"נ בכל עולם כו'.\n<b>אך</b> לפ\"ז לא יתכן מ\"ש כל<sup data-n=\"580\">39</sup> הגדול מחבירו יצרו גדול ממנו שהרי מי שנשמתו מעולם יותר עליון גם יצה\"ר שלו אינו רע כ\"כ כו'. אך הענין הוא דכל מגמתו של היצה\"ר הוא לטמא את הקדוש והטהור ביותר כמשל הגנבים שודדי לילה שאינם מוסרים נפשם רק במקום שיש הון יקר כו' וע\"כ תשוקתם לידבק דוקא בנשמות הגבוהות ביותר, ומ\"ש לפתח חטאת רובץ היינו כאשר הנשמה באה בהשתלשלות מבריאה ליצירה עד שנולדה בעוה\"ז אז יצרו גדול דנוגה דעשי' וחטאת העשי' רובץ לפתח דלידת הנשמות בעולם העשי' גם באותן שמקורן בבריאה כו', או פי' יצרו גדול כוונתו בנוגה דבריאה כו'.\n<b>והנה</b> כנ\"י אומרים שחורה אני מטעם הנ\"ל מ\"מ נאוה אני יותר משום דירידה צורך עלי' הוא כידוע, ולהבין זה י\"ל תחלה מ\"ש לבושי'<sup data-n=\"581\">40</sup> כתלג חיור ושער רישי' כעמר נקא וכתיב קוצותיו<sup data-n=\"582\">41</sup> תלתלים שחורות כעורב כו' ומשני<sup data-n=\"583\">42</sup> באד\"ר לא קשי' כאן בא\"א כאן בז\"א כו'.\n<b>וביאור</b> הדברים הנה יש להבין תחלה ענין א' שנראה כסותר לכאורה והוא במה שאמרו בבחי' י\"ג מדה\"ר אל רחום כו' ארך אפיים ורב חסד כו' שהן בבחי' י\"ג תקוני דיקנא דא\"א כו' וא\"כ בחי' המדות כמו רחום וחסד וכה\"ג הוא שנמשך מבחי' שערות דדיקנא, ובמ\"א<sup data-n=\"584\">43</sup> אמרו דאור אבא יונק ממזל הח' ונוצר כו' א\"כ הרי החכמה מתהוה מבחי' שערות דדיקנא וידוע דהחכ' מקור המדות כי החסד אינו רק בחי' ענף החכמה כנראה בחוש שמן השכל דוקא נמשך התפעלות החסד והדין וכל המדות כי כל המדות כולן הן למטה מן השכל ולא עוד אלא שנולדים ונמשכים מן השכל דוקא כו', כמ\"ש לפי<sup data-n=\"585\">44</sup> שכלו יהולל איש כנראה בתינוק קטן ששכלו קטן מדותיו קטנים וכשיגדל שכלו נגדלו מדותיו, וא\"כ איך אמר דהמדות רחום וחנון ורב חסד וכה\"ג הן נמשכים מבחי' א\"א שמשם נמשך מקור לחכמה והוא מזל הח' ונוצר כו' מאחר שהמדות נולדים מן החכמה איך יתכן שיהי' מקור א' לחכמה ומדות ולא עוד אלא שמקור המדות קודם למקור החכמה שהרי מקור המדות רחום וחנון כו' הן קודמין למזל נוצר חסד שהוא מקור החכמה כו'",[["579","38","<b>נשמה בבריאה ורוח ביצי' כו'</b>: ראה ת\"ז תכ\"ב (סח, ב)."],["580","39","<b>כל הגדול מחבירו יצרו גדול ממנו</b>: סוכה נב, א. וראה עוד על מארז\"ל זה בס' מאמרי אדה\"ז על מארז\"ל ע' פה. ובמ\"מ שם. וראה להלן ד\"ה בנימין זאב יטרף."],["581","40","<b>לבושי' כתלג חור</b>: דניאל ז, ט."],["582","41","<b>קוצותיו תלתלים</b>: שה\"ש ה, יא."],["583","42","<b>ומשני באד\"ר</b>: זח\"ג קלב, א."],["584","43","<b>ובמ\"א אמרו דאור אבא יונק ממזל הח' ונוצר</b>: ראה זח\"ג רפט, ב. ע\"ח שער הכללים פ\"ה. שער א\"א (שי\"ג) פ\"ט. שער או\"א (שי\"ד) פ\"ג. פ\"ח. ועוד."],["585","44","<b>לפי שכלו יהולל איש</b>: משלי יב, ח."]]],[2101920145,"איך יהי' הטפל קודם לעיקר כו'. אך התירוץ הוא כמו שתי' בענין ב' פסוקים הנ\"ל דסתרי אהדדי כאן בא\"א כאן בז\"א וכך גם כאן הוא התירוץ דב' מדות יש א' בבחי' א\"א והן רחום וחנון כו' ומשם נמשך מקור לחכמה והוא כמו מזל ונוצר כו' והב' מדות דז\"א שלמטה מן החכמה כנ\"ל וכמ\"ש<sup data-n=\"586\">45</sup> בזוהר דאית חסד ואית חסד כו'. וביאור הדברים הנה באמת בהכרח לומר שיש מציאות מדות כמו רחום וחנון כו' גם בבחי' א\"א שהוא בחי' הכתר שלמעלה מן החכמה כי הנה מאחר שאנו רואים שהמדות נולדים ונמשכים מן השכל א\"כ וודאי מוכרח שיש בחי' מציאות המדות בשכל עצמו ג\"כ טרם התמשכותם לבוא לידי גילוי מדות בהתפעלות בלב כי הן כלולות ונעלמות בשכל עצמו, שאם לא הי' בחי' מציאות מדות בשכל כלל לא הי' מציאות גילוי מדות בלב כלל, וכמו שנראה בחוש שיתפעל אדם בשכל באיזה אהבה לדבר מה כמו שכל שמשכיל באיזה דבר טוב כמו איזה מו\"מ וכה\"ג שאנו רואים שמתפעל בשכל לאהוב דבר המו\"מ וכיוצא ואח\"כ נולדה אהבה זו בגילוי בלב, וכך כל המדות כלולות בשכל רק שהן בטילים ונעלמים בשכל ונק' מדות שבשכל והוא בחי' ז\"ת דבינה או חכמה, וכמו\"כ בהכרח לומר בהתהות השכל מלמעלה מן השכל שיש במקור השכל ג\"כ מציאות שכל רק שכלול ונעלם שם בבחי' ביטול והתכללות כו' דאל\"כ לא הי' התהוות השכל כלל מלמעלה מן השכל, וא\"כ כמו שיש שכל בלמעלה מן השכל בהכרח שיש ג\"כ מציאות המדות שבשכל הנ\"ל ג\"כ בלמעלה מן השכל, ומדות אלו אשר בלמעלה מן השכל הוא למעלה מבחי' החכ' והשכל שנמשך מלמעלה מן השכל עד שלא נמשך מהם רק בבחי' שערה בעלמא והוא מזל הח' ונוצר חסד שחסד זה הוא בחי' המדות שלמעלה מן החכמה וממנה נמשך מקור לאור החכמה וזהו דאור אבא יונק ממזל הח' וכמו\"כ הרי אמרו הכל<sup data-n=\"587\">46</sup> תלוי במזל אפילו ס\"ת שבהיכל שהוא בחי' יחוד דאא\"ס<sup data-n=\"588\">47</sup> מב' מזלות דנוצר ונקה כידוע וד\"ל.\n<b>ולהבין</b> ביאור הדברים הנה יש להבין תחילה ענין הידוע שיש ד' מדריגות דצח\"מ בכל עולם מד' עולמות כמו שבעולם העשי' יש ד' מדריגות דצח\"מ, כך בעולם היצי' ובעולם הבריאה וגם בעולם האצי' יש ד' מדריגות דצח\"מ בחי' דומם שבאצי' כמו אבן וכה\"ג הוא בחי' המל' שנק' דומם בערך המדות כמ\"ש אבן<sup data-n=\"589\">48</sup> מאסו הבונים א'<sup data-n=\"590\">49</sup> ב\"ן כו', והוא בחי' אותיות הדבור שנק' אבנים כמ\"ש בס\"י ה'<sup data-n=\"591\">50</sup> אבנים",[["586","45","<b>וכמ\"ש בזוהר דאית חסד ואית חסד</b>: זח\"א ריט, א. זח\"ג כא, א. קלג, ב. קמ, ב."],["587","46","<b>הכל תלוי במזל אפי' ס\"ת שבהיכל</b>: ראה זח\"א קלד, א. וראה לקו\"ת תצא לז, ב. ובמ\"מ בס' מאמרי אדה\"ז עה\"ת ח\"א ע' קכז."],["588","47","<b>דאא\"ס</b>: כ\"ה בכת\"י המעתיק, ואוצ\"ל: דאו\"א."],["589","48","<b>אבן מאסו הבונים א' ב\"ן</b>: תהלים קיח, כב. וראה גם תו\"א משפטים עז, ג. לקו\"ת ברכה צט, ד. ס' מאמרי אדהאמ\"צ בראשית ע' שנט. במדבר ח\"א ע' קסא. דברים ח\"ב ע' תרכט. ח\"ג ע' תשצב. שערי אורה נא, ב. ובכ\"מ."],["590","49","<b>א' ב\"ן כו'</b>: ראה תניא שעהיחוה\"א פ\"ז (פד, ב) ובליקוט פירושים ומ\"מ (חיטריק) שם. ובמ\"מ בס' מאמרי אדהאמ\"צ במדבר שם, ודברים ח\"ב ע' תמא."],["591","50","<b>ה' אבנים בונות ק\"ך בתים</b>: ס' יצירה פ\"ד מי\"ב."]]],[2101920146,"בונות ק\"ך בתים כו' ובחי' צומח שבאצי' הוא בחי' המדות כמ\"ש כי<sup data-n=\"592\">51</sup> האדם עץ השדה בחי' המדות דאדם הן בחי' צומח כצומח שבעץ, שהרי אנו רואים שהמדות נגדלים ונצמחים מעט מעט כמו התינוק מדותיו קטנים וכשיגדל יגדלו המדות כמ\"ש לפי<sup data-n=\"593\">52</sup> שכלו יהולל איש כמ\"ש במ\"א, ומאחר שיש בהן בחי' קטנות וגדלות נק' בחי' צומח כו', אבל בחי' חו\"ב נק' ח\"י כמ\"ש והחכמה תחי' כו', (והבינה נק' חיים בחי' התפשטות החיים והחכמה נק' חי בעצם שממנו התפשטות החיים וכמו עץ החיים שהוא בחי' החכמה דוקא ע\"כ אין שם הסתעפות למות כמ\"ש ימותו<sup data-n=\"595\">54</sup> לא בחכמה כו' ובינה<sup data-n=\"596\">55</sup> נק' אלקים חיים כו' כידוע) ומ\"ש חי<sup data-n=\"597\">56</sup> חי הוא יודוך הן ב' פעמים ט\"ס דאו\"י ואו\"ח שבחו\"ב כמ\"ש<sup data-n=\"594\">53</sup> בזוהר בפי' ובניהו בן איש חי<sup data-n=\"598\">57</sup> כו', ולפעמים חי הוא ביסוד דאבא או יסוד ז\"א, וגם שאנו רואים שיש בחי' הצמיחה מקטנות וגדלות גם בחכמה כמו בתינוק ששכלו קטן וכשיגדל יוגדל ויצמח שכלו כו', א\"ז בחי' צומח לבד אלא בחי' צומח שבחי עצמו שלמעלה מבחי' צומח דמדות שבחכמה שנק' גם הוא צומח שבחי, ואפשר הגידול בשכל אינו רק בשכל שבמדות אבל עצם השכל שמתרבה הוא שנמשך מלמעלה מן ההעלם דמקיף<sup data-n=\"599\">58</sup> דל\"מ דצלם כמ\"ש<sup data-n=\"600\">59</sup> במ\"א בענין הריני כבן ע' שנה, ובחי' הכתר נק' בחי' מדבר ששם מקור החכמה כו' ולמעלה הוא בחי' א\"א דאצי' בחו\"ב שבאצי' בחי' ח\"י, וז\"א דאצי' בחי' צומח ובחי' המל' הוא בחי' דומם כנ\"ל, וכמו\"כ ד' עולמות אבי\"ע אצי' מדבר בריאה חי (והוא<sup data-n=\"601\">60</sup> בחי' מט\"ט ב' טתין גימטריא חי ומט\"ט<sup data-n=\"602\">61</sup> דיצי' בלא יוד כו' ועל שניהם",[["592","51","<b>כי האדם עץ השדה</b>: שופטים כ, יט."],["593","52","<b>לפי שכלו יהולל איש כמ\"ש במ\"א</b>: משלי יב, ח. וראה תניא אגה\"ק סט\"ו (קכג, א). תו\"א ויגש מד, ב. בשלח סו, א. לקו\"ת במדבר יז, ב. פינחס עז, ב. ובכ\"מ."],["595","54","<b>ימותו לא בחכ'</b>: איוב ד, כא."],["596","55","<b>ובינה נק' אלקים חיים כו' כידוע</b>: ראה זח\"ב סח, ב ובהגהות מהרח\"ו ואור החמה שם. ע\"ח שער הצלם (שכ\"ו) פ\"ג. לקו\"ת להאריז\"ל עה\"פ ירמי' י, י. סידור האריז\"ל בברכת יוצר. ובכ\"מ."],["597","56","<b>חי חי הוא יודוך</b>: ישעי' לח, יט. וראה שערי אורה ס, ב. עב, א. שערי תשובה מג, א. מאמרי אדהאמ\"צ דברים ח\"ג ע' תתט (וש\"נ). המשך תער\"ב ח\"ג ע' א'תמו."],["594","53","<b>כמ\"ש והחכ' תחי'</b>: קהלת ז, יב. [בפסוק: החכמה, בלי וא\"ו, אך כן הובא במקומות רבים במדרשים ובספרי ראשונים, ראה: תנחומא ויקהל ז. תקו\"ז בהקדמה (טו, ב). רבינו בחיי בראשית ט, ז. תניא אגה\"ק סי\"ז (קכה, ב). ובכ\"מ]."],["598","57","<b>כמ\"ש בזוהר בפי' ובניהו בן איש חי</b>: שמואל ב כג, כ. זח\"א ו, א. קסד, א. רז, ב."],["599","58","<b>דמקיף דל\"מ דצלם</b>: ראה בלקו\"ת תצא לו, ג ואילך: למ\"ד מ\"ם מקיפים וצ' הוא אור פנימי כו'. ע\"ש בארוכה (ומציין שם לע\"ח ולמבו\"ש)."],["600","59","<b>כמ\"ש במ\"א בענין הריני כבן ע' שנה</b>: ע\"פ ברכות יב, ב. כח, א. ראה גם תו\"א בהוספות קכד, א. תו\"ח לך לך צ, ב. פיה\"מ לאדהאמ\"צ מו, ד. סז, ד. ובכ\"מ. וראה לקוטי הש\"ס להאריז\"ל מס' ברכות."],["601","60","<b>והוא בחי' מט\"ט ב' טתין גימטריא ח\"י</b>: ראה גם תו\"א יתרו עב, א. מאמרי אדה\"ז תקס\"ט ע' קפ. אוה\"ת בראשית כרך ג' תפג, ב. המשך תער\"ב ח\"ג שם ע' א'תמו (בשם זוהר הרקיע)."],["602","61","<b>ומט\"ט דיצי' בלא יו\"ד</b>: ראה ס' שערי ג\"ע שער האותיות אות א' (פתח ו' דרך ד' — לה, ב). ביאוה\"ז וישב כג, ד. ובכ\"מ."]]],[2101920147,"אומר חי חי הוא יודוך כו') ויצי' צומח ועשי' דומם, ומ\"ש אנוש<sup data-n=\"603\">62</sup> כחציר ימיו בבחי' צומח דקטנות וגדלות במדות ובשכל קאי במט\"ט דיצי' בבחי' מדות ובמט\"ט דבריאה הוא בבחי' המוחין כו' וכמ\"ש נער<sup data-n=\"604\">63</sup> הייתי גם זקנתי כו' שרו של עולם אמרו, דקוב\"ה שהוא בחי' ז\"א דאצי' מי<sup data-n=\"605\">64</sup> איכא זקנה קמי' דהרי מל' דאצי' הוא שנעשה בחי' ע\"י לבריאה כו' וכמ\"ש במ\"א וד\"ל.\n<b>והנה</b> כמו\"כ יש ד' מדריגות דצח\"מ הנ\"ל גם בבחי' הכתר שהוא בחי' א\"א להיות שכלול גם הוא מע\"ס כידוע ובחי' המל' שבו נק' בחי' דומם שבכתר ובחי' המדות שבו נק' בחי' צומח ובחי' חו\"ב שבכתר נק' בחי' חי שבכתר ובחי' כתר שבכתר הוא בחי' מדבר כו'.\n<b>והנה</b> מבואר למעלה שיש מציאות שכל ומדות בלמעלה מן השכל והרי כמו שיש מדות בשכל הגלוי כלולים בהעלם כנ\"ל כך יש בשכל הכלול בלמעלה מן השכל ג\"כ בחי' המדות ושניהם נק' בחי' צומח שבחי שבבחי' הכתר דהיינו עצם בחי' שכל שכלול<sup data-n=\"606\">65</sup> בבחי' ו\"ק בחי' חי שבכתר כמ\"ש והחכמה תחי' כו' בחי' ח\"ס שבכתר שנק' חכמה שבכתר כידוע ובחי' השכל שכלול בו בח\"ס שממנו מקור התהוות שכל הגלוי דאל\"כ לא הי' התהוות השכל כלל מלמעלה מן השכל כו' הוא ג\"כ בחי' צומח שבחי וכן המדות שכלולים בשכל זה כמו התינוק שגדל שכלו מלמעלה מן השכל וכן מדות שבשכל זה עם מדותיו שכולם גדלים וצומחים מעט מעט כנ\"ל ונמצא שבחי' המדות שבכתר שנק' צומח סתם הוא למטה גם מבחי' המדות הכלולים בשכל הכלול בח\"ס [שנק'<sup data-n=\"607\">66</sup> צומח שבח\"י עכ\"פ וכערך ההפרש בין צומח סתם לגבי צומח שבח\"י וד\"ל. ועוד ודאי יש הפרש בין צומח שבח\"י דבהמה כצמר הכבש לצומח] דחי שבמדבר, ומלבד ערך ההפרש צומח דשערות לגבי צומח של המדות והשכל שהצומח דשערות הוא מבחי' חיצוניות דחיצוניות הצמיחה דשכל ומדות וכמ\"ש במ\"א באריכות וד\"ל, כי בחי' החי דבהמה אין לו ערוך כלל לבחי' החי שבמדבר שהוא בבחי' החכ' כנ\"ל ובפרט בבחי' חי שבכתר שהוא עיקר בחי' המדבר בכלל כנ\"ל.\n<b>ולפי\"ז</b> מ\"ש למעלה בבחי' א\"א דשער רישי' כעמר נקא בבחי' צומח דשערות הוא בבחי' צומח שבחי שבכתר דהיינו מבחי' מותרי המוחין דא\"א הנק' ח\"ס הבא בבחי' צמיחה לחוץ ואמנם הוא צמיחה גשמי' שמקבלת מצמיחה רוחני' דהיינו בחי' צומח דשכל ומדות הכלולים בח\"ס זה כו' כנ\"ל. אך מה שהמשיל לעמר נק'",[["603","62","<b>אנוש כחציר ימיו</b>: תהלים קג, טו. וראה זח\"ג ריז, ב (דכתוב זה קאי על מט\"ט). וראה לקו\"ת שה\"ש כה, א. ובכ\"מ."],["604","63","<b>נער הייתי גם זקנתי כו' שרו של עולם אמרו</b>: תהלים לז, כה. יבמות טז, ב ותוס' שם. וראה גם שער היחוד קמה, ב. שערי אורה טו, ב. שערי תשובה כט, ב. וע\"ש בהמ\"מ."],["605","64","<b>מי איכא זקנה</b>: יבמות שם: נער הייתי גם זקנתי מאן אמרי' אילימא קוב\"ה מי איכא זקנה קמי' כו'."],["606","65","<b>שכלול בבחי' ו\"ק בחי'</b>: בכת\"י ב: שכלול בכתר נק' בחי'."],["607","66","<b>שנק' צומח . . כצמר הכבש לצומח</b>: שורות אלו ניתוספו מכת\"י ב."]]],[2101920148,"שהוא צומח שבחי סתם הרי מורה על בחי' חי סתם שבחכ' דהיינו לא בבחי' המדות שהם כלולים בח\"ס שהוא שכל הכלול בו שנק' מדות שבשכל אלא בבחי' המדות סתם שנק' צומח סתם שבכתר, וזה א\"א לומר כלל משום דבחי' המדות סתם דא\"א הן המלובשים בנאצלים אור אבא מלביש לחסד דא\"א ובינה לגבורות דא\"א כו' כידוע, אבל בחי' השערות די\"ג ת\"ד כמו מזל ונוצר וכה\"ג הרי הוא למעלה מבחי' חו\"ב<sup data-n=\"608\">67</sup> דא\"א כי הוא בא מבחי' מותרי ח\"ס העצמיים, וכמ\"ש<sup data-n=\"609\">68</sup> במ\"א בהפרש שבין אבא יונק ממזל הח' למה שאור<sup data-n=\"610\">69</sup> אבא מלביש לחסד דא\"א שהיניקה ממזל הוא למעלה הרבה וכמ\"ש הכל תלוי במזל אפילו ס\"ת שבהיכל שהוא יחוד מוחין דאו\"א שמקבלים מן ב' מזלות דנוצר ונקה כנ\"ל, וא\"כ איך אפשר לומר שעמר נק' זה הוא נמשך מבחי' צומח סתם אלא בהכרח לומר שהוא בא מבחי' צומח שבחי דח\"ס העצמי דהיינו מבחי' המדות שבשכל הכלול בח\"ס וכמו מזל ונוצר חסד זהו מבחי' המדות הכלולים בשכל שכלול בח\"ס זה כו' כנ\"ל.\n<b>ולפי\"ז</b> י\"ל למה נמשל עמר נקא בצמר החי סתם. אך הענין הוא דודאי זה אמת די\"ג מדה\"ר רחום וחנון ונוצר חסד וכה\"ג הן מבחי' המדות שכלולים בבחי' צומח שבחי שבכתר כנ\"ל אבל יש הפרש בין צומח די\"ג ת\"ד ששרשם רק בחסד דא\"א לבחי' שער רישי' דא\"א שנק' גלגלתא דא\"א שמקבל מבחי' המדות חו\"ג דע\"י כידוע דחסד דע\"י מאיר בגלגלתא דא\"א וגבורה דע\"י בבחי' מוחא סתימאה דא\"א כו' וז\"ש ושער רישי' כעמר נק' כו', ואמנם הפסוק מדבר בע\"י עצמו וכמ\"ש וע\"י יתיב לבוש' כתלג חיור ושער רישי' כו' וקאי על בחי' ע\"י דשער רישי' כעמר נק' ולפי\"ז בחי' חו\"ג דא\"ק מאירי' בגלגלתא דע\"י וז\"ש דשער רישי' דע\"י כעמר נק' להיות שרש קבלתו רק מבחי' צומח דחי סתם [שבא\"ק<sup data-n=\"611\">70</sup> ועד\"ז עד רום המעלות גם בבחי' דצח\"מ שבג\"ר דא\"ק כו' וד\"ל, והיינו רק בבחי' צומח דחי סתם] שהוא בחי' המדות דחו\"ג דע\"י בלבד אבל ג\"ר דע\"י או ג\"ר דא\"ק הנ\"ל גם בחי' צומח שבחי שבחו\"ב דע\"י הנ\"ל בא\"א הוא נעלה ומרומם מכל האצי' גם מבחי' י\"ג מדה\"ר שהרי שרש י\"ג מדה\"ר אינו<sup data-n=\"612\">71</sup> נמצא בצומח שבחי שבא\"א וגם הרי בחי' גלגלתא דא\"א מקבל רק מבחי' חו\"ג דע\"י כנ\"ל וזהו המתנשא<sup data-n=\"613\">72</sup> מימות עולם פי' מבחי' ז\"ת דע\"י שמלובש בגלגלתא ומוחין סתימאה דא\"א וע\"כ נק' ע\"י כידוע וכמ\"ש<sup data-n=\"614\">73</sup> בזוהר דרישי'",[["608","67","<b>חו\"ב דא\"א</b>: בכת\"י ב: המדות דחו\"ג דא\"א."],["609","68","<b>וכמ\"ש במ\"א בהפרש שבין אבא יונק . . למה שאור אבא מלביש</b>: ראה סידור עם דא\"ח רצה, ג. ס' מאמרי אדה\"ז תקס\"ח ח\"א ע' רסג. מאמרי אדה\"ז עה\"ת ח\"א ע' קכז ואילך. ח\"ב ע' תקסח. לקו\"ת אמור לט, ד. ביאוה\"ז נשא פט, ב. שער היחוד לאדאהמ\"צ קכז, א ואילך. תו\"ח שמות (הוצאת תשס\"ג) ח\"א פט, ב (ובהוצאה הקודמת קכו, א) קלא, א (קסה, א). ר, א (רפו, ב). ועוד."],["610","69","<b>שאור אבא מלביש לחסד דא\"א</b>: ראה ע\"ח שער או\"א (שי\"ד) פ\"א. ובכ\"מ."],["611","70","<b>שבא\"ק ועד\"ז . . צומח דחי סתם</b>: שורות אלו ניתוספו מכת\"י ב."],["612","71","<b>אינו נמצא</b>: בכת\"י ב: אינו אלא."],["613","72","<b>המתנשא מימות עולם</b>: נוסח ברכות ק\"ש."],["614","73","<b>וכמ\"ש בזוהר דרישי' דע\"י</b>: ראה זח\"ג רפח, א."]]],[2101920149,"דע\"י מובדל ומרומם בלי התלבשות כלל להיות מקור לנאצלים ונחשב<sup data-n=\"615\">74</sup> מסוף העולם הא\"ס כידוע וד\"ל.\n<b>ומעתה</b> יש לתרץ הקושיא דלעיל במה שסותר פסוק דשער רישי' כעמר נק' למ\"ש קווצותיו שחורות כו', ומה דמשני כאן בא\"א כאן בז\"א שהן ב' מיני מדות הנ\"ל הוא גופא יש להבין למה זה לבן וזה שחור כו', אך הנה יש להקדים תחלה בשרש ענין המצות דהנה שורש התו\"מ רק מבחי' רצון וחכמה דא\"א שנק' גלגלתא ומוחא [ומשם<sup data-n=\"616\">75</sup> הן תרי\"ג ארחין שבז\"א כו'] ששרשן רק מבחי' חו\"ג דע\"י כנ\"ל אבל בחי' ג\"ר דע\"י למעלה משורש התו\"מ ושם נאמר אם<sup data-n=\"617\">76</sup> צדקת מה תתן לו כו', והטעם הוא כי שרש התו' מח\"ע דאורייתא<sup data-n=\"618\">77</sup> מח\"ע נפקת והיינו מבחי' ח\"ס דא\"א ויורדת משם בבחי' נובלות שהוא בחי' צומח דחי שבכתר כנ\"ל שהוא רק בבחי' המדות הכלולות בח\"ס כמו מזל ונוצר חסד כו', ולזה אמרו דנובלות<sup data-n=\"619\">78</sup> חכמה שלמעלה תורה כי הרי כל עיקר התורה הוא בבחי' המדות להבדיל בין טמא כו' רק שבחכמה<sup data-n=\"620\">79</sup> אתברירו והוא רק בחי' הנובלות דח\"ע שמתלבש במדות כנ\"ל, וכמו\"כ ענין המצות שהוא בחי' רצון עליון המורכב בח\"ס כו', וגם בחי' שער רישי' כעמר נק' הנ\"ל שרש הראשון של המצות הוא רק מבחי' חו\"ג דע\"י כנ\"ל, אבל בחי' חב\"ד דע\"י למעלה מהיות מתלבשים בתו\"מ וכמ\"ש המתנשא מימות עולם כנ\"ל וד\"ל.\n<b>אך</b> הנה יש בזה הפרש בין מ\"ע למל\"ת דהנה ידוע מארז\"ל במצות עשה שהן רמ\"ח מפני שזכרי<sup data-n=\"621\">80</sup> עם ו\"ה רמ\"ח ושמי עם י\"ה שס\"ה ל\"ת, הרי ל\"ת שרשן בי\"ה שהוא בחי' חו\"ב עד רום המעלות כידוע, ומ\"ע שרשן בו\"ה שהוא בחי' המדות והמעשה בלבד, ולפי\"ז הרי שרש המ\"ע רק בבחי' המדות שבכל פרצוף כמו בבחי' המדות שבח\"ס דא\"א עד בחי' המדות דחו\"ג דע\"י שבגלגלתא ומוחא סתימאה כו' שזהו בחי' שער רישי' כעמר נק' כו' כנ\"ל, וטעם הלבנת<sup data-n=\"622\">81</sup> שער הוא לפי שהמ\"ע שרשם בבחי' החסדים שהוא בחי' גילוי ירידת אא\"ס מלמעלה למטה דוקא כמו כל ענין מ\"ע שהוא רק בחי' המשכות אלקות למטה בציצית המשכות ל\"ב נ\"ח ובתפילין המשכות ד' מוחין ובצדקה המשכת בחי' חסד ובמצות ת\"ת המשכות אא\"ס בחכמה כו' וכה\"ג בכל מ\"ע, וגם במצות הקרבנות וכה\"ג שהן בחי' העלאת מ\"מ שורה בהן",[["615","74","<b>ונחשב מסוף העולם הא\"ס כידוע</b>: ראה ע\"ח שער דרושי אבי\"ע (שמ\"ב) פ\"א. סה\"מ תקס\"ב ח\"א ע' יז (בשם עמה\"מ). ובכ\"מ. וראה מאמרי אדהאמ\"צ קונטרסים ע' ד (ובהמ\"מ שם)."],["616","75","<b>ומשם הן תרי\"ג ארחין שבז\"א</b>: ראה לקמן ע' פז. וש\"נ."],["617","76","<b>אם צדקת מה תתן לו</b>: איוב לה, ז."],["618","77","<b>דאורייתא מח\"ע נפקת</b>: זח\"ב סב, א. פה, א. קכא, א. זח\"ג פא, א. קפב, א. רסא, א."],["619","78","<b>דנובלות חכמה שלמעלה תורה</b>: ב\"ר פי\"ז, ה."],["620","79","<b>שבחכמה אתברירו</b>: ראה זח\"ב רנד, ב. ובכ\"מ."],["621","80","<b>שזכרי עם ו\"ה רמ\"ח</b>: תקו\"ז בהקדמה ד, ב. ה, א. וראה לקו\"ת פקודי ג, ב ואילך. ובהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"ב ע' תיב וע' תריח."],["622","81","<b>הלבנת שער</b>: בכת\"י ב: הלבנונית."]]],[2101920150,"בחי' רצון העליון שרוצה בהעלאה זו כו', ואינו רוצה באופן אחר כמו תפילין וציצית פסולין וסוכה פסולה שא\"א להיות בהן המשכות אלקות ה\"ז רק בחי' גבורה שבחסד כו', וז\"ש כעמר נק' כל שערה הוא בחי' המשכה מיוחדת לכל מ\"ע כו', וכ\"א לבן מצד בחי' החסד והן כל הלכות שבמ\"ע שיש לה שערה מיוחדת כו' כמ\"ש הליכות עולם לו כו' וד\"ל.\n<b>אבל</b> כ\"ז בחי' צומח דמדות בלבד אבל שרש ל\"ת בי\"ה היינו בבחי' חו\"ב<sup data-n=\"623\">82</sup> דע\"י שמתנשא מימות עולם המתלבשים בגלגלתא ומוחא סתימאה כו', והענין הוא כי שרש הל\"ת ובפרט דקדוקי סופרים המחמירין ועושין סייגין וגדרים בהתרחקות יתירה כמו במאכלות אסורות כמו חלב ודם מלבד איסור הל\"ת עצמה הן הנה למעלה מבחי' המדות שאינם רק בחי' החסדים כו' כנ\"ל וה\"ז ההעדר והמניעה בהרחקה יתירה בלתי התלבשות למטה בבחי' גילוי זה מורה על היות הדבר במעלה ומדריגה יתירה ע\"כ לא יוכל לבוא למטה בהתלבשות והמשכות גילוי אלקות כמו מ\"ע כו' וכמ\"ש<sup data-n=\"624\">83</sup> במ\"א בענין לאו שקודם להן כו' והיינו בבחי' חו\"ב דע\"י שמתנשא מימות עולם שמתלבשים בתו\"מ דמ\"ע כי<sup data-n=\"625\">84</sup> זהו הכלל שכל הגבוה גבוה יותר יותר יוכל לבוא למטה ביותר וכל שאינו גבוה כ\"כ נעלה לא יוכל לבוא למטה מטה כ\"כ, וראי' לדבר זה ממ\"ש<sup data-n=\"626\">85</sup> באוה\"ח בטעם הענין מה שהארי' הוא חי' טמאה אע\"פ שבמרכבה העליונה פני<sup data-n=\"627\">86</sup> ארי' להימין ופני שור להשמאל כו' אך מפני ששרש פני הארי' גבוה יותר משרש פני השור כו' ע\"כ בירידת אור שפע מהן למטה מטה יוכל להיות מבחי' פני ארי' להימין בחי' ירידות והתלבשות למטה מטה ביותר והוא שמתלבש גם בחיות הטמאות דסט\"א משא\"כ פני שור שאינו גבוה כ\"כ כו' וכמ\"ש למעלה באריכות, וכן יובן דרך זה עוד ממשל נפילת אבן מן הגובה שלפי ערך הגבוה כך ירידתה למטה כו' וכמ\"ש במ\"א וד\"ל.\n<b>וזהו</b> שמי עם י\"ה שס\"ה ל\"ת שהרי שרש ענין הל\"ת עם דקדוקי סופרים הן בבחי' ההעדר והמניעה בלי התלבשות והמשכות למטה בדברים כשרים ומותרין כמו מ\"ע בתפילין וציצית וסוכה וכה\"ג, אלא רק ענינם בדברים האסורים כמו חלב ודם לא תאכלו וכל ל\"ת שעיקר ענינה רק במניעת דברים האסורים שבחלק הס\"א כו' הרי ירדו הל\"ת למטה מטה ביותר מן המ\"ע כמו ע\"ד דוגמא הארי' שהוא חי' טמאה כו' א\"כ ה\"ז הוראה גמורה על היות שרש הל\"ת במעלה ומדריגה יתירה ע\"כ כשנפלה למטה יותר והוא בעניני דברים האסורים דנוגה כו' וד\"ל.",[["623","82","<b>חו\"ב דע\"י</b>: בכת\"י ב: חו\"ג דע\"י."],["624","83","<b>וכמ\"ש במ\"א בענין לאו שקודם להן</b>: ראה לקו\"ת פקודי שם ה, ד. ו, ד. וראה גם תו\"א ויחי נב, ד. בשלח סב, א."],["625","84","<b>כי זהו הכלל שכל הגבוה גבוה יותר יותר יוכל לבוא למטה</b>: ראה בארוכה (וגם בהמשלים ע\"ז שנת' לקמן) שערי אורה לאדהאמ\"צ נח, א ואילך. סה, א ואילך. וראה תו\"ח בראשית כה, א, ובהמ\"מ שם."],["626","85","<b>ממ\"ש באוה\"ח בטעם הענין מה שהארי' הוא חי' טמאה</b>: בפ' אחרי יז, ד (ד\"ה ונראה). וראה גם תו\"א וישלח כה, ג. לקו\"ת שה\"ש שם ט, ד."],["627","86","<b>פני ארי' להימין</b>: ע\"פ יחזקאל א, י."]]],[2101920151,"<b>ואחכ\"ז</b> יובן התירוץ על הסתירה הנ\"ל במ\"ש כעמר נק' וכתיב קווצותיו תלתלים שחורות כעורב כו' דמשני כאן בא\"א וכאן בז\"א כו', דהנה מראות שחורות מורה על תוקף הדין כמו עמר נק' הנ\"ל שמורה תוקף החסד כו', והענין הוא דהל\"ת עם כל פרטי דקדוקי סופרים המחמירין ביותר הן בבחי' תוקף הדין הקשה בבחי' אכזריות שמאל דוחה לדחות ולרחק כו' הנאה כל שהוא מדברים האסורים גם שמץ מנהו עד א' ממאתיים בערלה וס' בבשר וחלב וכה\"ג בכל הרחקות וגדרים שעשו בשמירה יתירה כמו גזירות ח\"י דבר למגדר מלתא כמו סחור סחור לכרמא כו', כ\"ז הוא בחי' תוקף הדין שגזרה ח\"ע דוקא עד\"מ איש חכם ביותר יודע יותר השמירה הטובה מן דברים המזיקים לנפש כו' משאר החכמים כו' כך מבחי' תכלית ח\"ע למעלה משם נמשך שרש הל\"ת ודקדוקי סופרים בכמה פרטי המשכות מיוחדות והן בחי' שערות שחורות כעורב דוקא ע\"ד הנ\"ל בשערות דעמר נק' בבחי' החסדים הרי יש לכל שערה המשכה מיוחדת שהמה פרטי הלכות שבמ\"ע כך יש פרטי הלכות במל\"ת בריבוי דקדוקי סופרים במל\"ת, וז\"ש קוצותיו תלתלים כו' תילי<sup data-n=\"628\">87</sup> תילים של הלכות לרחק ולא לקרב כו', אך הנה בחי' שערות שחורות כעורב הוא בחי' ז\"א דוקא וכדמשני באד\"ר כאן בע\"י וא\"א כאן בז\"א כו'. והענין הוא כמבואר למעלה שיש ב' מיני מדות, מדות שבח\"ס ומדות שלמטה מחכ' דאצי' שהוא בחי' ז\"א דהנה ידוע באד\"ר<sup data-n=\"629\">88</sup> דתרי\"ג ארחין הוא שמתפלגין בז\"א דוקא כמ\"ש כל ארחות ה' דוקא והיינו מפני שבמדות שלמטה מן החכמה שם יש התחלקות חו\"ג דמ\"ע ול\"ת ומתפלגין לתרי\"ג ארחין רמ\"ח מ\"ע ושס\"ה ל\"ת ושם נאמר שחורות כעורב על שס\"ה ל\"ת דוקא, לפי שהדקדוק עפ\"י החכמה בהתרחקות יתירות אינו אלא במדות שנמשכים משכל הגלוי כי שם יוכל להיות תוקף הדין בהרחקות יתירות כו' אבל שרשם הוא בבחי' חו\"ב דע\"י שלמעלה משורש המ\"ע דעמר נק' כו' כנ\"ל בפי' שמי עם י\"ה כו' וד\"ל.\n<b>וזהו</b> שחורה אני ונאוה יותר מבנות ירושלים דהנה ענין הנאוה הוא רק בהארת פנים אמנם יש ב' מדריגות בזה א' במראה הלובן כבנות ירושלים שהוא בבחי' רמ\"ח מ\"ע ששרשם בעמר נק' כנ\"ל וז\"ש יאר<sup data-n=\"630\">89</sup> ה' פניו אליך כו' שהוא אסתכלותא דא\"א בז\"א שמקבל ש\"ע נהורין כו', והב' הנאוה אשר במראה השחרות [שבל\"א נק' שווארץ חענוודיק] שהוא החן אשר יש בשחרות דוקא כמ\"ש ויחונך סתם והוא ע\"י הל\"ת דוקא ששם מקבל בחי' הארת פנים דא\"א יותר מע\"י מצות עשה בחסדים שהרי נאמר חכמת<sup data-n=\"631\">90</sup> אדם תאיר פניו דקאי על בחי' א\"א דחכ' שבו תאיר פניו והוא דוקא ע\"י הארה ממקור החכמה דא\"א כמו בחכ' אדם שלמטה",[["628","87","<b>תילי תילים של הלכות</b>: עירובין כא, ב. ובכ\"מ."],["629","88","<b>באד\"ר דתרי\"ג ארחין . . כל ארחות ה'</b>: זח\"ג קכט, א. קלו, א. תהלים כה, י."],["630","89","<b>יאר ה' פניו אליך . . אסתכלותא דא\"א בז\"א שמקבל ש\"ע נהורין</b>: נשא ו, כה. ראה זח\"ג קכח, ב. קלו, ב. וראה בס' פלח הרמון להר\"ה מפאריטש ע' שסב."],["631","90","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."]]],[2101920152,"שמצהיבין פניו מחמת שמצא שכל חדש מעצם כח המשכיל ע\"י בחי' התענוג העצמי שירד בעצם המשכיל ואם לאו לא הי' בכח המשכיל להשכיל שכל חדש כו' וכמ\"ש<sup data-n=\"632\">91</sup> בע\"ח דפנימי' אבא בחי' ח\"ס הוא פנימי' ע\"י בבחי' ג\"ר שבו דוקא כו' וכמ\"ש במ\"א, ולפ\"ז בחי' הארת פנים דא\"א שע\"י ל\"ת ששרשם מגיע בחו\"ב דע\"י דוקא שלמעלה מחו\"ג דע\"י שמלובשים בגלגלתא ומוחא סתימאה דא\"א כנ\"ל יותר גבוה מהארת פנים דא\"א שע\"י מצות עשה כו' וד\"ל, וזהו שחורה אני ע\"י מל\"ת ונאוה יותר מבנות ירושלים בהגלות נגלות בחי' חו\"ב דע\"י ששם שורה בחי' עצמי' אא\"ס כו', וז\"ש ודלת<sup data-n=\"633\">92</sup> ראשך כארגמן כו' סומקא גו סומקא כו' שמקבלת מן שערות דז\"א שהן שחורות כעורב כנ\"ל והוא בחי' תושבע\"פ<sup data-n=\"634\">93</sup> מל' קרינן לה בבחי' דקדוקי סופרים דמל\"ת דוקא וכמארז\"ל<sup data-n=\"635\">94</sup> ערבים עלי ד\"ס דוקא יותר מיינה של תורה שהוא סוד ה' דגנוז במ\"ע וכה\"ג וכמ\"ש<sup data-n=\"636\">95</sup> ר\"א ב\"ע לר\"ע כלך מדברותיך אצל נגעים ואהלות כו' הרי הפסיקו מללמוד רזין דאורייתא הגנוזין בכל פרטי מ\"ע ללמוד הלכות נגעים ואהלות בהרחקות אשר בדיני הטומאה דס\"א כו' מטעם הנ\"ל וד\"ל.\n<b>כאהלי</b> קדר כיריעות שלמה, הנה אהלי קדר הוא משל לענין שחורה אני הנ\"ל דכמו ששחרות דאהלי קדר הוא בא מתוקף זריחת השמש במדינות החמין כך שחורה אני לפי ששזפתני השמש כו' שהוא ע\"י ל\"ת ששרשן בתוקף הגבורה שהוא תוקף ההארה במדריגה עליונה יותר משרש מצות עשה וכמובן מכל הנ\"ל בענין שחורות כעורב ששרשו למעלה מעמר נק' מטעם הנ\"ל וכמו אהלי קדר שהן בחי' מקיפים כך בחי' הל\"ת באים בבחי' מקיף בהעלם בלתי נודע טעם האיסור וההרחקה כו' משא\"כ מ\"ע הרי נודע סודן בבחי' המשכות כו' וד\"ל.\n<b>כיריעות</b> שלמה מלך<sup data-n=\"637\">96</sup> שהשלום שלו (כנ\"ל<sup data-n=\"638\">97</sup> בביאור הא' והב'). דהנה כל בחי' עילה ועלול אין העילה רוצה לירד ולהשפיע כאשר עדיין צריך שפע לעצמו תחלה כמו איידי<sup data-n=\"639\">98</sup> דטריד למבלע לא פליט, שכאשר המשפיע צריך לקבל לעצמו טוב לו יותר לקבל לעצמו מלהשפיע למקבל, וכמו הוי<sup data-n=\"640\">99</sup> זנב לאריות כו',",[["632","91","<b>וכמ\"ש בע\"ח דפנימי' אבא . . הוא פנימי' ע\"י</b>: פע\"ח שער הק\"ש פט\"ו. וראה לקו\"ת נצבים מט, ד. וש\"נ."],["633","92","<b>ודלת ראשך כארגמן סומקא גו סומקא</b>: שה\"ש ז, ו. ראה זח\"ג קמא, ב. רצו, א."],["634","93","<b>תושבע\"פ מל' קרינן לה</b>: תקו\"ז בהקדמה ד\"ה פתח אליהו."],["635","94","<b>וכמארז\"ל ערבים עלי ד\"ס</b>: ע\"ז לה, א ופירש\"י שם."],["636","95","<b>וכמ\"ש ר\"א ב\"ע לר\"ע כלך מדברותיך</b>: חגיגה יד, א."],["637","96","<b>מלך שהשלום שלו</b>: שמו\"ר פנ\"ב, ה. ובכ\"מ."],["638","97","<b>כנ\"ל בביאור הא' והב'</b>: ביאור הא' על ד\"ה שחורה, נדפס בלקו\"ת שה\"ש ז, ב. ובס' מאמרי אדה\"ז כתובים ח\"ב ע' עג. ביאור הב' נדפס בלקו\"ת שם ז, ד. ובס' מאמרי אדה\"ז שם ע' נד. וראה בהנסמן עוד בסה\"מ תקע\"א ע' שיז. וראה במ\"מ לעיל בתחילת המאמר."],["639","98","<b>איידי דטריד למיבלע לא פליט</b>: ע\"פ חולין קח, ב ופירש\"י שם. וראה שם ח, ב."],["640","99","<b>הוי זנב לאריות</b>: אבות פ\"ד מט\"ו."]]],[2101920153,"ומ\"ש<sup data-n=\"641\">100</sup> שהפרה רוצה להניק כו' היינו כאשר אין צריך לקבל שפע לעצמו, כי כבר שלם הוא בעצמו ולא עוד אלא שיש בו בחי' תוס' יותר מכפי הכלי שלו כענין אגברו<sup data-n=\"642\">101</sup> חמרא אדרדקי כי היכא כו', כמשל חבית המלאה ביותר שאז ישפוך ממנה לחוץ, וכך כל נובלות שפע הוא מיתרון האור שבמשפיע דוקא וכמ\"ש<sup data-n=\"643\">102</sup> בע\"ח שכל זיווג צריך שיומשך תחלה בחי' תוס' מוחין כו', וכמ\"כ בנוק' בחי' המקבל יש בתולות שאינן ראויות לכלי קיבול ואין בהם תשוקה לקבל רק כאשר הגיע לפירקה בבחי' תוס' ג\"כ והוא ענין הסימנים סימן התחתון והעליון כו' וכמ\"ש והנה<sup data-n=\"644\">103</sup> עתך עת דודים שערך צמח כו'. וזהו שהשלום שלו לחבר את המשפיע והמקבל בשביל היחוד שעוזר למשפיע להיות לו תוס' אור כדי שירצה לירד ולהשפיע למקבל, וכן עוזר למקבל שיהי' בה הכנת כלי הקיבול.\n<b>וזהו</b> שחורה אני בבחי' הגבורות שעושי' לה בחי' בית קיבול להתייחד, ובזה נק' נאוה יותר מבנות ירושלים שהן עלמות שאינן ראויות ליחוד שהם בחי' אותיות הפשוטים (כמו ענין הנה<sup data-n=\"645\">104</sup> העלמה הרה הנזכר במ\"א). וזהו כאהלי קדר להיות בבחי' תוס' אור בתוקף גדול ואח\"כ כיריעות שלמה בחי' המקיפים העליונים שמחברים המשפיע אל המקבל ונותנים בהם כח ליחוד וזיווג כו' כנ\"ל וד\"ל. וכמ\"ש<sup data-n=\"646\">105</sup> במ\"א בענין החופה כו', וכמ\"ש<sup data-n=\"647\">106</sup> אפריון עשה לו המלך שלמה מעצי הלבנו\"ן כו', וכמ\"ש<sup data-n=\"648\">107</sup> בביאורים הראשונים כו' וד\"ל.",[["641","100","<b>ומ\"ש שהפרה רוצה להניק</b>: פסחים קיב, א."],["642","101","<b>אגברו חמרא אדרדקי</b>: סנהדרין לח, א: אגברו חמרא אדרדקי כי היכי דלימרו מילתא."],["643","102","<b>וכמ\"ש בע\"ח שכל זיווג . . תוס' מוחין</b>: ראה ע\"ח שער הזיווגים פ\"א. ובכ\"מ."],["644","103","<b>והנה עתך עת דודים שערך צמח</b>: יחזקאל טז, ז-ח."],["645","104","<b>הנה העלמה הרה כו' הנזכר במ\"א</b>: ישעי' ז, יד. סה\"מ תקס\"ה ח\"א ע' שעט. וראה פיה\"מ לאדהאמ\"צ צב, ד: וכמ\"ש במ\"א בענין שאל לך אות כו' העמק שאלה שהוא עוצם הירידה בדרכי הטבע או הגבה למעלה מן הטבע כו' והשיב לא אשאל ולא אנסה כו', על כן אמר לו הנה העלמה הרה כו' שהן אותיות הטבע דאלקים בלתי מקבלים שפע מעלמא דדכורא כלל והן עצמן יהיו היפך הטבע כו'. וראה גם פיה\"מ שם לא, ב."],["646","105","<b>וכמ\"ש במ\"א בענין החופה כו'</b>: ראה לקו\"ת שה\"ש מז, ד. מאמרי אדהאמ\"צ דרושי חתונה ח\"ב ע' תצח. תקצא. ובכ\"מ."],["647","106","<b>וכמ\"ש אפריון עשה לו המלך שלמה</b>: שה\"ש ג, ט."],["648","107","<b>וכמ\"ש בביאורים הראשונים</b>: נסמן לעיל בסמוך."]]],[2101920154,"<h3>בנימין זאב יטרף</h3>\n<b>בנימין</b><sup data-n=\"649\">1</sup> זאב<sup data-n=\"650\">2</sup> יטרף כו' יששכר<sup data-n=\"651\">3</sup> חמור גרם כו'. יש להבין מהו המעלה במה שדימה אותם לזאב ולחמור שהם טמאים, כי מ\"ש ביהודה גור<sup data-n=\"652\">4</sup> אריה יש ליישב עדיין שעם היות האריה<sup data-n=\"653\">5</sup> חי' טמאה אבל מ\"מ הוא מלך שבחיות משא\"כ הזאב בחיות והחמור בבהמות הן פשוטים כו'. אך הענין עפמ\"ש בתירוץ מ\"ש פני<sup data-n=\"654\">6</sup> ארי' אל הימין ופני שור מהשמאל ולמטה נהפוך הוא שהארי' הוא חי' טמאה והשור הוא בהמה טהורה. שהענין הוא כי אדרבה היא הנותנת כי להיות שרש הארי' למעלה בקדושה גבוה מאד נעלה לכן בהתמשכותו למטה דהיינו בירידת החיות להתלבש בבחי' גוף ב\"ו א\"א לו להתלבש בגוף טהרה שאינו בעומק תחת כ\"כ עדיין לפי ערך גבהות שרשו שכל הגבוה גבוה יותר ירידתו למטה נמשך במורד יותר אלא מתלבש בגוף טמא דוקא. אבל פני שור שהוא מהשמאל מתלבש בגוף טהור כו'.\n<b>וביאור</b> זה הוא ע\"ד מ\"ש רז\"ל כל<sup data-n=\"655\">7</sup> הגדול מחבירו יצרו גדול ממנו, והטעם הוא כי הנה ע\"ד דוגמא מדת אהבה היא בודאי מדה גדולה בעבודת ה' ית' ואנו רואים שמסתעף ממנה גם מדת הכעס שכששופך לבו לפני ה' בתפלתו באהבה עזה אזי יכעוס מאד בראותו אח\"כ אנשים הולכים בהבליות ויבער בו מאד קנאת ה' באש תבערה. וכל שתהי' האהבה חזקה ביותר אזי יותר יהי' הכעס אח\"כ על ההיפוך. והנה הכעס בעצם מציאותו הוא לא טוב ועכ\"ז מתהוה דוקא מצד הקדושה דהיינו מהאהבה לאלקות שהרי מי שאין לו אהבה כלל לא יכעוס גם על הרשע והטעם הוא משום שכל דבר יש בו פסולת מחמת עה\"ד טו\"ר לכן גם מהאהבה מתגלה אח\"כ הפסולת וזהו הכעס וכמשל השמרים שביין כו'. וזהו ענין הארי\"ה<sup data-n=\"656\">8</sup> שהוא בגימ' גבורה דהיינו אהבה בתגבורת לה' ית' ולמטה הוא מזיק וטורף ודורס באין מידו מציל. והיינו משום כי גם בשרשו יש פסולת מהאהבה שהוא ענין הכעס על ההיפוך וכמשארז\"ל מזיעתן<sup data-n=\"657\">9</sup> של חיות יוצא נהר דינור ועל<sup data-n=\"658\">10</sup> ראש רשעים יחול כי החיות עומדי' באימה ויראה ולכן יכעסו על הרשעי' והוא",[["649","1","<b>בנימין זאב יטרף</b>: נדפס כאן מגוכי\"ק הצ\"צ בס' תקע\"ב [מס' 1116]. וראה המאמר בס' מאמרי אדה\"ז עה\"ת ח\"א ע' ריח. עניני המאמר נמצאים באריכות בעוד ב' נוסחאות: ביאוה\"ז לאדהאמ\"צ כז, ג (שם ההתחלה על זוהר ויחי דף רט\"ז שבע עשרה שנה מ\"ט כו'. ואפשר גם שם היא הנחה משנת תקע\"ב). ובאוה\"ת ויחי כרך ו' תתשכא, א (ומתחיל: ויחי יעקב)."],["650","2","<b>בנימין זאב יטרף</b>: ויחי מט, כז."],["651","3","<b>יששכר חמור גרם</b>: שם מט, יד."],["652","4","<b>גור אריה</b>: שם מט, ט."],["653","5","<b>האריה . . מלך שבחיות</b>: חגיגה יג, ב."],["654","6","<b>פני ארי' אל הימין גו'</b>: ראה יחזקאל א, י."],["655","7","<b>כל הגדול מחבירו</b>: סוכה נב, א. וראה לעיל בד\"ה שחורה אני (מש\"פ וירא). וש\"נ."],["656","8","<b>הארי\"ה שהוא בגימ' גבורה</b>: פי' הראב\"ד לספר יצירה פ\"א, מי\"ב (לד, ב). ובכ\"מ."],["657","9","<b>מזיעתן של חיות</b>: חגיגה יג, ב."],["658","10","<b>ועל ראש רשעים</b>: ראה ירמי' כג, יט."]]],[2101920155,"הנק' בשם זיעה כמו שהזיעה גשמיו' הוא מים ויוצאים בגוף מחמת חמימות דוקא שהיא מחמת שרוב החום שבגוף מגרש דבר שכנגדו חוצה, וכן הוא סיבת הזיעה במקום חם, כך הוא ענין הכעס שנולד דוקא מיתרון האהבה כנ\"ל. ולהיות כי הארי' למעלה הוא בחי' אהבה גדולה מאד לכן גם הכעס הנולד אח\"כ הוא רב ביותר.\n<b>עד\"מ</b> שאנו רואים בגשמיות הישמעאלים הם בעלי חסד גדולי' למסתופפי' בצלם וזהו מחמת גדלות עצמותם אמנם למורד בו יהי' באכזריות גדולה וימיתהו מיד כרגע. ושניהם סיבת א' כי לפי שהחסד הוא מסיבת הגדלות שלו א\"כ הרי שכנגדו כלא חשיב אצלו כו', משא\"כ מי שאינו יש ודבר בעיניו כ\"כ אף שאינו גומל חסד כ\"כ גם למסתופפי' בצלו אבל אינו מהיר כ\"כ גם בעונש לכשנגדו וגם נפש זולתו יקרה היא כו'. וכמ\"כ הנמשל לענין הארי' שהוא בחי' אהבה בתגבורת בקדושה לכן מן הפסולת נמשך אח\"כ הכעס הקשה ביותר על המנגד ועל ראש רשעים יחול כו' ובירידות המדרגו' בהתלבשותן בגוף גשמי מתהוה מזה ארי' גשמי המזיק ודורס בגשמיות בלי חמלה משא\"כ מפני שור כו' וזהו שכל הגדול מחבירו יצרו גדול הימנו, והוא מובן.\n<b>אמנם</b> לע\"ל כשיתבררו כל הבירורי' וכמארז\"ל עתידה<sup data-n=\"659\">11</sup> חזיר ליטהר כו' אזי יהי' כאו\"א רק כמו שהוא בעצם הקדושה האלקי' ומצד עצם הארי' גבוה יותר וכעד\"ז בשאר כל החיות טמאות שנפלו ממקום שלמעלה יותר שלכך ירד מאד בדילוג הערך יותר כו'. וז\"ש בנימין זאב יטרף וישכר חמור גרם, ואין הכוונה על הזאב והחמור שבקליפה, אלא על השרש ממקום שנפלו הניצוצות להיות זאב והחמור שהוא עליון ביותר כו'.",[["659","11","<b>עתידה חזיר ליטהר</b>: ראה הנסמן בלקו\"ש חי\"ב ע' 175."]]],[2101920156,"<h3>השתחוו[ לה' בהדרת קדש</h3>\n<b>(תהלים כט, ב)</b>\n<b>השתחוו</b><sup data-n=\"660\">1</sup> לה'<sup data-n=\"661\">2</sup> בהדרת קדש, ר\"ת<sup data-n=\"662\">3</sup> קבלה, ואומרים אותו בשבת, ובמזמור לתודה שאומרי' בימי החול נאמר הריעו<sup data-n=\"663\">4</sup> לה' כל הארץ ר\"ת הלכה. ולהבין מהו השייכות פ' דהשתחוו לה' לאומרו אחר ג\"פ הבו שבמזמור לדוד, ומהו ענין הריעו להלכה. הנה קבלה<sup data-n=\"664\">5</sup> הוא באצי' ותלמוד בבריא' ומשנה ביצי' ומקרא בעשיה. וצ\"ל איך יתכן שמקרא שהוא תשב\"כ הוא למטה ממשנה ומתלמוד שהם רק ביאוריה ופירושיה. וגם ידוע שקדושת תשב\"כ יותר מתשבע\"פ שאסור<sup data-n=\"665\">6</sup> להניח גמ' על חומש. אך הענין דפי' תלמוד בבריאה ומשנה וכו' היינו רק בבחי' גילוי ההארה אבל שרשם בבחי' אצילות בין במקרא כו', רק שבבחי' גילוי ההארה בהתלבשותם בעולמות יש בהם חלוקות שהקבלה היא בבחי' אצי' בלבד ולא נמשכ' למטה כלל והתלמוד נמשך ומתלבש בבריאה כו' עד שהמקרא נמשך ומתלבש גם בעשי', והיינו באמת לפי ששרשו שלמעלה בבחי' אצי' הוא גבוה מאד נעלה ממשנה ומתלמוד ומקבלה לכן נמשך ומתלבש גם בבחי' עשי' כנודע<sup data-n=\"666\">7</sup> הכלל שכל הגבוה יותר יכול לירד ולהשפיל עצמו למט' יותר. ולפי ששרש המשנה שבאצי' למטה מן המקרא לכן אינו יכול להתמשך ולהתלבש בעשי' אלא ביצי' בלבד. והתלמוד שהוא למטה בשרשו גם ממשנה אינו מתלבש רק עד בריאה בלבד וכו'.\n<b>ולהבין</b> זה דלכאורה אנו רואים שגם קבלה ירדה בעולם לחכמים מביני מדע שהם בעולם השפל דעשי'. הנה יש<sup data-n=\"667\">8</sup> להקדים תחלה הפרש שבין נביאים למקובלים. דהנה ידוע שיחזקאל<sup data-n=\"668\">9</sup> הנביא שהי' בגלות לא השיג רק בנו\"ה דיצי' ונק'<sup data-n=\"669\">10</sup> בן כפר וישעי' בנו\"ה דבריא' וכן כל הנביאי' חוץ ממרע\"ה שנאמ' עליו",[["660","1","<b>השתחוו לה'</b>: נדפס כאן מגוכי\"ק הצ\"צ בס' תקע\"ב [מס' 1116]. וראה המאמר בס' מאמרי אדה\"ז על כתובים ח\"א ע' ו. וראה עניני המאמר באריכות בד\"ה מזמור לתודה בס' מאמרי אדהאמ\"צ נ\"ך ע' קלט."],["661","2","<b>השתחוו לה' בהדרת קודש</b>: תהלים כט, ב."],["662","3","<b>ר\"ת קבלה</b>: שער הפסוקים להאריז\"ל תהלים ק, א. פע\"ח שער השבת (שי\"ח) פכ\"א. וראה במ\"מ בס' מאמרי אדהאמ\"צ נ\"ך שם ע' קלט."],["663","4","<b>הריעו לה' כל הארץ ר\"ת הלכה</b>: תהלים ק, א. שער הפסוקים שם. פע\"ח שער הזמירות (ש\"ו) פ\"ד."],["664","5","<b>קבלה הוא באצי' . . ומקרא בעשיה</b>: ראה פע\"ח שער הנהגת הלימוד (שי\"ז). תניא פ\"מ בהגה\"ה (נה, ב). אגה\"ק סכ\"ו. לקו\"ת ויקרא ה, א-ב. ס' מאמרי אדה\"ז ”אתהלך לאזניא\" ע' כח. ובכ\"מ."],["665","6","<b>שאסור להניח גמ' על חומש</b>: ראה זח\"א עא, ב ואילך (ובנצו\"א שם). ס' חסידים סקמ\"א (הובא בבית לחם יהודה ליו\"ד ר\"ס רפ\"ג)."],["666","7","<b>כנודע הכלל שכל הגבוה יותר</b>: ראה שערי אורה שער הפורים נח, א. סה, א. ובכ\"מ."],["667","8","<b>יש להקדים תחילה הפרש שבין נביאים למקובלים</b>: ראה גם תניא אגה\"ק סי\"ט. מאמרי אדהאמ\"צ ויקרא ח\"א ע' לו ואילך. ובכ\"מ."],["668","9","<b>שיחזקאל הנביא . . רק בנו\"ה דיצי' . . וישעי' בנו\"ה דבריאה</b>: ראה תקו\"ז בהקדמה ד, א. לקו\"ת להאריז\"ל ישעי' קאפיטל ו. תניא שעהיחוה\"א פ\"ה. אגה\"ק סי\"ט שם. ובכ\"מ."],["669","10","<b>ונק' בן כפר</b>: חגיגה יג, ב."]]],[2101920157,"ולא<sup data-n=\"670\">11</sup> [קם] נביא עוד כמשה וג\"כ הי' נבואתו מבריא' אלא שהי' מב' פרקין קדמאין שבנצח ולא השיג בחי' אצי' אלא כמו שהוא בבחי' התלבשו' בבריא' בחכמ' וחסד שבנצח וזהו וראית<sup data-n=\"671\">12</sup> את אחורי כו' ואהרן הי' נבואתו מב' פ\"ק<sup data-n=\"672\">13</sup> דהוד ושמואל<sup data-n=\"673\">14</sup> שהי' שקול כמשה ואהרן היינו לפי שהי' מקבל מב' הבחי' מנצח ומהוד אבל רק מבחי' אחוריים ושאר כל הנביאי' הם מפ\"ת דנו\"ה כו'. והנה אנו רואי' שהרשב\"י ע\"ה באד\"ר דיבר בעניני' העומדי' ברומו של עולם בבחי' אצי' ולמעלה מהאצי' וכן האריז\"ל עד גם בעולם הא\"ק כו', והיתכן שיהיו גדולים ממרע\"ה אשר התורה העידה עליו ולא קם נביא עוד בישראל כמשה כו'.\nב. <b>אך</b> הענין שיש להקדים ענין אור א\"ס מהו, כי פי' אור א\"ס היינו בחי' ההשפעה שממנו ית' שנקראת בשם אור וכמ\"ש ויקרא<sup data-n=\"674\">15</sup> לאור יום ור\"ל לאור המאיר מהשמש, ועצם השמש נק' מאור. ובאמת באור יש כמה שינויים שכעת ההארה בצמצום ובהסתר פנים ולעתיד יהי' הגילוי בתוספת רב ועצום ויש כמה וכמה עליות ברבוי התגלות ההארה וכ\"ז אינו נוגע לעצמותו ית' הנק' מאור שנאמ' בו אני<sup data-n=\"675\">16</sup> הוי' לא שניתי כמשל אור השמש שאינו פועל שינוי בשמש כידוע, אך מ\"מ גם האור נק' א\"ס כי מ\"מ הרי ההארה והזיו הוא מעין המאור כזיו השמש שהוא מעין השמש וא\"כ אינו בערך הספירו' כלל רק שע\"י צמצומים נתהוה ממנו י\"ס חכמ' חסד כו' אבל מצד עצמו' האור הוא בבחי' א\"ס וכמ\"ש<sup data-n=\"676\">17</sup> בת\"ז שהי' יכול להיות התהוות ריבו' רבבות ספי', פי' שיהי' התהוות מהות ספי' אחרים שאינן ממהו' חסד וחכמ' כלל מאחר שהאור הוא א\"ס רק שע\"י הצמצום שנמשך רק קו מהאור אזי נתהוו רק י\"ס כו' ונק'<sup data-n=\"677\">18</sup> אצי' מלשון ויאצל מן הרוח מרוחו של משה לע' הזקנים ועם כ\"ז לא הי' הזקנים ערוך למשה שהרי<sup data-n=\"678\">19</sup> ולא יספו להתנבאות רק אלדד ומידד היו מתנבאים במחנה. כמ\"כ בחי' הספירו' שהם נאצלים ומוגבלים במהות' חכמה חסד כו' אינן ערוך כלל לגבי עצם האור המאיר ממנו ית' שהוא א\"ס ממש כנ\"ל שהאור הוא עכ\"פ מעין המאור כו'.\n<b>ועוד</b> יש להקדים שיש ב' מיני השגות, א' הוא השגת המהות, ב' ידיעת המציאות. כגון עד\"מ המדות והשכל שבאדם אינו מכיר מהותם רק יודע מציאותם שהרי יודע איש החסד ממציאת טבע החסד המוטבע בלבו להיות מוותר משלו",[["670","11","<b>ולא [קם] נביא עוד כמשה</b>: ברכה לד, י."],["671","12","<b>וראית את אחורי כו'</b>: תשא לג, כג."],["672","13","<b>פ\"ק . . מפ\"ת</b>: [ פרקין קדמאין. מפרקין תתאין] ראה תקו\"ז סוף תיקון י'. ע\"ח שער א\"א (שי\"ג) פ\"א. שער הכוונות דרושי כוונת ק\"ש דרוש ה'. ובכ\"מ."],["673","14","<b>ושמואל שהי' שקול כמשה ואהרן</b>: ברכות לא, ב."],["674","15","<b>ויקרא לאור יום</b>: בראשית א, ד."],["675","16","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["676","17","<b>וכמ\"ש בת\"ז שהי' יכול להיות התהוות ריבו' רבבות ספי'</b>: ראה תי' ע' (קלה, א)."],["677","18","<b>ונק' אצי' מלשון ויאצל מן הרוח</b>: בהעלותך יא, כה. וראה גם תו\"א בראשית ג, א. משפטים עו, ב. ובכ\"מ."],["678","19","<b>שהרי ולא יספו . . רק אלדד ומידד</b>: בהעלותך יא, כה-כז."]]],[2101920158,"לזולתו ומרגיש אותו וכן הקפדן מקפדנותו שהוא טבע מדת הדין והגבורה המוטבע בלבו, ועכ\"ז אינו מכיר מהות החסד איך ומה הוא וכן מהות הקפדנות. וכעד\"ז במחשב' יובן ביותר מאשר אנו רואי' שיזכור האדם איזו שכל וסברא שלמדה כבר כמה שנים ולא עלתה על מוחו בינתיים רק אח\"כ בעיונו בהלכה יזכור אותו השכל, וא\"כ מוכרח שהי' הדבר גם עד הנה טמון בשכלו, והלא האדם אינו מרגיש מזה כלל, והיינו לפי שהשכל אינו דבר יש אלא רוחני ואינו משיג מהותו, ולכן אין כל אדם יכול להשיג איכות ומהות השכל, שאנו רואי' זה חכם וזה טפש, אף ששניהם יש להם מוח גשמי, רק החסרון הוא מצד כח החכמ' הרוחנית, ואין גוף גשמי יכול להשיג מהות רוחני, רק שידע מציאותן שידע בבירור שהוא חכם או שזה סכל, אבל לא יכיר מהות חכמ' זו שבו. ומ\"ש ב'<sup data-n=\"679\">20</sup> רוחות מספרות זע\"ז הוא לאחר פרידת' מהגוף אזי רוחני משיג רוחני זולתו, משא\"כ גוף גשמי אפי' רוחני' שבו אינו משיג רק מציאותו ולא מהותו.\n<b>וכך</b> יובן שזהו ההפרש בין נביאים למקובלים, שזה א\"צ לפנים שידע מרע\"ה כל הרזי דרזין שבאד\"ר אבל מ\"מ נבואתו הי' רק בבריא', פי' בבחי' השגת המהות, שמה שידעו המקובלי' ואפי' רשב\"י ע\"ה היינו רק ידיעת המציאו' בלבד שידע שיש בחי' חכים<sup data-n=\"680\">21</sup> ולא בחכמ' ידיעא אבל לא השיג מהו' חכמ' מהו, וא\"א כלל לאנושי להשיג זאת כי הרי מקור התהוות שכל אנושי הוא רק בבחי' יש מאין מכלים דעשי', ועשי' לגבי יצי' אין ערוך כו' עד מבריאה לאצי', רק שע\"י פרסות שהוא צמצומי' והעלמי' רבי' שמתצמצם אור ושפע החכמ' דאצי' מתהוה ממנה חכמ' אנושי', ולכן לא בחכמ' ידיעא כלל וא\"כ הרי א\"א להשיג בחכמ' שלמטה חכמה עליונ' ית' רק מציאות' בלבד. ועד\"ז השיג הרשב\"י ע\"ה מה שהשיג בבחי' אצי' ולמעלה מהאצי', וכל אלה לא נפלאו גם ממרע\"ה ופשיטא הוא, אבל מ\"ש שמרע\"ה הית' נבואתו רק בעולם הבריאה היינו בחי' השגת המהות, שבעולם הבריא' השיג מהות אותו העולם ממש, וכזה השיג ישעי' ג\"כ בבריא', וז\"ש שרפי'<sup data-n=\"681\">22</sup> עומדים כו' שהם בבריא' אבל למטה ממשה כנ\"ל, ויחזקאל ביצי' כו'. והוא עד\"מ כמו בחי' הדבור שבאדם שמשיג האדם מציאותו ומהותו לפי שהוא בערכו להיות מושג מחמת שהוא גשמי כמוהו, כי הגם שכ\"ב האותיות הם מהנפש כידוע דאע\"פ שאחה\"ע<sup data-n=\"682\">23</sup> יוצאי' מהגרון כו' היינו שאותיות אחה\"ע יוצאי' מן הנפש ומכים בגרון ועושים בו הקול וכן בומ\"ף בשפתים כו' ואותיו' שבנפש הם רוחניים, אין הכוונה שגשם האותיות הוא מהנפש כי גשם האותיות הוא הקול שהוא גשמי רק שכ\"ב אותיות הנפש מתלבשים בו, אחה\"ע מתלבשי' בקול שבגרון כו'. ולהיות כי יש להם עכ\"פ חומר גשמי לכן נתפסים במהותם ממש להאדם שהרי המדבר מרגיש מהות קול הדברים שמוציא מפיו ואינן כמו המדות והשכל שבו שאינו מכיר ותופס",[["679","20","<b>ב' רוחות מספרות זע\"ז</b>: ברכות יח, ב."],["680","21","<b>חכים ולא בחכמה ידיעא</b>: תקו\"ז בהקדמה ד\"ה פתח אליהו (יז, ב)."],["681","22","<b>שרפי' עומדים כו'</b>: ישעי' ו, ב."],["682","23","<b>שאחה\"ע יוצאי' מהגרון</b>: ראה ס' יצירה פ\"ב מ\"א."]]],[2101920159,"מהות' בלבד<sup data-n=\"683\">24</sup> רק שיודע שהם נמצאי' בלבד. ועד\"ז ענין הנבוא' הוא תפיס' מהות ועצמו' הדבר הנראה לו ובזה יש חלוקות ישעי' ראה והשיג כך ויחזקאל כך כנ\"ל.\nג. <b>ועתה</b> יובן ענין מקרא בעשי' כו' עד קבלה באצילות. כי הנה כתי' בראשי'<sup data-n=\"684\">25</sup> ברא אלקי' את השמים ואת הארץ וכתי' ביום עשות הוי' אלקים ארץ ושמים והכריעו רז\"ל במחשבה ארץ קדמה כו'. כי יש ב' בחי' ממכ\"ע וסכ\"ע, והנה ממכ\"ע הוא בחי' השתלשלות עילה ועלול והכל ברוחני' אבל להיות התהוות עשי' גשמיות א\"א להיות כלל עפ\"י השתלשלות שאין ערוך גשמיות לרוחניות אלא מא\"ס ב\"ה דוקא הסוכ\"ע שהוא כל יכול, פי' כי הרי נז\"ל שגם התהוות החכמה מא\"ס ב\"ה הוא ע\"י צמצום רב ועצום א\"כ קמי' ית' שוה להיות מהוה דומם גשמי כמו שמהוה החכמה ששניהם אינן ערוך אצלו ית' בשוה. וזהו שבמחשב\"ה שהוא בחי' סוכ\"ע ארץ קדמה, ולכן ג\"כ גבי ארץ נאמר הוי' אלקי' וגבי שמים לא נאמר הוי' רק אלקים בלבד שהוא ממכ\"ע וכמ\"ש בחכמה<sup data-n=\"685\">26</sup> יסד ארץ משא\"כ שמים הוא כונן בתבונה כו'. ולכן מקרא בעשי', מקרא דוקא ששרשו שבאצי' הוא למעלה מעלה ממשנה ומתלמוד כו' יכול להתלבש למטה בבחי' עשי' גשמיות עד שנק' תשב\"כ בדיו ע\"ג קלף גשמי וכל קדושתה נשפל בבחי' עשיה דוקא שעיקר הקפידא הוא על ציור והידור האותיות הגשמיים כו'. ועוד טעם למה שנשפל בבחי' מעשה כתב גשמי ולא כתשבע\"פ בדיבור משום שצ\"ל בה תגין וטעמים שהם אותן סתרי' דאורייתא שא\"א לפרשן בפה אלא לחכימא ברמיזא שהן התגי' והטעמי' שרומזי' לעניני' פלאים כידוע. אבל משנה ביצירה שלא יכלה להתלבש כ\"כ למטה בעשיה גשמיות אלא ביצירה (שהוא ממוצע בין בריאה שהוא תכלית הרוחני' לעשי' הגשמיו') והיינו בחי' הדבור שכלול מרוחני' וגשמיות כי הרי כ\"ב אותיות הן עצמן רוחני' ונמשכי' מהחכמה (פי' קדמות השכל שלמעלה מהשכל המושג) ומתלבשי' בקול היוצא מהבל הלב שהוא גשמי כו'. ותלמוד בבריאה שא\"א לו כלל להתלבש בשום בחי' גשמיות אלא ברוחני' בלבד והוא עולם הבריאה דאימא<sup data-n=\"686\">27</sup> עילא' מקננא בכורסייא והוא עד\"מ למטה בחי' השכל שאינו מעורב משום בחי' גשמיות כמו הדיבור מ\"ט דר' כו' אבל קבלה באצילות. כי הנה ג' עולמות בי\"ע אף שבדרך פרט נחלקי' לג' בחי' חלוקות כנ\"ל אבל לגבי אצי' כולם הם בחי' יש ואצי' בלבד הוא אלקות ושבו הוא בחי' השתלשלות מחכמה לבינה ומבינה למדות וממדות בדיבור כמשל באדם שמהשכל נמשכי' המדות וממדו' למחשבה או משכל למחשבה וממחשבה למדות כו' הכל בבחי' עילה ועלול, אבל להיות אפי' התהוות עולם הבריא' א\"א להיות בבחי' השתלשלו' שהרי הוא בחי' יש וא\"א להיות מתהוה מאצי' כמו שא\"א להיות התהוות גשמיות מרוחני' כו' אלא דוקא",[["683","24","<b>בלבד</b>: אולי תיבה זו מיותרת."],["684","25","<b>בראשי' ברא אלקי' . . ביום עשות הוי' אלקים . . במחשבה ארץ קדמה</b>: בראשית א, א. ב, ד. חגיגה יב, א. וראה לעיל ד\"ה ביום השמע\"צ."],["685","26","<b>בחכמה יסד ארץ</b>: משלי ג, יט."],["686","27","<b>דאימא עילא' מקננא בכורסייא</b>: תקו\"ז ת\"ו (כג, א). ע\"ח שער סדר אבי\"ע (שמ\"ז) פ\"ג. תניא פל\"ט. ועוד."]]],[2101920160,"מא\"ס ב\"ה הכל יכול כנ\"ל. וכמ\"כ הוא ההפרש בין תלמוד ומשנה כו' לקבלה, כי הנה כל בחי' הנגלה אף המשנה שלא נתלבשה בעשי' גשמיות שהרי עיקר מצות קריאתה בפה הוא, ואפי' התלמוד שהוא רק טעמי ההלכות מ\"ט דר' פלוני כו' מ\"מ בכלל עשי' יחשבו לגבי הקבלה לפי שהם סובבים על עשי' שהרי גם הטעם הוא טעם של העשי' למה יהי' הקרבן כך עד\"מ או שיהי' מעשה החושן ואפוד כך וכך. משא\"כ הקבלה הוא בחי' רוחנית הטעמי' של המצות דהיינו כמו שהן למעלה בבחי' אצילות ואינו שייך לעשי' כלל. וזהו שקבלה באצי', אף שגם קבלה ירדה בזה העולם כנ\"ל היינו רק בחי' ידיעת המציאות בלבד (לאיתני' אשר בארץ המה כרשב\"י ע\"ה ודוגמתו כהאריז\"ל כו') כנ\"ל בענין ההפרש בין מקובלים לנביאים כו' שהרי מהות הטעם של המצוה כמו שהוא באצי' אינו מושג. משא\"כ בתורה הנגלות לנו שמהות הרצון עליון שנתלבש בעשי' גשמיות מושג לנו שנודע שכך רצונו בעשיית מעשה המצוה זו הגשמית כו'. ואמנם באמת שרשן למעלה מקבלה דהיינו בבחי' רצון העליון שלמעלה מהאצי' לכן יכלו לירד ולישפל בבי\"ע שהוא בחי' גשמי' יחשב לגבי אצי' כנ\"ל.\nד. <b>אך</b> הנה בשבת אומרים השתחוו לה' בהדרת קדש, ר\"ת קבלה כי בשבת הוא בחי' עליות העולמות וכמ\"ש ויכולו<sup data-n=\"687\">28</sup> השמים מל' ותכל נפש דוד, שהוגבהו ונתעלו בחי' שמים וארץ בבחי' תענוג ע\"י שראה כל אשר עשה והנה טוב מאד, עד\"מ האדם העוסק באיזה מלאכה כמו ציור וכתב וכיוצא ששכלו ומדותיו נשפלים ומתלבשים בזו המלאכה ולאחר שפוסק מעשות ונח אזי אות' המלאכה מתעלי' לכלל תענוג להיות מתענג ממנה. וזהו ענין ג\"פ הבו עליית ג' עולמות בי\"ע בבחי' אצילות ממש. וזהו ענין בהדרת קדש א\"ת<sup data-n=\"688\">29</sup> בהדרת אלא בחרדת בחי' נורא הוא בחי' ת\"ת הנק' הדר וקדש הוא בחי' אצי' כי בכללות העולמות אצי' הוא חכמה יוד דש' הוי' וכו', והיינו בחי' חרדה וביטול בהתכללותם באצי' ואזי השתחוו לה' ר\"ת קבלה כי בבחי' אצי' הוא ממש השגת המהות דקבלה וגם נודע דקבלה בת\"ת.\n<b>ומזמור</b> לתודה הריעו לה', אומרי' בחול, כי הנה ענין התודה שמודה לאלקות ע\"י דבר שראה בו גילוי אלקותו ית' בביטול היש לאין גשמיות לרוחני' כגון ארבעה<sup data-n=\"689\">30</sup> צריכי' להודות יורדי הים המה<sup data-n=\"690\">31</sup> ראו מעשי ה' יעלו שמי' ירדו תהומות, ויעמד רוח סערה ותרומם גליו ואח\"כ תקום סערה לדממה ויחשו גליהם, וכן חולה שהי' מושכב על מטתו באין כח כשמתרפא ומחליף כח. אך כ\"ז הוא ביטול היש על מצבו ומעמדו באשר הוא שם על מקומו ששם הוא ג\"כ בטל לרוחני', כמו מי הים",[["687","28","<b>ויכולו השמים . . ותכל נפש דוד</b>: בראשית ב, א. שמו\"ב יג, לט ות\"י שם."],["688","29","<b>א\"ת </b> [ אל תקרי]<b> בהדרת אלא בחרדת</b>: ברכות ל, ב."],["689","30","<b>ארבעה צריכי' להודות</b>: ברכות נד, ב."],["690","31","<b>המה ראו מעשי ה' . . ויחשו גליהם</b>: ע\"פ תהלים קז, כד-כט."]]],[2101920161,"שעם היותן בטלי' למאמר ה' אשר שם להם חוק וגבול היינו רק כמו שהם בתמידי' שכך תמיד לא ישנו את תפקידם וכן ריפוי החולה. ולכך אומרי' זה בחול שבחי' ביטול היש לאין הוא בבי\"ע שהנבראי' הם על עמדם ולא נתעלו ושמה הם בטלים, משא\"כ בשבת ביטול היש לאין באופן אחר שמתעלים ממש מבי\"ע לאצי'. וזהו השתחוו לה' כו', הריעו לה' כל הארץ, גשמיות דוקא משום דארץ קדמה במחשבה כנ\"ל. אך ענין הריעו הוא ע\"ד שנודע<sup data-n=\"691\">32</sup> בגמ' ההפרש בין שברים לתרועה שהוא ענין גנוחי גניח וילולי יליל פי' התרועה הוא קולות קצרים ילולי יליל כאדם הבוכה ופוסק בכל רגע שאינו יכול להאריך במשיכת קול בכיותו והיינו מפני שהבכי' היא ממעמקים יותר מעומקא דליבא שאין לו שום כלי להיות נגבל ונתפס בו ומיד שיוצאת התגלות לבו בבחי' בכיה אזי מיד ג\"כ נפסק. וכך יש למעלה ג\"כ בחי' מטי<sup data-n=\"692\">33</sup> ולא מטי שההמשכה היא ממקום גבוה מאד נעלה וא\"א לו להיות בבחי' מטי לגמרי ולהתגלות כולו אלא מיד שנמשך בבחי' מטי אזי מיד מסתלק ולא מטי כי אין כלי מספיקו ולזה נשתבחו ישראל אשרי<sup data-n=\"693\">34</sup> העם יודעי תרועה דוקא.\n<b>וזהו</b> ג\"כ שר\"ת הריעו לה' כל הארץ הוא הלכה, כי ההלכות הם ג\"כ כמו כך שהם פסקי פסקי כל הלכה היא חלק קטן בפ\"ע כענין התרועה הנ\"ל שהם קולות קצרים והיינו משום שא\"א להיות כל השנה כולה ר\"ה להיות תרועה ממש אלא הריעו לה' בבחי' עסק ההלכות שהם ג\"כ כמו תרועה כו', ופי' להוי' להיות עי\"ז המשכת בחי' הוי' וד\"ל.",[["691","32","<b>שנודע בגמ'</b>: ר\"ה לג, ב ואילך."],["692","33","<b>מטי ולא מטי</b>: זח\"ב טז, ב. סה, א."],["693","34","<b>אשרי העם יודעי תרועה</b>: תהלים פט, טז."]]],[2101920162,"<h3>ארדה נא ואראה</h3>\n<b>ארדה</b><sup data-n=\"694\">1</sup> נא ואראה הכצעקתה כו'. ל' ארדה נא פלאי וגם מ\"ש ויגש<sup data-n=\"695\">2</sup> אברהם כו' חלילה לך מעשות כדבר הזה כו'. שלכאורה הוא כהטחת דברים כלפי שמיא, ומה משה שלא אמר רק למה<sup data-n=\"696\">3</sup> הרעות שהכביד פרעה עליהם ביותר אחר שליחותו נענש<sup data-n=\"697\">4</sup> ואמר לו הקב\"ה עתה תראה אבל לא תראה כשיכנסו לארץ למה הרהר אחרי מדותיו כו', ולכאורה אברהם דיבר קשות יותר חלילה לך כו' ולא מצינו שנענש ע\"ז כלל.\n<b>ויובן</b> בהקדים משל א' עפמ\"ש השוחד<sup data-n=\"698\">5</sup> יעור כו' הלא הדיין אינו מורה רק ככתוב בספר. אך הטעם כי מחמת קירוב לבבו אליו אזי נראה לו ענינו",[["694","1","<b>ארדה נא ואראה</b>: וירא יח, כא. המאמר נדפס כאן מגוכי\"ק הצ\"צ. ונמצא בס' מאמרי אדה\"ז עה\"ת ח\"א ע' קכד. ועי' נו\"א בשינויים שם ע' קו ובתו\"א וירא יד, ד."],["695","2","<b>ויגש אברהם כו'</b>: וירא שם כג-כה."],["696","3","<b>למה הרעות</b>: שמות ה, כב."],["697","4","<b>נענש וא\"ל הקב\"ה עתה תראה</b>: ראה שמות ו, א ופירש\"י שם. סנהדרין קיא, א."],["698","5","<b>השוחד יעור</b>: פ' שופטים טז, יט."]]],[2101920163,"באופן אחר ממש כאילו הוא זכאי, כי בכל דבר אם ידינוהו בשכלו יוכל להטותו לב' דברים הפכים, ברצותו יעשה מזה חוב ואיך שהוא מעשה שלא יעשה, וברצותו יצדיקו וישכיל איך שמעשה זו עצמה אינה חוב כלל. ולזה אין<sup data-n=\"699\">6</sup> ב\"ד שקול פחות מג' כי א' כל מגמתו להציל ולזכות והב' בהיפוך והג' מכריע וזה תלוי באיזה עין שכלי יביט עליו אם בעין טובה או בעין רעה. וכדמצינו גם למעלה שמתחלה נאמ' ויתעצב<sup data-n=\"700\">7</sup> אל לבו ויאמר אמחה את האדם כי יצר מחשבות לבו רק רע כו' וא\"כ אין תועלת בו, ואח\"כ כשהריח את ריח הניחוח שהקריב נח ונמתקו הגבורות אזי היפך זה גופא לזכות באמרו וינחם<sup data-n=\"701\">8</sup> כי יצר לב האדם רע מנעוריו פי' וא\"כ<sup data-n=\"702\">9</sup> עליו אשמה כלל והיינו לפי שחקר דינו בעין יפה, שהרי גם מתחלה ידע זה אלא שמצד הגבורו' הי' זה גופא חוב כו', כי הכל תלוי באיזה אופן יחקור דינו שכך יהי' הטייתו מהשכל כו'. והטעם כי הדעת<sup data-n=\"703\">10</sup> כולל חו\"ג פי' שמשכל א' יוכל להיות ב' נטיות אם לחסד אם לגבורה, ומובן למשכיל שענין ב' מדות אלו חו\"ג הנמשכים מן הדעת היינו בחי' מדות שבשכל כלומר שהשינוי הוא בשכל עצמו שכשנוטה כלפי חסד היינו שמשכיל איך שאינו חייב כלל וכשנוטה לדין הוא מה שמשכיל איך שהוא חייב, ואינם שייכי' למדות שבלב שיש שם ג\"כ חו\"ג אבל הם באופן אחר ממש, דהיינו שמצד השכל אין שינוי בין כשהוא בחסד בלב לכשהוא בגבורה ויודע בשכלו שהוא חייב עד\"מ אלא שאעפ\"כ לענין הפסק הוא מתחסד עמו כלומר לו יהי כן מ\"מ אינו חפץ בעונש ומדת הגבו' היא להעמיד הדבר על הדין ויעמיד במשפט תיכף, משא\"כ בחי' מדות שנמשכי' מן הדעת שבחי' החסד הוא שמהפך הדבר בשכל ושמשכיל כאילו אינו חייב כלל, ומדת הגבורה שבדעת היא ג\"כ נטי' בשכל להיפוך. וזה שביקש דוד מלפניך<sup data-n=\"704\">11</sup> משפטי יצא, ולא שביקש חסד לעשות עמו לפנים משה\"ד שהרי משפטי כתי', רק שיצא מלפניך כי בהיותך מלא רחמים תראה עניני באופן אחר ממש ואצא זכאי משא\"כ אם יסתכלו בעין אחר, וכנודע<sup data-n=\"705\">12</sup> שיש ב' עיינין א' מחסד וא' מגבורה ולמעלה יותר כתי' פקח<sup data-n=\"706\">13</sup> עינך חסר כתי' (הגם שבספרי' שלנו הוא מלא מ\"מ לפמ\"ש בזהר כן הוא, ויש כמה שינויים בין ספרי' שלנו לכמ\"ש בזהר כמו בענין כלות<sup data-n=\"707\">14</sup>",[["699","6","<b>אין ב\"ד שקול פחות מג'</b>: ראה סנהדרין ג, ב."],["700","7","<b>ויתעצב אל לבו . . רק רע</b>: ע\"פ בראשית ו, ה ואילך."],["701","8","<b>וינחם כי יצר לב האדם רע מנעוריו</b>: ע\"פ נח ח, כא."],["702","9","<b>וא\"כ עליו</b>: אוצ\"ל וא\"כ אין עליו. או שהר\"ת כאן הוא: ואין כאן."],["703","10","<b>הדעת כולל חו\"ג</b>: ראה ע\"ח שער תיקון הנוקבא (של\"ד) פ\"ג. תניא ספ\"ג. ספמ\"ג. ובכ\"מ."],["704","11","<b>מלפניך משפטי יצא</b>: תהלים יז, ב. וראה גם קונטרס בד קודש ס\"ז."],["705","12","<b>וכנודע שיש ב' עיינין</b>: ראה זח\"ג קל, א."],["706","13","<b>פקח עינך חסר כתי' . . לפמ\"ש בזהר כן הוא</b>: דניאל ט, יח. ראה זח\"ג קכט, ב. קל, א. קלז, א (ובקול ברמה שם). זח\"ב קעז, ב. תו\"ח וירא קג, א. קי, ב. קיח, א. אוה\"ת בהעלותך ע' שצט."],["707","14","<b>כלות משה ובזהר כלת משה חסר כתי'</b>: נשא ז, א. זח\"א רלו, ב. זח\"ב ה, ב. זח\"ג ד, ב. קמח, א. רכו, ב. רנד, ב. תנחומא נשא כו. פסיקתא פ' ויהי ביום כלות. ובפירש\"י נשא שם."]]],[2101920164,"משה ובזהר כלת משה חסר כתי') להיותו כולו רחמים כו' ולית<sup data-n=\"708\">15</sup> שמאלא בהאי עתיקא.\n<b>וזהו</b> ארדה נא ואראה הכצעקתה כו' פי' צעקת' היינו של המקטרג שמעלה דין סדום ומעשיהם הרעי' לפני ה', ולפני מי הוא צועק היינו לפי<sup data-n=\"709\">16</sup> מדת הרחמים כי למדה\"ד אינו צריך לצעוק שבלא\"ה מסכמת עמו אלא שמדה\"ר מעכבת ולזאת הוא צועק שתסכים גם היא, כי אם העון גדול מאד אזי גם עפ\"י מדה\"ר ראוי' לדין.\n<b>ולזה</b> אמר ארדה נא ממעלה למטה בבחי' חסד ואראה כלומר אני אראה בעין שלי היפה הכצעקתה הבאה אלי עשו כי יוכל להיות שלא כן הוא כלומר שעפ\"י החסד יוכלו למצוא זכות בגוף המעשה, וז\"ש מיד ויגש אברהם כו' כי<sup data-n=\"710\">17</sup> אברהם הי' בחי' מרכבה וזהו שנתן לאכול להמלאכים<sup data-n=\"711\">18</sup> מיכאל וגבריאל כו' שהם ג\"כ בחי' מרכבה אלא שהם בחיצונית ואברהם הי' מרכבה בבחי' פנימית ולכן השפיע הוא להם, וכנגד השכינה אמר אל<sup data-n=\"712\">19</sup> נא תעבור כו' שאינו רוצה להיות בבחי' פירוד ח\"ו.\n<b>והנה</b> מתחלה הי' מרכבה לבחי' ש' אדני מקור דבי\"ע ואחר שאמר הקב\"ה ארדה נא כו' שהוא בחי' ש' הוי' שהוא מדה\"ר שנמשך מלמעלה למטה לראות כו' אזי ויגש אברהם פי' שנגש ונתקרב לבחי' שם הוי' המתגלה כי אברהם<sup data-n=\"713\">20</sup> הוא איש החסד ומיד בהגלות נגלות בחי' מדת חסד עליון הנק' הוי' שאמר ארדה נא כו' אזי נגש אברם וקפץ אליו ונעשה מרכבה אז אליו. ולכן אמר אח\"כ חלילה לך כו' והוא המדבר בעד מדת חסד עליון שאליו הוא מרכבה שאותו מדת החסד כו' אומר לבחי' מל' הנק' שופט כל הארץ שמלאה דיני' כי דינא<sup data-n=\"714\">21</sup> דמלכותא דינא, חלילה לך מעשות כדבר הזה להתנהג בדיני' שהוא נגד מדת החסד שלי, כי הבעל יכול למחות באשתו ולהרגיז עליה עד\"מ.",[["708","15","<b>ולית שמאלא בהאי עתיקא</b>: זח\"ג קכט, ב."],["709","16","<b>לפי</b>: אוצ\"ל: לפני."],["710","17","<b>כי אברהם הי' בחי' מרכבה</b>: ראה ב\"ר פמ\"ז, ו."],["711","18","<b>להמלאכים מיכאל וגבריאל כו' שהם ג\"כ בחי' מרכבה</b>: ראה זח\"א צז, ב. זח\"ב רט, ב. רי, א."],["712","19","<b>אל נא תעבור</b>: וירא יח, ג."],["713","20","<b>אברהם הוא איש החסד</b>: ראה זח\"א מז, ב. ובכ\"מ."],["714","21","<b>דינא דמלכותא דינא</b>: גיטין י, ב."]]],[2101920165,"<h3>ענין כי שנואה לאה</h3>\n<b>ענין</b><sup data-n=\"715\">1</sup> כי<sup data-n=\"716\">2</sup> שנואה לאה כו' ויאהב<sup data-n=\"717\">3</sup> את רחל כו', הטעם הוא משום שבחי' לאה היא גבוה מאד במדרגה היינו בחי' אם הבנים שהעמידה ששה שבטים כו' ולכן לא הכירה יעקב שהוא בחי' מדות עליונות שהן למטה מהשכל כי המדות נמשכות מהשכל כמ\"ש לפי<sup data-n=\"718\">4</sup> שכלו יהולל איש וא\"כ השכל עצמו הוא למעלה בערך מהם ושם הוא בחי'<sup data-n=\"719\">5</sup> לאה אלא שהיא בחי' האחרונה שבשכל דהיינו בחי' אותיות המחשבה שהן לבושי השכל וע\"כ נקראת לאה שהוא מלשון עייפות כמו וילאו<sup data-n=\"720\">6</sup> למצוא כו' שהיא נלאה תמיד מחמת שמקבלת ההשפעה בתמידי' בלי הפסק כי המחשבה משוטטת תמיד ואפי' בחלום יחשוב וידמה כו'. ומ\"מ היא למעלה מהמדות שהן למטה מהשכל לגמרי ולכן לא הכירה יעקב משא\"כ רחל הוא בחי' עולם הדיבור שלמטה מבחי' המדות שהוא בחי' יעקב ולכן היתה לאה שנואה כי דבר הנעלם ומופלא מההשגה אינו אהוב ואין בו תענוג כלל משא\"כ מדבר המושג הוא מתענג ולכן היתה רחל אהובה. וזהו שכניסתו את לאה הי' שלא מדעתו כי היא בחי' שלמעלה מהדעת שלו כנ\"ל. אמנם כ\"ז הוא קודם שנשאה אבל אח\"כ הרי נעשה הוא בעל ומשפיע לה והיא נעשי' בחי' מקבל ממנו, והיינו שירדה בחי' המחשבה מכמו שהיתה קודם בחי' לבוש להשכל בלבד ונמשכה למטה להיות מלבשת גם את המדות ונעשית בחי' מקבל מהמדות כו'.",[["715","1","<b>ענין כי שנואה לאה</b>: נדפס כאן מגוכי\"ק הצ\"צ בס' תקע\"ב [מס' 1116]. וראה המאמר בס' מאמרי אדה\"ז עה\"ת ח\"א ע' קסט. וראה גם תו\"ח ויצא כז, ג. וראה בארוכה להלן בד\"ה ורחל היתה יפ\"ת."],["716","2","<b>כי שנואה לאה</b>: ויצא כט, לא."],["717","3","<b>ויאהב את רחל</b>: ע\"פ ויצא כט, יח. ל."],["718","4","<b>לפי שכלו יהולל איש</b>: משלי יב, ח."],["719","5","<b>בחי' לאה . . אותיות המחשבה</b>: ראה ס' מאמרי אדה\"ז עה\"ת ח\"א ע' קנו, ובמ\"מ שם."],["720","6","<b>וילאו למצוא</b>: וירא יט, יא."]]],[2101920166,"<h3>ענין שנא' באמהות שהיו יפ\"ת</h3>\n<b>ענין</b><sup data-n=\"721\">1</sup> שנא' באמהות<sup data-n=\"722\">2</sup> שהיו יפ\"ת ויפ\"מ מה בא משה להשמיענו וכי לפושעים הוא נותן יד ח\"ו שמוכיחי' מכאן הקפדה על היופי כו'. ושלמה סותר דבריו במ\"ש שקר<sup data-n=\"723\">3</sup> החן והבל היופי כו'. אך הענין כי בחי' היופי הוא ג\"כ בשרשן למעלה מהארת הכתר שנמשך ומאיר במל' דוקא כי נעוץ תחלתן בסופן כמשל תגבורת אור השמש",[["721","1","<b>ענין שנא' באמהות</b>: נדפס כאן מגוכי\"ק הצ\"צ בס' תקע\"ב [מס' 1116]. וראה המאמר בס' מאמרי אדה\"ז עה\"ת ח\"א ע' קסח. חלק של המאמר הובא בתוס' הגהות באוה\"ת ויחי תתקצה, א (בתוך ד\"ה שבע עשרה שנה, ועד\"ז נמצא בביאוה\"ז להצ\"צ ח\"ב תשלה, א), ובסיומו כותב: ”ע\"כ מצאתי בשם אדמ\"ו ז\"ל\". וראה המאמר בשינויים ובאריכות בד\"ה ורחל היתה יפ\"ת הנדפס להלן. ובאריכות יותר בתו\"ח ויצא כז, ג. לב, ג."],["722","2","<b>באמהות שהיו יפ\"ת ויפ\"מ</b>: לך יב, יא. יד."],["723","3","<b>שקר החן</b>: משלי לא, ל."]]],[2101920167,"באויר השלישי הסמוך לארץ ביותר מבאויר האמצעי כו'. וכך לפי שבחי' מל' רגליה<sup data-n=\"724\">4</sup> יורדות לכן צריכה חיזוק מלמעלה יותר והוא ענין י\"ג מדה\"ר שנמשכים במל' ולכך גם למטה בטבע הבריאה הנשים יפים מהאנשים, ולכן חשקו השרים<sup data-n=\"725\">5</sup> פרעה ואבימלך בהם, והעיקר הי' בשרשם למעלה שהן השרים שלהם שלמעלה שחשקו<sup data-n=\"726\">6</sup> לקבל יניקה מהם וכמ\"ש במ\"א ויראו<sup data-n=\"727\">7</sup> אותה שרי פרעה ויהללו אותה שרי<sup data-n=\"728\">8</sup> פרעה שהן<sup data-n=\"729\">9</sup> ב' שמות הוי' א' כסדרו וא' למפרע שהיו בה כו'. וכך היא דרכה של תורה שתוכן רצוף ענינים פנימיים העומדים ברומו של עולם והקורא בתורה וסובר שהם סיפורי מעשיות כפשוטן כתב<sup data-n=\"730\">10</sup> ע\"ז בס' א' שאינו מקבל שכר ע\"ז כלל. והנה הלא<sup data-n=\"731\">11</sup> היא כתובה על ספר הישר הכונה על ס' בראשית, שקודם לתורה, כי כל הד' ספרים הם גופי תורה בביאורי המצות ויש בהם ב' קוין ימין ושמאל עשין ול\"ת זה כנגד זה משא\"כ ס' בראשית הוא בבחי' יושר וכולו בבחי' א', ולכן ארז\"ל יפה<sup data-n=\"732\">12</sup> שיחתן של עבדי אבות מתורתן של בנים כו'.\n<b>וההפרש</b> שבין תואר למראה הוא כי היופי בתואר היינו ענין הסידור נכון בבנין האברים במזיגה שלא יעדיף מדת הא' או יקצר מדתו מכמו הראוי להיות לפי מדת האברים האחרים אלא יהיו כולם שקולים וכן בד' החושים ראי' שמיעה ריח דבור יהיו כולם במזיגה ולא יהי' א' רפה והשני חזק יותר לפי ערך ממנו, ולמעלה היינו בחי' המזיגה בספי' עליונות חסד<sup data-n=\"733\">13</sup> דרועא ימינא גבורה דרועא שמאלא כו' שיהי' כחו של זה כפי הראוי להיות נגד שלעומתו. והיופי במראה היינו בחי' ההידור בקלסתר פנים והוא בחי' המקיפים (שהרי מה שאין לו קלסתר פנים עכ\"ז אין שינוי בעצם מזיגת האיברים אלא ההידור הוא רק השראת המקיף כו').",[["724","4","<b>רגליה יורדות</b>: שם ה, ה."],["725","5","<b>השרים</b>: באוה\"ת שם ליתא תיבה זו."],["726","6","<b>שחשקו לקבל יניקה מהם וכמ\"ש במ\"א</b>: ראה ד\"ה ויראו אותה שרי פרעה, נדפס בתו\"ח לך לך צא, א. ובאוה\"ת לך לך עב, ב. [והוא ג\"כ משנת תקע\"ב, ונאמר לפני מאמר זה — ראה לקמן בסוף הס' ברשימת מאמרי תקע\"ב]."],["727","7","<b>ויראו אותה</b>: לך לך יב, טו."],["728","8","<b>שרי פרעה (השני)</b>: בכתוב: ויהללו אותה אל פרעה. [ובאוה\"ת שם ליתא תיבות אלו]."],["729","9","<b>שהן ב' שמות הוי'</b>: ראה תו\"ח לך לך צא, ב שם (בשם לקו\"ת להאריז\"ל). וראה ש\"ך עה\"ת כאן. פני דוד להחיד\"א ל\"ך סי' טו\"ב."],["730","10","<b>כתב ע\"ז בס' א'</b>: ראה ס' דגל מחנה אפרים פ' וישב בתחילתו. (זח\"ג קמט, ב. קנב, א) ובכ\"מ."],["731","11","<b>הלא היא כתובה על ספר הישר הכונה על ס' בראשית</b>: יהושע י, יג. ע\"ז כה, א."],["732","12","<b>יפה שיחתן</b>: ב\"ר פ\"ס, ח."],["733","13","<b>חסד דרועא ימינא</b>: תקו\"ז בהקדמה (יז, א)."]]],[2101920168,"<h3><i>נוסח אחר</i>: ורחל היתה יפ\"ת</h3>\n<b>ורחל</b><sup data-n=\"734\">1</sup> היתה יפ\"ת ויפ\"מ<sup data-n=\"735\">2</sup> וכן ברבקה כתיב והנערה<sup data-n=\"736\">3</sup> טובת מראה כו', ובשרה נאמר ג\"כ יפ\"מ כו', ולכאורה אין לזה טעם כלל כי מה זאת מעלה יתירה ברוחני' כו', ועוד שהרי שלמה המע\"ה אמר להיפוך להשפיל מעלת החן והיופי כמ\"ש שקר החן<sup data-n=\"737\">4</sup> והבל היופי וכתיב נזם<sup data-n=\"738\">5</sup> זהב באף חזיר אשה יפה וסרת טעם כו'. אך הנה יש להקדים במ\"ש יעקב אעבדך<sup data-n=\"739\">6</sup> שבע שנים ברחל בתך ולמה לא בלאה, ולמה ז' שנים כי אולי אם הי' מתחייב א\"ע בב' וג' שנים הי' לבן מתרצה בכך ולמה מעצמו קיבל ע\"ע ז' שנים כו'. אמנם הנה ידוע בשרש בחי' יעקב ולאה ורחל למעלה שיעקב<sup data-n=\"740\">7</sup> פי' יו\"ד עקב בחי' הארת סוף מדריגת השכל במדות אשר בחכ'<sup data-n=\"741\">8</sup> אתברירו כו', והנה בחי' רחל<sup data-n=\"742\">9</sup> הוא בחי' עלמא דאתגלייא עולם הדיבור<sup data-n=\"743\">10</sup> כידוע ע\"כ אהב יעקב להשפיע לרחל לבא בבחי' הגילוי, והוא בחי' ז' שנים עילאין שהי' עובד ללבן העליון בעבור רחל נגד ז' מדות כו' ע\"ד שנאמר שש<sup data-n=\"744\">11</sup> שנים תזרע שדך כו' כי אין<sup data-n=\"745\">12</sup> נותנין לאדם פרנסה רק בשביל אשתו, אבל בשביל לאה לא רצה לעבוד כלל כי לא הכיר יעקב ולא השיג במעלת ומדריגת נשמת לאה להיותה למעלה הימנו במדריגה וכל דבר המופלא ונעלם מן ההשגה אין לו אהבה ותשוקה אלי', אדרבה יוכל להיות שיפול שנאה בלבבו על אותו הדבר, וז\"ש כי<sup data-n=\"746\">13</sup> שנואה לאה כי לאה היא בחי' עלמא דאתכסייא בהעלם ע\"כ היא שנואה, עד\"מ אדם שמשיג איזו שכל בלימודו מתענג בו ובאהבתה<sup data-n=\"747\">14</sup> ישגה תמיד, אבל כשאינו משיגו שכלו קץ בו עד ששנאוי הדבר היפך העונג כו' וד\"ל.\n<b>ושרש</b> הדברים הוא כי לאה<sup data-n=\"748\">15</sup> הוא בחי' עולם המח' כידוע שהוא תענוג תמידי שאינו תענוג אלא צער, וע\"כ נק' לאה<sup data-n=\"749\">16</sup> ל' נלאה כמו ונלאו<sup data-n=\"750\">17</sup> לשתות מים כו', ולאה בה\"א בחי' נוק' הרי ענין הנלאה הוא בבחי' מקבל ולא בבחי'",[["734","1","<b>ורחל היתה יפ\"ת</b>: נוסח ב' ממאמרים הקודמים (ד\"ה ענין שנא' באמהות וד\"ה ורחל היתה יפ\"ת). וראה בארוכה ד\"ה זה בתו\"ח ויצא כז, ג ואילך."],["735","2","<b>ורחל היתה יפ\"ת ויפ\"מ</b>: ויצא כט, יז."],["736","3","<b>והנערה טובת מראה . . ובשרה נאמר</b>: חיי שרה כד, טז. לך יב, יא. יד. וראה נח יא, כט."],["737","4","<b>שקר החן והבל היופי</b>: משלי לא, ל."],["738","5","<b>נזם זהב באף חזיר</b>: משלי יא, כב."],["739","6","<b>אעבדך שבע שנים</b>: ויצא כט, יח."],["740","7","<b>שיעקב פי' יו\"ד עקב</b>: ע\"ח שער סדר אצי' (ש\"ג) פ\"ב. תו\"א ר\"פ ויצא. ובכ\"מ."],["741","8","<b>בחכ' אתברירו</b>: ראה אגה\"ק סכ\"ח. זהר (היכלות) פקודי רנד, סע\"ב. הנסמן במאמרי אדהאמ\"צ דברים ח\"א ע' רצה."],["742","9","<b>רחל . . עלמא דאתגלייא</b>: ראה זח\"א קנב, א. ע\"ח שער מוחין דצלם (שכ\"ג) פ\"ד."],["743","10","<b>רחל . . עולם הדיבור</b>: ראה ע\"ח שער אח\"פ (ש\"ד) פ\"א. מאמרי אדהאמ\"צ ויקרא ח\"א ע' רכז. וש\"נ."],["744","11","<b>שש שנים תזרע שדך</b>: בהר כה, ג."],["745","12","<b>אין נותנין לאדם פרנסה</b>: ראה ב\"מ נט, א. מאמרי אדהאמ\"צ בראשית ע' שו."],["746","13","<b>כי שנואה לאה</b>: ויצא כט, לא."],["747","14","<b>ובאהבתה ישגה תמיד</b>: ע\"ד משלי ה, יט."],["748","15","<b>לאה . . עולם המח'</b>: ראה גם מאמרי אדהאמ\"צ בראשית ע' תקמו. וש\"נ."],["749","16","<b>לאה ל' נלאה</b>: ראה גם לקו\"ת להאריז\"ל ס\"פ תולדות. שערי אורה שער החנוכה ז, א. ובכ\"מ."],["750","17","<b>ונלאו לשתות מים</b>: ע\"פ וארא ז, יח [ובתו\"ח כאן (כח, א): וילאו]."]]],[2101920169,"משפיע דהיינו שהמקבל נלאה לקבל מפני בחי' תמידות הקבלה ע\"כ נלאה לקבל התענוג תמידי שבשפע, עד\"מ תלמיד המקבל מרבו שכל נפלא אעפ\"י שמתענג בו מאד כמו ר\"ע<sup data-n=\"751\">18</sup> שזלגו עיניו דמעות כו' וכה\"ג, מ\"מ אין זה רק כאשר מקבל לפרקי' כמו קביעת עת בוקר וערב וכה\"ג, אבל כאשר משפיע לו תמיד מן הבוקר ועד הערב ועד בכלל בלי הפסק כלל וכלל אז נהפך התענוג לצער גדול כי נלאה המקבל מאוד לקבל התענוג הזה להיותו תמידי בלי הפסק, ע\"כ תענוג<sup data-n=\"752\">19</sup> תמידי אינו תענוג בין במשפיע בין במקבל, כי גם שיותר<sup data-n=\"753\">20</sup> שהעגל רוצה לינק הפרה רוצה כו' מכ\"מ לא שמתענג המשפיע כששופע בתמידות רק דוקא כשמשפיע לפרקי' רחוקי' יותר כו', אך מ\"מ אין המשפיע נלאה בהשפעתו אלא המקבל הוא שנלאה לקבל בתמידות (ומ\"ש שלש<sup data-n=\"754\">21</sup> הנה לא תשבענה ארץ<sup data-n=\"755\">22</sup> לא שבעה מים דמלבד שלא נלאה הארץ לקבל אלא שלא תשבע מים של המשפיע וכן מ\"ש כל<sup data-n=\"756\">23</sup> הנחלים הולכים אל הים כו' והים איננו מלא כו', כל זה מדבר לעתיד דוקא דכתי' א\"ח<sup data-n=\"757\">24</sup> עט\"ב נקבה<sup data-n=\"758\">25</sup> תסובב גבר כו'). ויובן דבר זה בבחי' המחשבות שבאדם, דהנה אנו רואים שמח' משוטטת תמיד באדם בלי הפסק כלל וכלל אפי' רגע חדא שהרי כל שעה ורגע המח' תחשוב בכל הדברים שעולה על השכל והלב וכל מה שעיניו רואות ואזניו שומעות כו' הכל מהרהר במח' ואין לה מנוחה אפי' רגע וא\"א שיהי' האדם פנוי אפי' רגע מלחשוב מאומה, וגם בשעת השינה ששכלו ומדותיו ועיניו ואזניו סתומים ונאלמים כו' מ\"מ אין המח' פנוי' כלל שהרי החלומות<sup data-n=\"759\">26</sup> הן מעין הרהורא דלבא שביום, וידוע שכל דמיונות וחלומות<sup data-n=\"760\">27</sup> שבשינה הכל הוא מבחי' אותיות המח' רק שהוא מבחי' האחרונה שבמח' שנק' כח המדמה שבמח' כו', וע\"כ נק' המח' בשם לאה ל' נלאה לפי שהמח' היא תמיד בבחי' מקבל מהשכל בלי הפסק כלל, וגם שיש תענוג בכל הדברים העולים ומתקבלים במח' מ\"מ נלאה המח' לקבל מפני תמידות הקבלה כמשל הנ\"ל בתלמיד היושב לפני רבו כו', והעיקר מפני שהוא תענוג תמידי שנלאה המקבל לקבל תענוג תמידי כו' וד\"ל.\n<b>ובכ\"ז</b> יובן למעלה בבחי' מח' העליונה שבאצי' שנק' לאה למעלה שהן בחי' אותיות מחשבותיו ית', גם שנאמר כי<sup data-n=\"761\">28</sup> לא מחשבותי מחשבותיכם כו' שכל",[["751","18","<b>ר\"ע שזלגו עיניו דמעות</b>: ראה במאמרי אדהאמ\"צ דברים ח\"ג ע' א'קכג. וש\"נ."],["752","19","<b>תענוג תמידי אינו תענוג</b>: מובא בלקוטי אמרים להה\"מ סקס\"ח [הוצאת קה\"ת, מא, ב] בשם הבעש\"ט."],["753","20","<b>שיותר שהעגל רוצה לינק</b>: ראה פסחים קיב, א. מאמרי אדהאמ\"צ דברים ח\"א ע' רפז. וש\"נ."],["754","21","<b>שלש הנה לא תשבענה</b>: משלי ל, טו."],["755","22","<b>ארץ לא שבעה מים</b>: משלי שם, טז."],["756","23","<b>כל הנחלים הולכים אל הים</b>: קהלת א, ז."],["757","24","<b>א\"ח עט\"ב</b>: משלי יב, ד."],["758","25","<b>נקבה תסובב גבר</b>: ירמי' לא, כא."],["759","26","<b>החלומות הן מעין הרהורא דלבא</b>: ראה ברכות נה, סע\"ב. מאמרי אדהאמ\"צ ח\"ד ע' א'תפ. וש\"נ."],["760","27","<b>וחלומות שבשינה . . כח המדמה</b>: ראה שמונה פרקים להרמב\"ם פ\"ב. תו\"א וישב כח, ג. ובכ\"מ."],["761","28","<b>כי לא מחשבותי</b>: ישעי' נה, ח."]]],[2101920170,"בחי' אורות עליונים דא\"א וע\"י וחו\"ב כו' הכל עולין במח' בבחי' משפיע והמח' בחי' מקבל בתמידות, ע\"כ נק' לאה ל' נלאה שנלאה לקבל תענוג תמידי, כיחוד עליון דאו\"א<sup data-n=\"762\">29</sup> דזיווגייהו תדיר בלי הפסק כלל דלא<sup data-n=\"763\">30</sup> מתפרשין לעלמין כידוע שחו\"ב הוא שפע האור מאין ליש בתמידות דוקא ע\"כ גם המח' שבה מזדווגין (כנראה בחו\"ש שא\"א להביא שכל מן ההעלם לגילוי השגה דבינה מאין ליש רק במח' דוקא שבה נתפסת ההשגה של המושכל כו') נלאה מפני תמידות הקבלה כנ\"ל וד\"ל.\n<b>והנה</b> מעתה יש להבין למה לא הכיר וידע יעקב במעלת ומדריגת בחי' לאה מאחר שהמח' היא בחי' מקבל בגילוי אותיות כפי' הנ\"ל ולמה לא אמר אעבדך בלאה ז' שנים כמו שאמר ברחל. אך הנה ב' מדריגות יש בבחי' לאה, הא' למעלה מבחי' יעקב אשר ע\"כ לא הכיר והשיג בה כלל, והב' למטה מבחי' יעקב אשר נעשית לאה בחי' מקבל מיעקב כשנשא אותה ודוקא לאה<sup data-n=\"764\">31</sup> ילדה ששה בנים כו'. כי הנה לפעמים אמר בע\"ח<sup data-n=\"765\">32</sup> דלאה היא רק בחי' אחוריים דאימא והוא ענין קשר של תש\"ר בד' כו', ולפעמים משמע דלאה<sup data-n=\"766\">33</sup> היא בחי' בינה אם<sup data-n=\"768\">35</sup> הבנים<sup data-n=\"767\">34</sup> ממש כו', להיות ידוע דבינה היא מקור המדות ממש כנראה בחוש שהתינוק ששכלו קטן מדותיו קטנים וכששכלו גדול מדותיו גדולים, ולכאורה אין שייכות למדות עם השכל עד שגידולם תלוי זה בזה, אך מ\"מ גידול המדות תלוי בגידול השכל מפני שמקור חוצבם הוא מן השכל דוקא, ואמנם ודאי שאין השכל הבא בהתפעלות המדות משיג לעצם השכל דבינה שמשם מקור חוצבם כמו שכל עלול לא ישיג עילתו כו', ואעפ\"י שהשגה דבינה מובדל מן המדות מ\"מ בבחי' העלם מאיר למדות והוא הנק' עלמא דאתכסי', וע\"ז אמר דלאה היא בחי' בינה אם הבנים ונק' ג\"כ מח', אבל היא גם בהיותה בחי' היותר אחרונה שבחכ' שנק' מחשבת שכל מ\"מ למעלה היא מבחי' המדות ואין למדות השגה בעצם מהותה כו', וזהו בחי' יעקב שהן בחי' המדות לא הכיר והשיג במעלת נשמת לאה כלל להיותה למעלה הימנו כנ\"ל. אבל המדריגה הב' דלאה הוא בחי' אחוריים וחיצוני' דבינה דלמטה מבחי' יעקב, דהיינו כאשר יורדת המח' מלהיות לבוש לחכ' כו' למטה מטה להיות לבוש וכלי בית קיבול למדות שבלב, כמו עד\"מ המהרהר במח' מה שלבו חפץ שכל פרט מן המדות שבלב מאירים ומשפיעים במח' ואותיות המח' מגבילים ומקבלים אותם, כידוע שכמו שהמח' בחי' בית קיבול ולבוש לחו\"ב כנ\"ל",[["762","29","<b>דאו\"א דזיווגייהו תדיר</b>: ראה זח\"ג רצ, ב. מאמרי אדהאמ\"צ בראשית ע' שנו. וש\"נ."],["763","30","<b>דאו\"א . . דלא מתפרשין לעלמין</b>: ראה זח\"ב בשלח נו, א. זח\"ג ד, א. מאמרי אדהאמ\"צ בראשית ע' א. וש\"נ."],["764","31","<b>לאה ילדה ששה בנים</b>: ויצא ל, כ."],["765","32","<b>אמר בע\"ח דלאה . . אחוריים דאימא . . קשר של תש\"ר</b>: ראה שער יעקב ולאה (של\"ו) פ\"ד. לקו\"ת להאריז\"ל ס\"פ תולדות ופ' ויצא. מאמרי אדהאמ\"צ דברים ח\"א ע' רפג."],["766","33","<b>דלאה . . בינה</b>: לקו\"ת להאריז\"ל פ' ויצא שם. ובכ\"מ."],["768","35","<b>בינה אם הבנים</b>: ראה זח\"א ריט, א. ובכ\"מ."],["767","34","<b>דלאה . . אם הבנים</b>: ראה זח\"א קנד, סע\"א. קנז, ב."]]]]});
